const MAX_PROCESS_CPU_SECONDS: u64 = 10 * 365 * 24 * 60 * 60;
const MAX_PROCESS_LAUNCHER_ARGS: usize = 32;
const MAX_PROCESS_LAUNCHER_ARG_BYTES: usize = 4 * 1024;
const MAX_PROCESS_LAUNCHER_TOTAL_BYTES: usize = 64 * 1024;
