const MAX_BACKUP_ENTRIES: usize = 1_000_000;
const EVENT_LOG_MAGIC: &[u8] = b"ASPLOG\0";
const EVENT_LOG_VERSION: u16 = 2;
const EVENT_LOG_LEGACY_VERSION: u16 = 1;
const SNAPSHOT_MAGIC: &[u8] = b"ASPSNAP\0";
const SNAPSHOT_VERSION: u16 = 1;
const BACKUP_MANIFEST_VERSION: u16 = 1;
const WORKSPACE_MAX_FILES: usize = 20_000;
const WORKSPACE_SEARCH_FILE_MAX_BYTES: u64 = 1024 * 1024;
const WORKSPACE_MAX_SEARCH_HITS: usize = 2_000;
const WORKSPACE_SELECTED_FILES_MAX_BYTES: u64 = 32 * 1024 * 1024;
const WORKSPACE_RESPONSE_MAX_BYTES: u64 = 64 * 1024 * 1024;
// A watcher-backed tree index is a performance hint, never the only source
// of truth. Entries older than this are rebuilt even when no native event was
// observed, which bounds the impact of a platform watcher that coalesces or
// loses notifications. If the watcher is unavailable, the fast path is
// disabled and every query falls back to a fresh bounded scan.
const WORKSPACE_INDEX_MAX_AGE: Duration = Duration::from_secs(2);
const MAX_WORKSPACE_INDEXES: usize = 128;
// notify invokes its callback on a backend-owned thread. Keep the hand-off
// bounded so a filesystem event storm cannot turn the watcher bridge into an
// unbounded allocation. If the queue fills, the cache is disabled and queries
// fall back to a fresh bounded scan; correctness never depends on delivery of
// every individual notification.
const WORKSPACE_WATCHER_QUEUE_CAPACITY: usize = 4096;
// External editor/build changes are journaled through a second bounded hand-
// off. The native watcher remains an optimization: if this queue fills, the
// cache is disabled and a later semantic query performs a fresh scan. Keeping
// the queue separate from notify's result queue prevents event payloads from
// blocking the backend thread while the journal worker is fsyncing.
const WORKSPACE_FILE_EVENT_QUEUE_CAPACITY: usize = 1024;
const WORKSPACE_FILE_EVENT_COALESCE: Duration = Duration::from_millis(50);
const WORKSPACE_FILE_EVENT_OBSERVATION_LIMIT: usize = 4096;
