// a watcher must not turn a large generated file into unbounded background
// work. Files above this threshold use size/mtime identity instead.
const WORKSPACE_FILE_EVENT_HASH_MAX_BYTES: u64 = 16 * 1024 * 1024;
// Search results are a cache hint just like the tree. Keep the aggregate
// retained result memory bounded independently of the response/frame budget;
// large or unusually broad searches simply remain uncached.
const WORKSPACE_SEARCH_CACHE_MAX_ENTRIES: usize = 64;
const WORKSPACE_SEARCH_CACHE_ENTRY_MAX_BYTES: usize = 4 * 1024 * 1024;
const WORKSPACE_SEARCH_CACHE_MAX_BYTES: usize = 32 * 1024 * 1024;
