const WORKSPACE_FILE_MEMORY_WAIT: Duration = Duration::from_millis(250);
const WORKSPACE_SEARCH_LINE_MAX_BYTES: usize = 8 * 1024;
const WORKSPACE_SEARCH_MAX_BYTES: u64 = 8 * 1024 * 1024;
const WORKSPACE_INDEX_PATH_MAX_BYTES: u64 = 32 * 1024 * 1024;
const PATH_MAX_BYTES: usize = 4 * 1024;
const QUERY_TERM_MAX_BYTES: usize = 4 * 1024;
const PTY_INPUT_MAX_BYTES: usize = 64 * 1024;
const PTY_MAX_DIMENSION: u16 = 500;
// portable-pty exposes a synchronous writer.  A suspended or non-reading
// terminal can therefore apply backpressure to the PTY master; never let that
// write pin a Tokio reactor worker.  The bounded timeout also turns a wedged
// terminal into a reconnectable attachment failure instead of an immortal
// request task.  Durable session state and the tmux owner remain intact.
const PTY_INPUT_WRITE_TIMEOUT: Duration = Duration::from_secs(10);
// PTY DATAGRAMs carry replaceable current-screen state.  Limit publication
// to a terminal-friendly frame rate so a compiler/test flood does not rebuild
// and retransmit a full screen for every output chunk.  Reliable PTY output
// remains lossless and is still forwarded immediately.
const PTY_DATAGRAM_INTERVAL: Duration = Duration::from_millis(16);
// Base-relative PTY state is replaceable and therefore cannot rely on a
// datagram ACK.  Emit a full snapshot at least this often so one lost delta
// cannot leave a client stale indefinitely; a reconnect or reliable lag
// snapshot resets the same counter immediately.
const PTY_DELTA_FULL_INTERVAL: u8 = 16;
// A terminal screen is replaceable state. Persist a coarse generation marker
// rather than one WAL event per PTY output chunk; the reliable PTY byte stream
// remains lossless, while this interval bounds journal churn during compiler
// or test floods and still gives reconnects a recent generation validator.
const PTY_EVENT_PERSIST_INTERVAL: Duration = Duration::from_millis(100);
const EVENT_SUBSCRIBER_CAPACITY: usize = 256;
const MAX_ACTIVE_SUBSCRIPTIONS_PER_SESSION: usize = 64;

