static PTY_STATE_DATAGRAMS_SENT_TOTAL: AtomicU64 = AtomicU64::new(0);
static PTY_STATE_DATAGRAM_BYTES_TOTAL: AtomicU64 = AtomicU64::new(0);
static PTY_STATE_DATAGRAMS_COMPRESSED_TOTAL: AtomicU64 = AtomicU64::new(0);
static PTY_STATE_DATAGRAMS_SKIPPED_TOTAL: AtomicU64 = AtomicU64::new(0);
static PTY_STATE_DELTA_DATAGRAMS_SENT_TOTAL: AtomicU64 = AtomicU64::new(0);
static PTY_STATE_DELTA_DATAGRAM_BYTES_TOTAL: AtomicU64 = AtomicU64::new(0);
static PTY_STATE_DELTA_DATAGRAMS_SKIPPED_TOTAL: AtomicU64 = AtomicU64::new(0);
static PTY_INPUT_WRITE_TIMEOUTS_TOTAL: AtomicU64 = AtomicU64::new(0);
static PROCESS_OUTPUT_ATTACHMENT_DETACHES_TOTAL: AtomicU64 = AtomicU64::new(0);
static PROCESS_TIMEOUTS_TOTAL: AtomicU64 = AtomicU64::new(0);
static PROCESS_OUTPUT_LIMIT_TERMINATIONS_TOTAL: AtomicU64 = AtomicU64::new(0);
