static PROCESS_LOG_SYNC_TOTAL: AtomicU64 = AtomicU64::new(0);
static PROCESS_LOG_SYNC_BYTES_TOTAL: AtomicU64 = AtomicU64::new(0);
static PROCESS_LOG_SYNC_DURATION_US_TOTAL: AtomicU64 = AtomicU64::new(0);
static PROCESS_LOG_SYNC_FAILURES_TOTAL: AtomicU64 = AtomicU64::new(0);
static AUTHENTICATION_TIMEOUTS_TOTAL: AtomicU64 = AtomicU64::new(0);
