static WORKSPACE_FILE_EVENT_DROPS_TOTAL: AtomicU64 = AtomicU64::new(0);
// QUIC stateless retry is a transport-level address-validation guard.  It is
// enabled automatically by the fail-closed production profile (and can be
// opted into for development) so spoofed Initial packets cannot make the
// daemon spend TLS/application resources before the peer proves it can receive
// traffic at its source address.  Quinn owns the token cryptography; these
// counters only make the operator-visible tradeoff measurable.
static QUIC_STATELESS_RETRIES_TOTAL: AtomicU64 = AtomicU64::new(0);
static QUIC_STATELESS_RETRY_FAILURES_TOTAL: AtomicU64 = AtomicU64::new(0);
// The retry counters above are process-wide observability totals. Keep the
// effective configuration in a separate gauge so a zero counter is not
// ambiguous on a loopback-only daemon where Quinn may validate the initial
// address without sending a retry.
static QUIC_STATELESS_RETRY_ENABLED: AtomicBool = AtomicBool::new(false);

#[derive(Debug, Clone, Copy, Default)]
struct ProcessResourceUsage {
    cpu_time_us: u64,
    max_rss_bytes: u64,
}

#[derive(Debug, Clone, Copy, Default)]
struct CgroupResourceUsage {
    /// Current memory charged to the daemon's cgroup, including descendants.
    memory_current_bytes: u64,
    /// Configured memory ceiling. Zero means the cgroup reports `max` or is
    /// unavailable; it is intentionally not confused with a zero-byte limit.
    memory_limit_bytes: u64,
    /// Aggregate cgroup CPU consumption in microseconds.
    cpu_usage_us: u64,
    /// Current/maximum process count. A zero maximum means `pids.max=max` or
    /// that the host does not expose a cgroup-v2 controller.
    pids_current: u64,
    pids_limit: u64,
}

/// Optional per-command limits inherited by the shell and all descendants.
/// A zero value leaves that resource unlimited; deployments should normally
/// combine these limits with a supervisor cgroup (the supplied systemd unit
/// already has one).  The limits are applied in the child just before exec so
/// they cannot consume daemon address space or CPU while being installed.
/// Linux children also default to `no_new_privs`, which prevents setuid and
/// file-capability privilege gains from an otherwise untrusted workspace
/// command.  A caller may explicitly opt out for a trusted launcher that
/// requires privilege transitions; that mode is never implicit.
#[derive(Debug, Clone, Copy)]
struct ProcessLimits {
    memory_bytes: u64,
    cpu_seconds: u64,
    exec_timeout_seconds: u64,
    no_new_privs: bool,
}

// The platform-specific secure default cannot be expressed with `derive`:
// Linux enables no_new_privs while other targets leave the field false.
#[allow(clippy::derivable_impls)]
impl Default for ProcessLimits {
    fn default() -> Self {
        Self {
            memory_bytes: 0,
            cpu_seconds: 0,
            exec_timeout_seconds: 0,
            no_new_privs: cfg!(target_os = "linux"),
        }
    }
}

/// Optional external boundary for EXEC/SPAWN. ASP deliberately does not
/// implement a sandbox: a configured launcher is an operator-supplied,
/// absolute-path executable such as `bwrap`, `systemd-run`, or a site wrapper
/// that must `exec` its arguments so PID identity and signal semantics remain
/// observable to the durable monitor. The same launcher is applied to tmux
/// when a PTY is opened, so a fail-closed production profile cannot bypass the
/// configured worker boundary through the interactive shell path.
#[derive(Debug, Clone, Default)]
struct ProcessLauncher {
    program: Option<PathBuf>,
    args: Vec<String>,
    required: bool,
    identity: Option<ProcessLauncherIdentity>,
}

/// Identity captured for an operator-supplied process boundary. A path check
/// at daemon startup is not enough: replacing the executable with an atomic
/// rename while aspd is running must not silently alter the isolation policy.
/// Unix device/inode fields catch same-path replacement; size/mtime provide a
/// conservative fallback on platforms without those fields. Launcher paths
/// are canonicalized once at startup so a symlinked parent cannot be swapped
/// to redirect later process launches.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct ProcessLauncherIdentity {
    size: u64,
    modified_unix_nanos: Option<u128>,
    #[cfg(unix)]
    device: u64,
    #[cfg(unix)]
    inode: u64,
}

/// Read inexpensive, process-local resource counters for health/metrics.
/// `getrusage` is supplied by the host OS and does not spawn a helper or do
/// filesystem I/O on the Tokio reactor. Peak RSS is reported because it is
/// the portable quantity exposed by this API; cgroup/container metrics remain
/// the authority for current and child-process memory.
fn process_resource_usage() -> ProcessResourceUsage {
    #[cfg(unix)]
    {
        let mut raw = std::mem::MaybeUninit::<libc::rusage>::zeroed();
        // SAFETY: getrusage writes the complete rusage structure when it
        // returns zero, and the pointer is valid for the duration of the call.
        let result = unsafe { libc::getrusage(libc::RUSAGE_SELF, raw.as_mut_ptr()) };
        if result != 0 {
            return ProcessResourceUsage::default();
        }
        // SAFETY: success from getrusage initialized every field of `raw`.
        let raw = unsafe { raw.assume_init() };
        let user_us = timeval_to_micros(raw.ru_utime);
        let system_us = timeval_to_micros(raw.ru_stime);
        ProcessResourceUsage {
            cpu_time_us: user_us.saturating_add(system_us),
            max_rss_bytes: max_rss_bytes(raw.ru_maxrss),
        }
    }
    #[cfg(not(unix))]
    {
        ProcessResourceUsage::default()
    }
}

/// Read cgroup-v2 counters when the daemon is launched under a Linux service
/// manager/container. These are intentionally best-effort: macOS and hosts
/// without a mounted cgroup filesystem return zeros, while systemd's
/// `MemoryMax`/`TasksMax` values become visible in `/metrics` without adding a
/// helper process or trusting a child-reported value.
fn cgroup_resource_usage() -> CgroupResourceUsage {
    #[cfg(target_os = "linux")]
    {
        let Some(root) = cgroup_v2_path() else {
            return CgroupResourceUsage::default();
        };
        let memory_current_bytes = read_cgroup_u64(&root.join("memory.current"));
        let memory_limit_bytes = read_cgroup_limit(&root.join("memory.max"));
        let cpu_usage_us = std::fs::read_to_string(root.join("cpu.stat"))
            .ok()
            .and_then(|contents| {
                contents.lines().find_map(|line| {
                    let mut fields = line.split_whitespace();
                    (fields.next() == Some("usage_usec"))
                        .then(|| fields.next().and_then(|value| value.parse().ok()))
                        .flatten()
                })
            })
            .unwrap_or_default();
        let pids_current = read_cgroup_u64(&root.join("pids.current"));
        let pids_limit = read_cgroup_limit(&root.join("pids.max"));
        CgroupResourceUsage {
            memory_current_bytes,
            memory_limit_bytes,
            cpu_usage_us,
            pids_current,
            pids_limit,
        }
    }
    #[cfg(not(target_os = "linux"))]
    {
        CgroupResourceUsage::default()
    }
}

#[cfg(target_os = "linux")]
fn cgroup_v2_path() -> Option<&'static Path> {
    static PATH: OnceLock<Option<PathBuf>> = OnceLock::new();
    PATH.get_or_init(|| {
        let contents = std::fs::read_to_string("/proc/self/cgroup").ok()?;
        let relative = contents.lines().find_map(|line| {
            let path = line.strip_prefix("0::")?;
            let path = path.trim();
            path.starts_with('/').then(|| path.trim_start_matches('/'))
        })?;
        let root = PathBuf::from("/sys/fs/cgroup").join(relative);
        root.is_dir().then_some(root)
    })
    .as_deref()
}

#[cfg(target_os = "linux")]
fn read_cgroup_u64(path: &Path) -> u64 {
    std::fs::read_to_string(path)
        .ok()
        .and_then(|value| value.trim().parse().ok())
        .unwrap_or_default()
}

#[cfg(target_os = "linux")]
fn read_cgroup_limit(path: &Path) -> u64 {
    std::fs::read_to_string(path)
        .ok()
        .and_then(|value| parse_cgroup_limit(&value))
        .unwrap_or_default()
}

#[cfg(target_os = "linux")]
fn parse_cgroup_limit(value: &str) -> Option<u64> {
    let value = value.trim();
    if value == "max" {
        Some(0)
    } else {
        value.parse().ok()
    }
}

#[cfg(unix)]
fn timeval_to_micros(value: libc::timeval) -> u64 {
    let seconds = u64::try_from(value.tv_sec).unwrap_or_default();
    let micros = u64::try_from(value.tv_usec)
        .unwrap_or_default()
        .min(999_999);
    seconds.saturating_mul(1_000_000).saturating_add(micros)
}

#[cfg(unix)]
fn max_rss_bytes(value: libc::c_long) -> u64 {
    let value = u64::try_from(value).unwrap_or_default();
    #[cfg(any(target_os = "linux", target_os = "android"))]
    {
        value.saturating_mul(1024)
    }
    #[cfg(not(any(target_os = "linux", target_os = "android")))]
    {
        value
    }
}

#[derive(Parser, Debug)]
#[command(
    name = "aspd",
    about = "ASP agent-native remote development daemon",
    version
)]
struct Args {
    #[arg(long, env = "ASP_LISTEN", default_value = "127.0.0.1:4433")]
    listen: SocketAddr,
    /// Enable the fail-closed production policy. This requires authenticated
    /// clients, a loopback health endpoint, an operator-supplied process
    /// boundary, and nonzero CPU/wall-clock limits. The boundary itself is
    /// intentionally external (for example a reviewed bwrap/systemd wrapper
    /// or per-workspace container); ASP does not pretend to be a sandbox.
    #[arg(long, env = "ASP_PRODUCTION", default_value_t = false)]
    production: bool,
    /// Maximum wire version accepted by this daemon. The default accepts the
    /// current v17 plus the tested v16 compatibility framing. Setting this to
    /// 16 is useful for a controlled rollback/compatibility drill; it does
    /// not change the durable session format.
    #[arg(
        long,
        env = "ASP_MAX_PROTOCOL_VERSION",
        default_value_t = PROTOCOL_VERSION,
        value_name = "VERSION"
    )]
    max_protocol_version: u16,
    /// Explicitly permit listening beyond loopback. Prefer a Tailscale
    /// interface or a firewall when enabling this for remote development.
    #[arg(long, env = "ASP_ALLOW_NON_LOOPBACK", default_value_t = false)]
    allow_non_loopback: bool,
    /// Require QUIC stateless address validation before accepting a
    /// connection. The production profile enables this automatically; the
    /// explicit switch is useful for development daemons that listen on a
    /// shared/private interface. Quinn generates and validates the retry
    /// token, so ASP does not implement cryptography or a second congestion
    /// control path. The first connection pays one extra handshake flight;
    /// resumed sessions retain their durable identity and reconnect normally.
    #[arg(long, env = "ASP_STATELESS_RETRY", default_value_t = false)]
    stateless_retry: bool,
    /// Optional localhost-only HTTP health endpoint for a service manager.
    /// Nothing is bound unless this flag is explicitly supplied.
    #[arg(long, env = "ASP_HEALTH_LISTEN", value_name = "ADDRESS")]
    health_listen: Option<SocketAddr>,
    /// Optional allowlist for PORT_OPEN targets. Repeat for multiple exact
    /// loopback `HOST:PORT` entries. With no entries, the development
    /// behavior remains the historical loopback-only policy; shared or
    /// production deployments should list every port they intend to expose.
    #[arg(long = "port-target", value_name = "HOST:PORT")]
    port_targets: Vec<String>,
    /// Explicitly disable PORT_OPEN. This is useful with `--production` when
    /// a deployment does not need development-server forwarding; it is
    /// mutually exclusive with an allowlist.
    #[arg(
        long,
        env = "ASP_DISABLE_PORT_FORWARDING",
        default_value_t = false,
        conflicts_with = "port_targets"
    )]
    disable_port_forwarding: bool,
    /// Minimum free bytes on the filesystem containing `--root`. Readiness
    /// becomes false and new durable mutations are rejected below this
    /// threshold. Zero keeps the development default without a circuit
    /// breaker; production mode requires an explicit nonzero value.
    #[arg(
        long,
        env = "ASP_MIN_FREE_BYTES",
        default_value_t = 0,
        value_name = "BYTES"
    )]
    min_free_bytes: u64,
    /// Validate the daemon's paths, TLS material, authentication policy,
    /// retention values, and resource budgets, then exit without acquiring
    /// the state lock or creating missing files. This is intended for
    /// service-manager ExecStartPre checks and deployment automation.
    #[arg(
        long,
        default_value_t = false,
        conflicts_with_all = [
            "rotate_auth_token",
            "backup_state",
            "verify_state",
            "restore_state",
            "force_restore"
        ]
    )]
    validate_config: bool,
    #[arg(long, env = "ASP_ROOT", default_value = ".")]
    root: PathBuf,
    #[arg(long, env = "ASP_CERT", default_value = ".asp/server-cert.der")]
    cert: PathBuf,
    #[arg(long, env = "ASP_KEY", default_value = ".asp/server-key.der")]
    key: PathBuf,
    /// File containing the bearer token required from clients. Created automatically.
    #[arg(long, env = "ASP_AUTH_TOKEN_FILE", default_value = ".asp/auth-token")]
    auth_token_file: PathBuf,
    /// Atomically rotate the bearer token and exit. The daemon must not be
    /// running; clients using the token file pick up the new value on their
    /// next connection. The credential itself is never printed.
    #[arg(
        long,
        default_value_t = false,
        conflicts_with_all = [
            "insecure_no_auth",
            "auth_principals_file",
            "client_ca",
            "auth_certificates_file",
            "backup_state",
            "verify_state",
            "restore_state",
            "force_restore"
        ]
    )]
    rotate_auth_token: bool,
    /// Optional JSON map of identity names to token/scope records. When set,
    /// this replaces the single bearer token file and binds new sessions to
    /// the authenticated identity.
    #[arg(long, env = "ASP_AUTH_PRINCIPALS_FILE")]
    auth_principals_file: Option<PathBuf>,
    /// DER-encoded client CA used to require TLS client certificates, or a
    /// directory containing up to eight regular `.der` CAs for an old/new
    /// overlap during rotation. The certificate fingerprint must be mapped in
    /// `--auth-certificates-file`. This is the preferred identity-bound mode
    /// for shared deployments.
    #[arg(long, env = "ASP_CLIENT_CA", requires = "auth_certificates_file")]
    client_ca: Option<PathBuf>,
    /// Optional JSON map of identity names to client-certificate fingerprints
    /// and scopes, for example `{"alice":{"certificate_sha256":"...","scopes":["*"]}}`.
    #[arg(
        long,
        env = "ASP_AUTH_CERTIFICATES_FILE",
        conflicts_with = "auth_principals_file",
        requires = "client_ca"
    )]
    auth_certificates_file: Option<PathBuf>,
    /// Explicitly assign sessions created before owner binding (owner
    /// `legacy`) to one principal from `--auth-principals-file`. This is a
    /// one-shot maintenance operation and never runs while the daemon serves.
    #[arg(
        long,
        value_name = "PRINCIPAL",
        requires = "auth_principals_file",
        conflicts_with_all = [
            "validate_config",
            "rotate_auth_token",
            "backup_state",
            "verify_state",
            "restore_state",
            "force_restore",
            "client_ca",
            "auth_certificates_file",
            "insecure_no_auth"
        ]
    )]
    migrate_legacy_owner: Option<String>,
    /// Advisory lock preventing two daemons from supervising the same state directory.
    #[arg(long, env = "ASP_LOCK_FILE", default_value = ".asp/aspd.lock")]
    lock_file: PathBuf,
    /// Private JSONL audit sink. Entries contain only non-sensitive operation,
    /// principal, remote, and outcome labels; the writer is asynchronous and
    /// rotates at a bounded size.
    #[arg(long, env = "ASP_AUDIT_LOG", default_value = ".asp/audit.log")]
    audit_log: PathBuf,
    /// Disable client authentication for local development only.
    #[arg(long, env = "ASP_INSECURE_NO_AUTH", default_value_t = false)]
    insecure_no_auth: bool,
    /// Create a consistent backup of the durable `.asp` state directory and
    /// write it to a new destination directory. The destination must not
    /// already exist.
    #[arg(long, value_name = "DIRECTORY", conflicts_with_all = ["restore_state", "verify_state"])]
    backup_state: Option<PathBuf>,
    /// Verify a backup directory created by `--backup-state`.
    #[arg(long, value_name = "DIRECTORY", conflicts_with_all = ["backup_state", "restore_state"])]
    verify_state: Option<PathBuf>,
    /// Restore a previously verified backup into the workspace. Existing
    /// state requires `--force-restore` and is moved aside for recovery.
    #[arg(long, value_name = "DIRECTORY", conflicts_with_all = ["backup_state", "verify_state"])]
    restore_state: Option<PathBuf>,
    /// Permit `--restore-state` to move the current `.asp` directory aside.
    #[arg(long, default_value_t = false)]
    force_restore: bool,
    /// Compact event journals after this many hours.
    #[arg(
        long,
        env = "ASP_EVENT_RETENTION_HOURS",
        default_value_t = 168_u64,
        value_name = "HOURS"
    )]
    event_retention_hours: u64,
    /// Remove logs for exited processes older than this many hours.
    #[arg(
        long,
        env = "ASP_PROCESS_LOG_RETENTION_HOURS",
        default_value_t = 168_u64,
        value_name = "HOURS"
    )]
    process_log_retention_hours: u64,
    /// Remove committed immutable artifacts older than this many hours.
    /// Objects with an unknown creation timestamp are retained safely.
    #[arg(
        long,
        env = "ASP_ARTIFACT_RETENTION_HOURS",
        default_value_t = 720_u64,
        value_name = "HOURS"
    )]
    artifact_retention_hours: u64,
    /// Maximum decoded request bytes allowed for one authenticated principal
    /// and operation during a rolling minute. Set high enough for the largest
    /// expected streamed upload; zero is rejected.
    #[arg(
        long,
        env = "ASP_PRINCIPAL_REQUEST_BYTES_PER_MINUTE",
        default_value_t = DEFAULT_PRINCIPAL_REQUEST_BYTES_PER_MINUTE,
        value_name = "BYTES"
    )]
    principal_request_bytes_per_minute: u64,
    /// Maximum encoded response bytes allowed for one authenticated principal
    /// during a rolling minute. Set high enough for the largest expected
    /// streamed output; zero is rejected.
    #[arg(
        long,
        env = "ASP_PRINCIPAL_RESPONSE_BYTES_PER_MINUTE",
        default_value_t = DEFAULT_PRINCIPAL_RESPONSE_BYTES_PER_MINUTE,
        value_name = "BYTES"
    )]
    principal_response_bytes_per_minute: u64,
    /// Per-command virtual address-space limit inherited by descendants.
    /// Zero disables this RLIMIT; a supervisor cgroup remains the stronger
    /// deployment boundary.
    #[arg(
        long,
        env = "ASP_PROCESS_MEMORY_BYTES",
        default_value_t = 0,
        value_name = "BYTES"
    )]
    process_memory_bytes: u64,
    /// Per-command CPU time limit inherited by descendants. Zero disables
    /// this RLIMIT; wall-clock and cgroup policy remain supervisor concerns.
    #[arg(
        long,
        env = "ASP_PROCESS_CPU_SECONDS",
        default_value_t = 0,
        value_name = "SECONDS"
    )]
    process_cpu_seconds: u64,
    /// Permit EXEC/SPAWN children to gain privileges through setuid or file
    /// capabilities on Linux. The secure default is to set `no_new_privs` on
    /// every child; use this only for a reviewed trusted launcher.
    #[arg(
        long,
        env = "ASP_ALLOW_PROCESS_PRIVILEGE_GAIN",
        default_value_t = false
    )]
    allow_process_privilege_gain: bool,
    /// Absolute executable used as an optional external EXEC/SPAWN boundary.
    /// The launcher receives `/bin/sh -lc <command>` (or the durable wrapper
    /// path) as its final arguments and must replace itself with that child.
    /// Mature tools such as bwrap/systemd-run may be supplied here; ASP does
    /// not implement a sandbox itself.
    #[arg(long, env = "ASP_PROCESS_LAUNCHER", value_name = "PATH")]
    process_launcher: Option<PathBuf>,
    /// Argument passed verbatim to `--process-launcher`; repeat for multiple
    /// arguments. Use `--process-launcher-arg=--flag` for values beginning
    /// with a dash.
    #[arg(
        long = "process-launcher-arg",
        value_name = "ARG",
        requires = "process_launcher"
    )]
    process_launcher_args: Vec<String>,
    /// Refuse startup unless an external process launcher is configured. This
    /// is the production fail-closed mode for deployments that require a
    /// per-workspace sandbox/supervisor.
    #[arg(long, env = "ASP_REQUIRE_PROCESS_LAUNCHER", default_value_t = false)]
    require_process_launcher: bool,
    /// Wall-clock limit for attached EXEC/EXEC_SUMMARY commands. Zero
    /// disables it; detached SPAWN processes are intentionally unaffected.
    /// A timed-out command is terminated as a process group and reports the
    /// conventional exit code 124. Use a supervisor/worker boundary as the
    /// stronger policy for untrusted workloads.
    #[arg(
        long,
        env = "ASP_EXEC_TIMEOUT_SECONDS",
        default_value_t = 0,
        value_name = "SECONDS"
    )]
    exec_timeout_seconds: u64,
    /// Stop accepting new connections after SIGTERM/SIGINT, allow in-flight
    /// requests to finish, then close the endpoint. Long-lived PTY/event
    /// streams are bounded by this grace period and reconnect normally.
    #[arg(
        long,
        env = "ASP_SHUTDOWN_GRACE_SECONDS",
        default_value_t = DEFAULT_SHUTDOWN_GRACE_SECONDS,
        value_name = "SECONDS"
    )]
    shutdown_grace_seconds: u64,
    /// Print durable session metadata and exit. This is a local, lock-
    /// protected operator command and does not open the QUIC listener.
    #[arg(
        long,
        default_value_t = false,
        conflicts_with_all = [
            "delete_session",
            "validate_config",
            "rotate_auth_token",
            "backup_state",
            "verify_state",
            "restore_state",
            "force_restore",
            "migrate_legacy_owner"
        ]
    )]
    list_sessions: bool,
    /// Delete one durable session and exit. The command refuses sessions with
    /// running processes, a persisted PTY, or active subscriptions; stop the
    /// daemon first so no new attachment can race the decision.
    #[arg(
        long,
        value_name = "SESSION_ID",
        conflicts_with_all = [
            "list_sessions",
            "validate_config",
            "rotate_auth_token",
            "backup_state",
            "verify_state",
            "restore_state",
            "force_restore",
            "migrate_legacy_owner"
        ]
    )]
    delete_session: Option<Uuid>,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
struct BackupManifest {
    version: u16,
    created_unix_ms: u64,
    entries: Vec<BackupEntry>,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
struct BackupEntry {
    path: String,
    bytes: u64,
    sha256: String,
    #[serde(default)]
    mode: Option<u32>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct AuthPrincipal {
    id: Arc<str>,
    credential: Arc<str>,
    certificate_sha256: Option<Arc<str>>,
    scopes: Vec<String>,
}

#[derive(Debug, Clone, Deserialize)]
#[serde(deny_unknown_fields)]
struct AuthPrincipalConfig {
    token: String,
    #[serde(default = "default_auth_scopes")]
    scopes: Vec<String>,
}

#[derive(Debug, Clone, Deserialize)]
#[serde(deny_unknown_fields)]
struct AuthCertificateConfig {
    certificate_sha256: String,
    #[serde(default = "default_auth_scopes")]
    scopes: Vec<String>,
}

/// A small identity for an on-disk authentication configuration.  The cache
/// is intentionally invalidated on a metadata change (including an atomic
/// rename used during rotation), while the file is still reopened through the
/// symlink-safe reader before a new value is accepted.  This avoids reparsing
/// a potentially large principals map on every request without weakening
/// revocation/rotation semantics.
#[derive(Debug, Clone, PartialEq, Eq)]
struct AuthFileStamp {
    length: u64,
    modified: Option<SystemTime>,
    /// Atomic credential rotation commonly replaces the file with a new
    /// inode while preserving length and (on coarse filesystems) mtime. Keep
    /// the file identity when the platform exposes it so a cache can never
    /// retain a revoked map solely because metadata timestamps collided.
    file_id: Option<(u64, u64)>,
}

#[derive(Debug, Clone)]
struct CachedAuthToken {
    stamp: AuthFileStamp,
    value: Arc<str>,
}

#[derive(Debug, Clone)]
struct CachedAuthPrincipals {
    stamp: AuthFileStamp,
    values: Arc<HashMap<String, AuthPrincipalConfig>>,
}

#[derive(Debug, Clone)]
struct CachedAuthCertificates {
    stamp: AuthFileStamp,
    values: Arc<HashMap<String, AuthCertificateConfig>>,
}

/// The audit record deliberately has no request body, path, command, token,
/// or file content. It is safe to route to an access-controlled operational
/// sink while still answering who did what and whether authentication or
/// admission failed.
#[derive(Debug, Serialize)]
struct AuditEntry {
    unix_ms: u64,
    remote: Option<String>,
    operation: String,
    principal: Option<String>,
    outcome: String,
}

enum AuditMessage {
    Entry(AuditEntry),
    Shutdown(std::sync::mpsc::SyncSender<bool>),
}

struct AuditInner {
    tx: std::sync::mpsc::SyncSender<AuditMessage>,
    dropped: AtomicU64,
    failures: AtomicU64,
    join: Mutex<Option<std::thread::JoinHandle<()>>>,
}

struct AuditSink {
    inner: Arc<AuditInner>,
}

impl AuditSink {
    fn open(path: &Path) -> Result<Arc<Self>> {
        if let Some(parent) = path.parent()
            && !parent.as_os_str().is_empty()
        {
            std::fs::create_dir_all(parent)?;
            reject_symlink(parent)?;
        }
        // Open once before starting the writer so a bad path or permission is
        // reported during daemon startup instead of silently losing audit
        // records after the first request.
        let file = open_audit_file(path)?;
        drop(file);

        let (tx, receiver) = std::sync::mpsc::sync_channel(AUDIT_QUEUE_CAPACITY);
        let inner = Arc::new(AuditInner {
            tx,
            dropped: AtomicU64::new(0),
            failures: AtomicU64::new(0),
            join: Mutex::new(None),
        });
        let writer_inner = Arc::clone(&inner);
        let writer_path = path.to_path_buf();
        let writer = std::thread::Builder::new()
            .name("asp-audit-writer".to_owned())
            .spawn(move || audit_writer(writer_path, receiver, writer_inner))
            .context("spawn ASP audit writer")?;
        *inner.join.lock().expect("audit writer handle poisoned") = Some(writer);
        Ok(Arc::new(Self { inner }))
    }

    fn record(
        &self,
        remote: Option<SocketAddr>,
        operation: &str,
        principal: Option<&str>,
        outcome: &str,
    ) {
        let entry = AuditEntry {
            unix_ms: unix_ms(),
            remote: remote.map(|value| value.to_string()),
            operation: operation.to_owned(),
            principal: principal.map(str::to_owned),
            outcome: outcome.to_owned(),
        };
        match self.inner.tx.try_send(AuditMessage::Entry(entry)) {
            Ok(()) => {}
            Err(std::sync::mpsc::TrySendError::Full(_)) => {
                self.inner.dropped.fetch_add(1, Ordering::Relaxed);
            }
            Err(std::sync::mpsc::TrySendError::Disconnected(_)) => {
                self.inner.dropped.fetch_add(1, Ordering::Relaxed);
                self.inner.failures.fetch_add(1, Ordering::Relaxed);
            }
        }
    }

    fn stats(&self) -> (u64, u64) {
        (
            self.inner.dropped.load(Ordering::Relaxed),
            self.inner.failures.load(Ordering::Relaxed),
        )
    }

    fn shutdown(&self) -> Result<()> {
        let (sender, receiver) = std::sync::mpsc::sync_channel(1);
        self.inner
            .tx
            .send(AuditMessage::Shutdown(sender))
            .map_err(|_| anyhow!("ASP audit writer stopped"))?;
        if !receiver
            .recv()
            .context("wait for ASP audit writer shutdown")?
        {
            bail!("ASP audit writer could not flush during shutdown");
        }
        if let Some(writer) = self
            .inner
            .join
            .lock()
            .expect("audit writer handle poisoned")
            .take()
        {
            writer
                .join()
                .map_err(|_| anyhow!("ASP audit writer thread panicked"))?;
        }
        Ok(())
    }
}

fn open_audit_file(path: &Path) -> Result<File> {
    reject_symlink(path)?;
    let mut options = OpenOptions::new();
    options.create(true).append(true).read(true);
    #[cfg(unix)]
    options.custom_flags(libc::O_NOFOLLOW);
    let file = options
        .open(path)
        .with_context(|| format!("open ASP audit log {}", path.display()))?;
    set_private_permissions(path)?;
    Ok(file)
}

fn rotated_audit_path(path: &Path) -> Result<PathBuf> {
    let name = path
        .file_name()
        .and_then(|value| value.to_str())
        .ok_or_else(|| anyhow!("ASP audit log path is not valid UTF-8"))?;
    Ok(path.with_file_name(format!("{name}.1")))
}

/// Move the active audit segment over the retained segment without first
/// deleting the retained file. Unix rename replaces a regular destination
/// atomically; platforms without that guarantee use the safest available
/// remove-then-rename fallback. The caller has already rejected symlinks and
/// the fallback still leaves the active segment in place if removal fails.
fn replace_audit_segment(path: &Path, rotated: &Path) -> Result<()> {
    #[cfg(unix)]
    {
        std::fs::rename(path, rotated)
            .with_context(|| format!("replace rotated ASP audit log {}", rotated.display()))?;
    }
    #[cfg(not(unix))]
    {
        match std::fs::remove_file(rotated) {
            Ok(()) => {}
            Err(error) if error.kind() == std::io::ErrorKind::NotFound => {}
            Err(error) => return Err(error.into()),
        }
        std::fs::rename(path, rotated)
            .with_context(|| format!("rotate ASP audit log {}", path.display()))?;
    }
    Ok(())
}

fn rotate_audit_file(path: &Path, file: &mut File) -> Result<File> {
    file.sync_data()?;
    let rotated = rotated_audit_path(path)?;
    reject_symlink(&rotated)?;
    replace_audit_segment(path, &rotated)?;
    if let Some(parent) = path.parent() {
        sync_directory(parent)?;
    }
    match open_audit_file(path) {
        Ok(file) => Ok(file),
        Err(error) => {
            // Do not leave the active path missing when a transient open
            // failure occurs after the rename. Restoring the old path keeps
            // the audit sink recoverable on the next request/restart.
            let restore = std::fs::rename(&rotated, path);
            if restore.is_ok()
                && let Some(parent) = path.parent()
            {
                let _ = sync_directory(parent);
            }
            Err(error).context("reopen ASP audit log after rotation")
        }
    }
}

fn audit_writer(
    path: PathBuf,
    receiver: std::sync::mpsc::Receiver<AuditMessage>,
    inner: Arc<AuditInner>,
) {
    let mut file = match open_audit_file(&path) {
        Ok(file) => file,
        Err(error) => {
            inner.failures.fetch_add(1, Ordering::Relaxed);
            warn!(%error, path = %path.display(), "ASP audit writer could not open log");
            return;
        }
    };
    let mut dirty_bytes = 0_u64;
    let mut last_sync = Instant::now();
    while let Ok(message) = receiver.recv() {
        match message {
            AuditMessage::Entry(entry) => {
                let mut line = match serde_json::to_vec(&entry) {
                    Ok(line) => line,
                    Err(error) => {
                        inner.failures.fetch_add(1, Ordering::Relaxed);
                        warn!(%error, "could not encode ASP audit entry");
                        continue;
                    }
                };
                line.push(b'\n');
                let current_len = match file.metadata() {
                    Ok(metadata) => metadata.len(),
                    Err(error) => {
                        inner.failures.fetch_add(1, Ordering::Relaxed);
                        warn!(%error, "could not stat ASP audit log");
                        continue;
                    }
                };
                if current_len.saturating_add(line.len() as u64) > AUDIT_MAX_BYTES {
                    match rotate_audit_file(&path, &mut file) {
                        Ok(rotated) => {
                            file = rotated;
                            dirty_bytes = 0;
                        }
                        Err(error) => {
                            inner.failures.fetch_add(1, Ordering::Relaxed);
                            warn!(%error, path = %path.display(), "could not rotate ASP audit log");
                            continue;
                        }
                    }
                }
                let start = match file.metadata() {
                    Ok(metadata) => metadata.len(),
                    Err(error) => {
                        inner.failures.fetch_add(1, Ordering::Relaxed);
                        warn!(%error, "could not stat ASP audit log before write");
                        continue;
                    }
                };
                if let Err(error) = file.write_all(&line).and_then(|_| file.flush()) {
                    let _ = file.set_len(start);
                    let _ = file.seek(SeekFrom::End(0));
                    inner.failures.fetch_add(1, Ordering::Relaxed);
                    warn!(%error, path = %path.display(), "could not write ASP audit entry");
                    continue;
                }
                dirty_bytes = dirty_bytes.saturating_add(line.len() as u64);
                if dirty_bytes >= AUDIT_SYNC_BYTES || last_sync.elapsed() >= AUDIT_SYNC_INTERVAL {
                    if let Err(error) = file.sync_data() {
                        inner.failures.fetch_add(1, Ordering::Relaxed);
                        warn!(%error, path = %path.display(), "could not sync ASP audit log");
                    } else {
                        dirty_bytes = 0;
                        last_sync = Instant::now();
                    }
                }
            }
            AuditMessage::Shutdown(reply) => {
                let ok = file.sync_data().is_ok();
                if !ok {
                    inner.failures.fetch_add(1, Ordering::Relaxed);
                }
                let _ = reply.send(ok);
                break;
            }
        }
    }
    if dirty_bytes > 0 {
        let _ = file.sync_data();
    }
}

fn default_auth_scopes() -> Vec<String> {
    vec!["*".to_owned()]
}

impl AuthPrincipal {
    fn anonymous() -> Self {
        Self {
            id: Arc::from("anonymous"),
            credential: Arc::from(""),
            certificate_sha256: None,
            scopes: default_auth_scopes(),
        }
    }

    fn legacy(credential: impl Into<Arc<str>>) -> Self {
        Self {
            id: Arc::from("legacy"),
            credential: credential.into(),
            certificate_sha256: None,
            scopes: default_auth_scopes(),
        }
    }

    fn allows(&self, scope: &str) -> bool {
        self.scopes
            .iter()
            .any(|value| value == "*" || value == scope)
    }
}

#[derive(Default)]
struct Journal {
    events: VecDeque<Event>,
    next_id: u64,
    approx_bytes: usize,
    oldest_event_unix_ms: Option<u64>,
}

/// Durable server-side state for one independent event subscriber.  The
/// acknowledgement is cumulative and monotonic; `last_seen_unix_ms` is a
/// lease heartbeat used to forget abandoned consumers during maintenance.
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
struct EventConsumer {
    #[serde(default)]
    acknowledged_event_id: u64,
    #[serde(default)]
    last_seen_unix_ms: u64,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
struct PersistedEventConsumers {
    consumers: HashMap<String, EventConsumer>,
}

struct SessionDisk {
    directory: PathBuf,
    events: Mutex<EventFile>,
    segments: Mutex<Vec<PathBuf>>,
    /// Highest event ID represented by `snapshot.bin`.  Runtime replay can
    /// recover events that fell out of the bounded in-memory window as long as
    /// the caller's cursor is at or after this boundary.
    snapshot_boundary: AtomicU64,
    /// Total bytes in the active log and rotated segments. Event appends are
    /// frequent (especially for process output), so keep this daemon-owned
    /// accounting in memory instead of rescanning every segment on each
    /// append. Startup/rotation/compaction refresh it from the filesystem.
    total_bytes: AtomicU64,
}

struct EventFile {
    file: File,
    path: PathBuf,
    checksummed: bool,
    first_event_id: Option<u64>,
    dirty_bytes: u64,
    last_sync: Instant,
}

/// Bounded destination for durable replay.  Startup recovery must scan every
/// event to rebuild materialized state, but a live RESUME/SUBSCRIBE request
/// only needs enough events to send to one client.  Keeping this limit in the
/// collector (rather than after `load_event_log` returns) prevents a large
/// WAL from becoming an equally large temporary `Vec<Event>`.
struct EventReplayBuffer {
    after_event_id: u64,
    events: Vec<Event>,
    bytes: usize,
    limit_reached: bool,
}

impl EventReplayBuffer {
    fn new(after_event_id: u64) -> Self {
        Self {
            after_event_id,
            events: Vec::new(),
            bytes: 0,
            limit_reached: false,
        }
    }

    /// Return `false` when the caller should stop scanning and use a current
    /// snapshot instead.  Events at or before the cursor are still validated
    /// by the WAL loader but do not consume the replay budget.
    fn push(&mut self, event: &Event) -> bool {
        if event.id <= self.after_event_id {
            return true;
        }
        let event_bytes = event_approx_bytes(event);
        if self.events.len() >= MAX_DURABLE_REPLAY_EVENTS
            || self.bytes.saturating_add(event_bytes) > MAX_DURABLE_REPLAY_BYTES
        {
            self.limit_reached = true;
            return false;
        }
        self.bytes = self.bytes.saturating_add(event_bytes);
        self.events.push(event.clone());
        true
    }
}

#[derive(Default)]
struct LoadedSession {
    events: VecDeque<Event>,
    approx_bytes: usize,
    next_id: u64,
    oldest_event_unix_ms: Option<u64>,
    processes: HashMap<Uuid, ProcessRecord>,
    process_requests: HashMap<Uuid, ProcessRequest>,
    file_versions: HashMap<String, u64>,
    file_requests: HashMap<Uuid, FileRequest>,
    signal_requests: HashMap<Uuid, SignalRequest>,
    artifact_requests: HashMap<Uuid, ArtifactRequest>,
    artifacts: HashMap<String, ArtifactRecord>,
    pty_started: bool,
    pty_generation: u64,
    running_processes: usize,
    event_consumers: HashMap<String, EventConsumer>,
}

/// Conservative in-memory accounting for a journal event. This deliberately
/// avoids JSON/base64 serialization on every high-rate output chunk; the
/// journal limits only need an upper-bound estimate, while the WAL itself
/// remains encoded and checksummed by SessionDisk.
fn event_approx_bytes(event: &Event) -> usize {
    let variable = match &event.kind {
        EventKind::SessionCreated | EventKind::PtyStarted | EventKind::PtyStateAdvanced { .. } => 0,
        EventKind::ProcessStarted { command, .. } => command.len(),
        EventKind::ProcessOutput { data, .. } => data.len(),
        EventKind::ProcessExited { .. } => 0,
        EventKind::FileChanged { path, .. } => path.len(),
        EventKind::FileMutation {
            request_hash,
            path,
            sha256,
            ..
        } => request_hash
            .len()
            .saturating_add(path.len())
            .saturating_add(sha256.len()),
        EventKind::SignalApplied {
            request_hash,
            message,
            ..
        } => request_hash
            .len()
            .saturating_add(message.as_deref().map_or(0, str::len)),
        EventKind::ArtifactCreated {
            request_hash,
            artifact_id,
            name,
            ..
        } => request_hash
            .len()
            .saturating_add(artifact_id.len())
            .saturating_add(name.as_deref().map_or(0, str::len)),
        EventKind::ArtifactDeleted { artifact_id, .. } => artifact_id.len(),
    };
    128usize.saturating_add(variable)
}

impl LoadedSession {
    fn push(&mut self, event: Event) {
        self.next_id = self.next_id.max(event.id);
        self.oldest_event_unix_ms = Some(
            self.oldest_event_unix_ms
                .map_or(event.unix_ms, |oldest| oldest.min(event.unix_ms)),
        );
        self.apply(&event);
        self.approx_bytes = self.approx_bytes.saturating_add(event_approx_bytes(&event));
        self.events.push_back(event);
        while self.events.len() > JOURNAL_MAX_EVENTS || self.approx_bytes > JOURNAL_MAX_BYTES {
            if let Some(old) = self.events.front() {
                self.approx_bytes = self.approx_bytes.saturating_sub(event_approx_bytes(old));
            }
            self.events.pop_front();
        }
        self.oldest_event_unix_ms = self.events.front().map(|event| event.unix_ms);
    }

    fn apply(&mut self, event: &Event) {
        match &event.kind {
            EventKind::ProcessStarted {
                process_id,
                command,
                pid,
                request_id,
            } => {
                if self
                    .processes
                    .insert(
                        *process_id,
                        ProcessRecord {
                            command: command.clone(),
                            running: true,
                            exit_code: None,
                            exit_unix_ms: None,
                            pid: *pid,
                            pid_start_time: None,
                            stdout_bytes: 0,
                            stderr_bytes: 0,
                        },
                    )
                    .is_none()
                {
                    self.running_processes += 1;
                }
                if let Some(request_id) = request_id {
                    self.process_requests.insert(
                        *request_id,
                        ProcessRequest {
                            command: command.clone(),
                            command_hash: Some(sha256(command.as_bytes())),
                            process_id: *process_id,
                            started_event_id: event.id,
                        },
                    );
                }
            }
            EventKind::ProcessOutput {
                process_id,
                stream,
                data,
                ..
            } => {
                if let Some(record) = self.processes.get_mut(process_id) {
                    match stream {
                        OutputStream::Stdout => record.stdout_bytes += data.len() as u64,
                        OutputStream::Stderr => record.stderr_bytes += data.len() as u64,
                    }
                }
            }
            EventKind::ProcessExited {
                process_id, code, ..
            } => {
                if let Some(record) = self.processes.get_mut(process_id) {
                    if record.running {
                        record.running = false;
                        self.running_processes = self.running_processes.saturating_sub(1);
                    }
                    record.exit_code = *code;
                    record.exit_unix_ms = Some(event.unix_ms);
                }
            }
            EventKind::FileChanged { path, version } => {
                self.file_versions.insert(path.clone(), *version);
            }
            EventKind::FileMutation {
                request_id,
                request_hash,
                path,
                version,
                sha256,
            } => {
                self.file_versions.insert(path.clone(), *version);
                self.file_requests.insert(
                    *request_id,
                    FileRequest {
                        request_hash: request_hash.clone(),
                        path: path.clone(),
                        version: *version,
                        sha256: sha256.clone(),
                    },
                );
            }
            EventKind::SignalApplied {
                request_id,
                request_hash,
                process_id,
                signal,
                success,
                message,
            } => {
                self.signal_requests.insert(
                    *request_id,
                    SignalRequest {
                        request_hash: request_hash.clone(),
                        process_id: *process_id,
                        signal: *signal,
                        success: *success,
                        message: message.clone(),
                    },
                );
            }
            EventKind::ArtifactCreated {
                request_id,
                request_hash,
                artifact_id,
                total_size,
                name,
            } => {
                self.artifact_requests.insert(
                    *request_id,
                    ArtifactRequest {
                        request_hash: request_hash.clone(),
                        artifact_id: artifact_id.clone(),
                        total_size: *total_size,
                        name: name.clone(),
                        event_id: event.id,
                    },
                );
                self.artifacts.insert(
                    artifact_id.clone(),
                    ArtifactRecord {
                        artifact_id: artifact_id.clone(),
                        total_size: *total_size,
                        name: name.clone(),
                        created_event_id: event.id,
                        created_unix_ms: event.unix_ms,
                    },
                );
            }
            EventKind::ArtifactDeleted { artifact_id, .. } => {
                self.artifacts.remove(artifact_id);
                self.artifact_requests
                    .retain(|_, request| request.artifact_id != *artifact_id);
            }
            EventKind::PtyStarted => self.pty_started = true,
            EventKind::PtyStateAdvanced { generation } => {
                self.pty_generation = self.pty_generation.max(*generation);
            }
            EventKind::SessionCreated => {}
        }
    }
}

impl SessionDisk {
    fn open(directory: &Path) -> Result<(Arc<Self>, LoadedSession)> {
        ensure_private_directory(directory)?;
        // These subtrees are daemon-owned and are created lazily. Validate
        // any that already exist before reading journals or starting
        // recovery so a replaced directory cannot redirect process,
        // transaction, upload, or artifact I/O outside the session.
        for name in ["processes", "transactions", "uploads", "artifacts"] {
            ensure_optional_private_directory(&directory.join(name), name)?;
        }
        let mut loaded = match read_snapshot_file(directory)? {
            Some(snapshot) => {
                if let Some(expected_id) = directory
                    .file_name()
                    .and_then(|name| name.to_str())
                    .and_then(|name| name.parse::<Uuid>().ok())
                    && snapshot.session_id != expected_id
                {
                    bail!(
                        "ASP snapshot session ID does not match {}",
                        directory.display()
                    );
                }
                Some(LoadedSession::from_snapshot(snapshot))
            }
            None => None,
        };
        let mut loaded = loaded.take().unwrap_or_default();
        // A snapshot may legitimately make old WAL segments redundant.
        // Every event after that boundary must nevertheless form one
        // contiguous monotonic sequence; otherwise a torn or malicious
        // journal could silently hide a missing lifecycle event.
        let snapshot_boundary = loaded.next_id;
        let mut last_event_id = snapshot_boundary;
        let mut segment_paths = list_event_segments(directory)?;
        let active_path = directory.join("events.log");
        segment_paths.sort();
        for path in &segment_paths {
            let _ = load_event_log(
                path,
                false,
                &mut loaded,
                snapshot_boundary,
                &mut last_event_id,
                true,
                None,
            )?;
        }
        let active = load_event_log(
            &active_path,
            true,
            &mut loaded,
            snapshot_boundary,
            &mut last_event_id,
            true,
            None,
        )?;
        loaded.event_consumers = read_event_consumers_file(directory)?;
        for (consumer_id, consumer) in &loaded.event_consumers {
            validate_event_consumer_id(consumer_id)?;
            if consumer.acknowledged_event_id > loaded.next_id {
                bail!(
                    "event consumer {consumer_id:?} acknowledges event {} beyond journal head {}",
                    consumer.acknowledged_event_id,
                    loaded.next_id
                );
            }
        }
        let active_bytes = active.file.metadata()?.len();
        let segment_bytes = segment_paths.iter().try_fold(0_u64, |total, path| {
            Ok::<u64, std::io::Error>(total.saturating_add(std::fs::metadata(path)?.len()))
        })?;
        Ok((
            Arc::new(Self {
                directory: directory.to_path_buf(),
                events: Mutex::new(active),
                segments: Mutex::new(segment_paths),
                snapshot_boundary: AtomicU64::new(snapshot_boundary),
                total_bytes: AtomicU64::new(active_bytes.saturating_add(segment_bytes)),
            }),
            loaded,
        ))
    }

    fn append(&self, event: &Event) -> Result<()> {
        let payload = asp_protocol::encode_message(event)?;
        let length = u32::try_from(payload.len()).context("event exceeds journal frame limit")?;
        let mut event_file = self.events.lock().expect("event log poisoned");
        let mut start = event_file.file.metadata()?.len();
        let checksum_bytes: u64 = if event_file.checksummed { 4 } else { 0 };
        let frame_bytes = 4_u64
            .saturating_add(checksum_bytes)
            .saturating_add(payload.len() as u64);
        if start > EVENT_LOG_MAGIC.len() as u64 + 2
            && start.saturating_add(frame_bytes) > EVENT_SEGMENT_MAX_BYTES
        {
            self.rotate_locked(&mut event_file, event.id)?;
            self.refresh_total_bytes_locked(&event_file)?;
            start = event_file.file.metadata()?.len();
        }
        let projected = self
            .total_bytes
            .load(Ordering::Acquire)
            .saturating_add(frame_bytes);
        if projected > EVENT_LOG_MAX_BYTES {
            bail!(
                "event storage exceeds the {EVENT_LOG_MAX_BYTES} byte safety limit; compact or restore retention"
            );
        }
        let result = (|| -> Result<()> {
            event_file.file.write_all(&length.to_be_bytes())?;
            if event_file.checksummed {
                event_file.file.write_all(&crc32(&payload).to_be_bytes())?;
            }
            event_file.file.write_all(&payload)?;
            event_file.file.flush()?;
            Ok(())
        })();
        if let Err(error) = result {
            // A failed write must not leave a partial frame in the live file:
            // the next append happens on this same descriptor, not after a
            // restart that would otherwise truncate the tail for us.
            let _ = event_file.file.set_len(start);
            let _ = event_file.file.seek(SeekFrom::End(0));
            event_file.dirty_bytes = 0;
            return Err(error);
        }
        if event_file.first_event_id.is_none() {
            event_file.first_event_id = Some(event.id);
        }
        event_file.dirty_bytes = event_file.dirty_bytes.saturating_add(frame_bytes);
        self.total_bytes.fetch_add(frame_bytes, Ordering::AcqRel);
        let force_sync = !matches!(
            event.kind,
            EventKind::ProcessOutput { .. } | EventKind::PtyStateAdvanced { .. }
        );
        if force_sync
            || event_file.dirty_bytes >= EVENT_SYNC_BYTES
            || event_file.last_sync.elapsed() >= EVENT_SYNC_INTERVAL
        {
            if let Err(error) = event_file.file.sync_data() {
                let _ = event_file.file.set_len(start);
                let _ = event_file.file.seek(SeekFrom::End(0));
                event_file.dirty_bytes = 0;
                self.total_bytes.fetch_sub(frame_bytes, Ordering::AcqRel);
                return Err(error.into());
            }
            event_file.dirty_bytes = 0;
            event_file.last_sync = Instant::now();
        }
        Ok(())
    }

    fn rotate_locked(&self, event_file: &mut EventFile, next_event_id: u64) -> Result<()> {
        event_file.file.flush()?;
        event_file.file.sync_data()?;
        let first = event_file.first_event_id.unwrap_or(next_event_id);
        let segment = self
            .directory
            .join(format!("events-{first:020}-{}.log", Uuid::new_v4()));
        std::fs::rename(&event_file.path, &segment)?;
        sync_directory(&self.directory)?;
        self.segments
            .lock()
            .expect("event segments poisoned")
            .push(segment);
        let active_path = self.directory.join("events.log");
        reject_symlink(&active_path)?;
        let mut options = OpenOptions::new();
        options.create(true).truncate(true).read(true).write(true);
        #[cfg(unix)]
        options.custom_flags(libc::O_NOFOLLOW);
        let mut file = options.open(&active_path)?;
        file.write_all(EVENT_LOG_MAGIC)?;
        file.write_all(&EVENT_LOG_VERSION.to_be_bytes())?;
        file.sync_data()?;
        *event_file = EventFile {
            file,
            path: active_path,
            checksummed: true,
            first_event_id: None,
            dirty_bytes: 0,
            last_sync: Instant::now(),
        };
        Ok(())
    }

    fn total_len_locked(&self, event_file: &EventFile) -> Result<u64> {
        let active = event_file.file.metadata()?.len();
        let segments = self.segments.lock().expect("event segments poisoned");
        let old = segments.iter().try_fold(0_u64, |total, path| {
            Ok::<u64, std::io::Error>(
                total.saturating_add(
                    std::fs::metadata(path)
                        .map(|metadata| metadata.len())
                        .unwrap_or(0),
                ),
            )
        })?;
        Ok(active.saturating_add(old))
    }

    fn refresh_total_bytes_locked(&self, event_file: &EventFile) -> Result<()> {
        let total = self.total_len_locked(event_file)?;
        self.total_bytes.store(total, Ordering::Release);
        Ok(())
    }

    fn sync(&self) -> Result<()> {
        let mut event_file = self.events.lock().expect("event log poisoned");
        event_file.file.flush()?;
        event_file.file.sync_data()?;
        event_file.dirty_bytes = 0;
        event_file.last_sync = Instant::now();
        Ok(())
    }

    fn len(&self) -> Result<u64> {
        self.total_len()
    }

    fn total_len(&self) -> Result<u64> {
        Ok(self.total_bytes.load(Ordering::Acquire))
    }

    fn compact(&self, snapshot: &SessionSnapshotData) -> Result<()> {
        // Snapshot first. If the daemon dies before the WAL is reset, startup
        // loads the snapshot and safely skips events at or below its boundary.
        write_snapshot_file(&self.directory, snapshot)?;
        let mut event_file = self.events.lock().expect("event log poisoned");
        event_file.file.set_len(0)?;
        event_file.file.seek(SeekFrom::Start(0))?;
        event_file.file.write_all(EVENT_LOG_MAGIC)?;
        event_file
            .file
            .write_all(&EVENT_LOG_VERSION.to_be_bytes())?;
        event_file.file.flush()?;
        event_file.file.sync_data()?;
        event_file.checksummed = true;
        event_file.first_event_id = None;
        event_file.dirty_bytes = 0;
        event_file.last_sync = Instant::now();
        let mut segments = self.segments.lock().expect("event segments poisoned");
        for path in segments.drain(..) {
            match std::fs::remove_file(&path) {
                Ok(()) => {}
                Err(error) if error.kind() == std::io::ErrorKind::NotFound => {}
                Err(error) => {
                    warn!(%error, path = %path.display(), "could not remove compacted ASP event segment")
                }
            }
        }
        drop(segments);
        sync_directory(&self.directory)?;
        self.snapshot_boundary
            .store(snapshot.through_event_id, Ordering::Release);
        self.refresh_total_bytes_locked(&event_file)?;
        Ok(())
    }

    fn persist_event_consumers(&self, consumers: &HashMap<String, EventConsumer>) -> Result<()> {
        if consumers.len() > MAX_EVENT_CONSUMERS_PER_SESSION {
            bail!(
                "event consumer state exceeds the {MAX_EVENT_CONSUMERS_PER_SESSION} consumer limit"
            );
        }
        for consumer_id in consumers.keys() {
            validate_event_consumer_id(consumer_id)?;
        }
        let payload = asp_protocol::encode_message(&PersistedEventConsumers {
            consumers: consumers.clone(),
        })?;
        let length =
            u32::try_from(payload.len()).context("event consumer state exceeds frame limit")?;
        let mut bytes = Vec::with_capacity(EVENT_CONSUMER_STATE_MAGIC.len() + 10 + payload.len());
        bytes.extend_from_slice(EVENT_CONSUMER_STATE_MAGIC);
        bytes.extend_from_slice(&EVENT_CONSUMER_STATE_VERSION.to_be_bytes());
        bytes.extend_from_slice(&length.to_be_bytes());
        bytes.extend_from_slice(&crc32(&payload).to_be_bytes());
        bytes.extend_from_slice(&payload);
        if bytes.len() as u64 > MAX_EVENT_CONSUMER_STATE_BYTES {
            bail!("event consumer state exceeds {MAX_EVENT_CONSUMER_STATE_BYTES} bytes");
        }
        let path = self.directory.join("event-consumers.bin");
        reject_symlink(&path)?;
        write_atomic_file(&path, &bytes, 0o600)
    }

    fn read_events_since(&self, after_event_id: u64) -> Result<Option<Vec<Event>>> {
        let snapshot_boundary = self.snapshot_boundary.load(Ordering::Acquire);
        if after_event_id < snapshot_boundary {
            return Ok(Some(Vec::new()));
        }
        let mut loaded = LoadedSession {
            next_id: snapshot_boundary,
            ..LoadedSession::default()
        };
        let mut last_event_id = snapshot_boundary;
        let mut collected = EventReplayBuffer::new(after_event_id);
        let segments = self
            .segments
            .lock()
            .expect("event segments poisoned")
            .clone();
        for path in segments {
            let _ = load_event_log(
                &path,
                false,
                &mut loaded,
                snapshot_boundary,
                &mut last_event_id,
                false,
                Some(&mut collected),
            )?;
            if collected.limit_reached {
                return Ok(None);
            }
        }
        let active_path = self.directory.join("events.log");
        let _ = load_event_log(
            &active_path,
            false,
            &mut loaded,
            snapshot_boundary,
            &mut last_event_id,
            false,
            Some(&mut collected),
        )?;
        if collected.limit_reached {
            return Ok(None);
        }
        Ok(Some(collected.events))
    }
}

fn list_event_segments(directory: &Path) -> Result<Vec<PathBuf>> {
    let mut segments = Vec::new();
    for entry in std::fs::read_dir(directory)? {
        let entry = entry?;
        let name = entry.file_name();
        let name = name.to_string_lossy();
        let Some(rest) = name.strip_prefix("events-") else {
            continue;
        };
        let Some(rest) = rest.strip_suffix(".log") else {
            continue;
        };
        let Some(first) = rest
            .split('-')
            .next()
            .and_then(|value| value.parse::<u64>().ok())
        else {
            continue;
        };
        let file_type = entry.file_type()?;
        if file_type.is_symlink() {
            bail!(
                "refusing to follow symlink event segment {}",
                entry.path().display()
            );
        }
        if !file_type.is_file() {
            continue;
        }
        segments.push((first, entry.path()));
    }
    segments.sort();
    Ok(segments.into_iter().map(|(_, path)| path).collect())
}

fn load_event_log(
    path: &Path,
    create: bool,
    loaded: &mut LoadedSession,
    snapshot_boundary: u64,
    last_event_id: &mut u64,
    materialize: bool,
    mut collected: Option<&mut EventReplayBuffer>,
) -> Result<EventFile> {
    if let Ok(metadata) = std::fs::symlink_metadata(path)
        && metadata.file_type().is_symlink()
    {
        bail!("refusing to follow symlink event log {}", path.display());
    }
    let mut options = OpenOptions::new();
    options
        .read(true)
        .write(true)
        .create(create)
        .truncate(false);
    #[cfg(unix)]
    options.custom_flags(libc::O_NOFOLLOW);
    let mut input = options.open(path)?;
    set_private_permissions(path)?;
    let mut file_len = input.metadata()?.len();
    let header_len = EVENT_LOG_MAGIC.len() + std::mem::size_of::<u16>();
    if file_len == 0 {
        input.write_all(EVENT_LOG_MAGIC)?;
        input.write_all(&EVENT_LOG_VERSION.to_be_bytes())?;
        input.sync_data()?;
        file_len = header_len as u64;
    }
    if file_len < header_len as u64 {
        if !create {
            bail!("truncated ASP event log header in {}", path.display());
        }
        input.set_len(0)?;
        input.seek(SeekFrom::Start(0))?;
        input.write_all(EVENT_LOG_MAGIC)?;
        input.write_all(&EVENT_LOG_VERSION.to_be_bytes())?;
        input.sync_data()?;
        file_len = header_len as u64;
    }
    input.seek(SeekFrom::Start(0))?;
    let mut header = vec![0_u8; header_len];
    input
        .read_exact(&mut header)
        .context("read ASP event log header")?;
    if &header[..EVENT_LOG_MAGIC.len()] != EVENT_LOG_MAGIC {
        bail!("unsupported ASP event log format in {}", path.display());
    }
    let version_offset = EVENT_LOG_MAGIC.len();
    let version = u16::from_be_bytes(
        header[version_offset..version_offset + std::mem::size_of::<u16>()].try_into()?,
    );
    let checksummed = match version {
        EVENT_LOG_LEGACY_VERSION => false,
        EVENT_LOG_VERSION => true,
        _ => {
            bail!(
                "unsupported ASP event log version {version} in {}",
                path.display()
            )
        }
    };
    let mut offset = header_len as u64;
    let mut first_event_id = None;
    let mut raw_last_event_id = None::<u64>;
    let mut corruption_reason = None::<&str>;
    // A bounded replay may stop before the end of a valid WAL. This is a
    // resource decision, not corruption, and must not trigger active-log tail
    // truncation below.
    let mut collection_limited = false;
    input.seek(SeekFrom::Start(offset))?;
    loop {
        let frame_start = offset;
        let mut length_bytes = [0_u8; 4];
        match input.read_exact(&mut length_bytes) {
            Ok(()) => {}
            Err(error) if error.kind() == std::io::ErrorKind::UnexpectedEof => {
                // An exact EOF before the next length prefix is a clean end
                // of a rotated segment. Only bytes after `frame_start` mean
                // that an immutable segment contains a torn frame.
                if !create && frame_start < file_len {
                    corruption_reason = Some("truncated event log frame");
                }
                break;
            }
            Err(error) => return Err(error.into()),
        }
        let length = u32::from_be_bytes(length_bytes) as usize;
        if length > MAX_FRAME_BYTES {
            corruption_reason = Some("frame length exceeds the protocol limit");
            break;
        }
        let expected_crc = if checksummed {
            let mut checksum_bytes = [0_u8; 4];
            match input.read_exact(&mut checksum_bytes) {
                Ok(()) => Some(u32::from_be_bytes(checksum_bytes)),
                Err(error) if error.kind() == std::io::ErrorKind::UnexpectedEof => {
                    if !create && frame_start < file_len {
                        corruption_reason = Some("truncated event log checksum");
                    }
                    break;
                }
                Err(error) => return Err(error.into()),
            }
        } else {
            None
        };
        let mut payload = vec![0_u8; length];
        match input.read_exact(&mut payload) {
            Ok(()) => {}
            Err(error) if error.kind() == std::io::ErrorKind::UnexpectedEof => {
                if !create && frame_start < file_len {
                    corruption_reason = Some("truncated event log payload");
                }
                break;
            }
            Err(error) => return Err(error.into()),
        }
        if expected_crc.is_some_and(|expected| crc32(&payload) != expected) {
            corruption_reason = Some("frame checksum mismatch");
            break;
        }
        let event = match asp_protocol::decode_message::<Event>(&payload) {
            Ok(event) => event,
            Err(_) => {
                corruption_reason = Some("event payload could not be decoded");
                break;
            }
        };
        if event.id == 0 {
            corruption_reason = Some("event ID is zero");
            break;
        }
        if raw_last_event_id.is_some_and(|previous| event.id <= previous) {
            corruption_reason = Some("event IDs are not strictly increasing");
            break;
        }
        raw_last_event_id = Some(event.id);
        if event.id <= snapshot_boundary && *last_event_id > snapshot_boundary {
            corruption_reason = Some("stale event appears after the journal boundary");
            break;
        }
        if event.id > snapshot_boundary && event.id != last_event_id.saturating_add(1) {
            corruption_reason = Some("event IDs contain a gap");
            break;
        }
        first_event_id.get_or_insert(event.id);
        if event.id > loaded.next_id {
            if let Some(events) = collected.as_deref_mut()
                && !events.push(&event)
            {
                collection_limited = true;
                break;
            }
            if materialize {
                loaded.push(event);
                *last_event_id = loaded.next_id;
            } else {
                // Live replay only needs corruption/ordering validation and a
                // bounded set of events to send.  Do not rebuild the startup
                // materialized process/request/artifact maps here: a large
                // durable WAL must not turn one RESUME into unbounded memory.
                loaded.next_id = event.id;
                *last_event_id = event.id;
            }
        }
        offset = frame_start + 4 + u64::from(checksummed) * 4 + length as u64;
    }
    if let Some(reason) = corruption_reason {
        drop(input);
        let quarantine = quarantine_event_log(path)?;
        bail!(
            "ASP event log {} has {reason}; quarantined as {}",
            path.display(),
            quarantine.display()
        );
    }
    if collection_limited {
        // This path is used only by read-only replay. Leave the WAL intact;
        // startup recovery still scans the complete file and validates any
        // trailing corruption on the next daemon open.
        input.seek(SeekFrom::End(0))?;
    } else if offset != file_len {
        input.set_len(offset)?;
        input.sync_data()?;
        file_len = offset;
    }
    input.seek(SeekFrom::End(0))?;
    if file_len > EVENT_LOG_MAX_BYTES {
        bail!(
            "event log segment {} exceeds the {EVENT_LOG_MAX_BYTES} byte safety limit",
            path.display()
        );
    }
    Ok(EventFile {
        file: input,
        path: path.to_path_buf(),
        checksummed,
        first_event_id,
        dirty_bytes: 0,
        last_sync: Instant::now(),
    })
}

/// Preserve a log that contains a complete but invalid frame. Truncating a
/// checksum mismatch would silently discard committed history and can make a
/// restored workspace look valid when it is not. Startup therefore refuses to
/// consume the file and moves it aside for an operator or backup restore.
fn quarantine_event_log(path: &Path) -> Result<PathBuf> {
    let parent = path
        .parent()
        .ok_or_else(|| anyhow!("event log has no parent directory"))?;
    let stem = path
        .file_stem()
        .and_then(|value| value.to_str())
        .unwrap_or("events");
    let quarantine = parent.join(format!("{stem}.corrupt-{}.log", Uuid::new_v4()));
    std::fs::rename(path, &quarantine)
        .with_context(|| format!("quarantine corrupt event log {}", path.display()))?;
    sync_directory(parent)?;
    Ok(quarantine)
}
impl Journal {
    fn from_loaded(
        events: VecDeque<Event>,
        next_id: u64,
        oldest_event_unix_ms: Option<u64>,
    ) -> Self {
        let approx_bytes = events.iter().map(event_approx_bytes).sum();
        let retained_oldest = events.front().map(|event| event.unix_ms);
        Self {
            events,
            next_id,
            approx_bytes,
            oldest_event_unix_ms: retained_oldest.or(oldest_event_unix_ms),
        }
    }

    fn append(&mut self, kind: EventKind) -> Event {
        self.next_id += 1;
        let event = Event {
            id: self.next_id,
            unix_ms: unix_ms(),
            kind,
        };
        self.oldest_event_unix_ms = Some(
            self.oldest_event_unix_ms
                .map_or(event.unix_ms, |oldest| oldest.min(event.unix_ms)),
        );
        self.approx_bytes = self.approx_bytes.saturating_add(event_approx_bytes(&event));
        self.events.push_back(event.clone());
        event
    }

    fn enforce_bounds(&mut self) {
        while self.events.len() > JOURNAL_MAX_EVENTS || self.approx_bytes > JOURNAL_MAX_BYTES {
            if let Some(old) = self.events.pop_front() {
                self.approx_bytes = self.approx_bytes.saturating_sub(event_approx_bytes(&old));
            }
        }
        self.oldest_event_unix_ms = self.events.front().map(|event| event.unix_ms);
    }

    fn rollback(&mut self, event: &Event) {
        if self
            .events
            .back()
            .is_some_and(|current| current.id == event.id)
        {
            if let Some(removed) = self.events.pop_back() {
                self.approx_bytes = self
                    .approx_bytes
                    .saturating_sub(event_approx_bytes(&removed));
            }
            self.next_id = event.id.saturating_sub(1);
            self.oldest_event_unix_ms = self.events.front().map(|event| event.unix_ms);
        }
    }

    fn since(&self, after: u64) -> (Vec<Event>, bool) {
        let retained_from = self.retained_from_event_id();
        let compacted = after.saturating_add(1) < retained_from;
        let events = if compacted {
            Vec::new()
        } else {
            self.events
                .iter()
                .filter(|event| event.id > after)
                .cloned()
                .collect()
        };
        (events, compacted)
    }

    fn retained_from_event_id(&self) -> u64 {
        self.events
            .front()
            .map_or(self.next_id.saturating_add(1), |event| event.id)
    }
}

#[derive(Clone, Serialize, Deserialize)]
struct ProcessRecord {
    command: String,
    running: bool,
    exit_code: Option<i32>,
    #[serde(default)]
    exit_unix_ms: Option<u64>,
    pid: Option<u32>,
    /// Linux `/proc/<pid>/stat` start-time ticks captured when the child was
    /// spawned. A PID is only a locator; this optional identity prevents a
    /// later process that reuses the number from being monitored or signaled.
    #[serde(default)]
    pid_start_time: Option<u64>,
    stdout_bytes: u64,
    stderr_bytes: u64,
}

fn process_output_within_limit(record: &ProcessRecord, additional_bytes: usize) -> bool {
    record
        .stdout_bytes
        .saturating_add(record.stderr_bytes)
        .saturating_add(additional_bytes as u64)
        <= PROCESS_OUTPUT_MAX_BYTES
}

#[derive(Clone, Serialize, Deserialize)]
struct ProcessRequest {
    command: String,
    /// SHA-256 of the original command. Older snapshots did not persist a
    /// hash; those entries are normalized during load. Pruned process
    /// tombstones keep this hash while dropping the potentially large command
    /// body, preserving idempotency without retaining unbounded metadata.
    #[serde(default)]
    command_hash: Option<String>,
    process_id: Uuid,
    started_event_id: u64,
}

#[derive(Clone, Serialize, Deserialize)]
struct FileRequest {
    request_hash: String,
    path: String,
    version: u64,
    sha256: String,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
struct PendingFileMutation {
    request_id: Uuid,
    request_hash: String,
    path: String,
    version: u64,
    sha256: String,
    temporary_path: String,
    backup_path: Option<String>,
    #[serde(default)]
    previous_sha256: Option<String>,
}

type FileTransactionPreparation = (u64, Option<String>, Option<PathBuf>, Option<PathBuf>);

#[derive(Debug, Clone, Serialize, Deserialize)]
struct PendingProcessStart {
    process_id: Uuid,
    request_id: Uuid,
    command: String,
    #[serde(default)]
    pid: Option<u32>,
    #[serde(default)]
    pid_start_time: Option<u64>,
    /// Absolute wall-clock deadline for an attached EXEC, if configured.
    /// Detached SPAWN records leave this absent so a development server can
    /// remain alive indefinitely across daemon restarts.
    #[serde(default)]
    deadline_unix_ms: Option<u64>,
}

#[derive(Debug, Clone, Copy, Serialize, Deserialize)]
struct ProcessTimeoutMetadata {
    /// Unix-millisecond deadline captured when the process was accepted.
    deadline_unix_ms: u64,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
struct PendingFileUpload {
    request_id: Uuid,
    request_hash: String,
    path: String,
    total_size: u64,
    sha256: String,
    /// SHA-256 of the file that the caller based this replacement on.
    #[serde(default)]
    expected_sha256: Option<String>,
    /// Explicitly permit replacing an existing file without a base hash.
    #[serde(default)]
    allow_blind: bool,
}

#[derive(Clone, Serialize, Deserialize)]
struct ArtifactRequest {
    request_hash: String,
    artifact_id: String,
    total_size: u64,
    name: Option<String>,
    #[serde(default)]
    event_id: u64,
}

#[derive(Clone, Serialize, Deserialize)]
struct ArtifactRecord {
    artifact_id: String,
    total_size: u64,
    name: Option<String>,
    created_event_id: u64,
    /// Event timestamp used by retention/GC. Zero denotes a record restored
    /// from a pre-GC snapshot whose creation time was not persisted; unknown
    /// ages are retained rather than guessed.
    #[serde(default)]
    created_unix_ms: u64,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
struct PendingArtifactUpload {
    request_id: Uuid,
    request_hash: String,
    artifact_id: String,
    total_size: u64,
    name: Option<String>,
}

struct FileUploadSpec {
    request_id: Uuid,
    path: String,
    total_size: u64,
    expected_sha256: String,
    expected_base_sha256: Option<String>,
    allow_blind: bool,
    resume: bool,
}

struct ArtifactUploadSpec {
    request_id: Uuid,
    artifact_id: String,
    total_size: u64,
    name: Option<String>,
    resume: bool,
}

#[derive(Clone, Serialize, Deserialize)]
struct SignalRequest {
    request_hash: String,
    process_id: Uuid,
    signal: i32,
    success: bool,
    message: Option<String>,
}

#[derive(Serialize, Deserialize)]
struct SessionSnapshotData {
    session_id: Uuid,
    through_event_id: u64,
    #[serde(default)]
    oldest_event_unix_ms: Option<u64>,
    processes: HashMap<Uuid, ProcessRecord>,
    process_requests: HashMap<Uuid, ProcessRequest>,
    file_versions: HashMap<String, u64>,
    file_requests: HashMap<Uuid, FileRequest>,
    signal_requests: HashMap<Uuid, SignalRequest>,
    #[serde(default)]
    artifact_requests: HashMap<Uuid, ArtifactRequest>,
    #[serde(default)]
    artifacts: HashMap<String, ArtifactRecord>,
    pty_started: bool,
    pty_generation: u64,
}

impl LoadedSession {
    fn from_snapshot(snapshot: SessionSnapshotData) -> Self {
        let mut process_requests = snapshot.process_requests;
        for request in process_requests.values_mut() {
            if request.command_hash.is_none() {
                request.command_hash = Some(sha256(request.command.as_bytes()));
            }
        }
        let running_processes = snapshot
            .processes
            .values()
            .filter(|record| record.running)
            .count();
        Self {
            next_id: snapshot.through_event_id,
            oldest_event_unix_ms: snapshot.oldest_event_unix_ms,
            processes: snapshot.processes,
            process_requests,
            file_versions: snapshot.file_versions,
            file_requests: snapshot.file_requests,
            signal_requests: snapshot.signal_requests,
            artifact_requests: snapshot.artifact_requests,
            artifacts: snapshot.artifacts,
            pty_started: snapshot.pty_started,
            pty_generation: snapshot.pty_generation,
            running_processes,
            event_consumers: HashMap::new(),
            ..Self::default()
        }
    }
}

struct Session {
    id: Uuid,
    /// Authenticated principal that owns this durable session. The owner is
    /// persisted beside the event log and is checked on every attachment.
    owner: Arc<str>,
    /// Serializes materialized state changes with their journal event. Resume
    /// and compaction take this lock first, so a snapshot boundary cannot
    /// observe an event without the corresponding state update (or vice versa).
    commit_lock: Mutex<()>,
    journal: Mutex<Journal>,
    disk: Option<Arc<SessionDisk>>,
    processes: RwLock<HashMap<Uuid, Arc<Mutex<ProcessRecord>>>>,
    process_requests: Mutex<HashMap<Uuid, ProcessRequest>>,
    file_requests: Mutex<HashMap<Uuid, FileRequest>>,
    signal_requests: Mutex<HashMap<Uuid, SignalRequest>>,
    artifact_requests: Mutex<HashMap<Uuid, ArtifactRequest>>,
    artifacts: RwLock<HashMap<String, ArtifactRecord>>,
    /// Durable cumulative event acknowledgements, scoped to this session's
    /// owner.  The sidecar is intentionally separate from the large snapshot
    /// so a heartbeat does not rewrite process/file materialized state.
    event_consumers: Mutex<HashMap<String, EventConsumer>>,
    /// Number of committed or in-flight request IDs across the durable
    /// idempotency tables. Initialized from recovered state and changed only
    /// through `reserve_idempotency_record`.
    idempotency_records: Arc<AtomicUsize>,
    pty: Mutex<Option<Arc<PersistentPty>>>,
    pty_started: AtomicBool,
    pty_generation: AtomicU64,
    running_processes: AtomicUsize,
    active_subscriptions: Arc<AtomicUsize>,
    /// Workspace-wide file versions shared by every durable session attached
    /// to this checkout. The map is rebuilt from all session snapshots/WALs
    /// at startup and advanced only while `SessionStore::workspace_mutation_gate`
    /// is held, so concurrent agents observe one monotonic version per path.
    file_versions: Arc<Mutex<HashMap<PathBuf, u64>>>,
    file_mutations: tokio::sync::Mutex<()>,
    artifact_mutations: tokio::sync::Mutex<()>,
    /// Active artifact readers are leases for retention/GC. GC holds this
    /// map while tombstoning and unlinking an object, so a new GET cannot
    /// race a deletion on platforms that do not permit unlinking open files.
    artifact_readers: Mutex<HashMap<String, usize>>,
    upload_locks: Mutex<HashMap<Uuid, Arc<tokio::sync::Mutex<()>>>>,
    event_tx: broadcast::Sender<Event>,
    root: PathBuf,
    /// `main` canonicalizes the workspace once before opening the store. Keep
    /// that stable identity on each session so every file/path authorization
    /// check does not repeat a filesystem `canonicalize()` of the root on the
    /// Tokio request path.
    canonical_root: PathBuf,
}

struct UploadLockLease {
    session: Arc<Session>,
    request_id: Uuid,
    lock: Arc<tokio::sync::Mutex<()>>,
}

struct ArtifactReadLease<'a> {
    session: &'a Session,
    artifact_id: String,
}

impl Drop for ArtifactReadLease<'_> {
    fn drop(&mut self) {
        let mut readers = self
            .session
            .artifact_readers
            .lock()
            .expect("artifact reader map poisoned");
        if let Some(count) = readers.get_mut(&self.artifact_id) {
            *count = count.saturating_sub(1);
            if *count == 0 {
                readers.remove(&self.artifact_id);
            }
        }
    }
}

/// Remove a temporary workspace file if an upload future is cancelled before
/// the transaction can adopt it. The normal commit path disarms this guard.
/// Cancellation can happen on a Tokio reactor worker, so the best-effort
/// unlink is handed to the blocking pool instead of issuing a synchronous
/// filesystem call from `Drop`; synchronous callers retain a direct fallback.
struct TemporaryPathGuard {
    path: Option<PathBuf>,
}

impl TemporaryPathGuard {
    fn new(path: PathBuf) -> Self {
        Self { path: Some(path) }
    }

    fn disarm(&mut self) {
        self.path = None;
    }
}

impl Drop for TemporaryPathGuard {
    fn drop(&mut self) {
        if let Some(path) = self.path.take() {
            remove_temporary_path_best_effort(path);
        }
    }
}

fn remove_temporary_path_best_effort(path: PathBuf) {
    if tokio::runtime::Handle::try_current().is_ok() {
        drop(tokio::task::spawn_blocking(move || {
            let _ = std::fs::remove_file(path);
        }));
    } else {
        let _ = std::fs::remove_file(path);
    }
}

type EventSubscription = (
    Vec<Event>,
    bool,
    bool,
    u64,
    u64,
    SessionSnapshot,
    broadcast::Receiver<Event>,
);

type ResumeSessionData = (Vec<Event>, bool, bool, u64, SessionSnapshot);

impl Drop for UploadLockLease {
    fn drop(&mut self) {
        self.session
            .release_upload_lock(self.request_id, &self.lock);
    }
}

impl Session {
    #[cfg(test)]
    fn new(root: PathBuf) -> Arc<Self> {
        let session = Self::from_loaded(
            Uuid::new_v4(),
            root,
            None,
            LoadedSession::default(),
            Arc::from("test"),
            Arc::new(Mutex::new(HashMap::new())),
        );
        session
            .append(EventKind::SessionCreated)
            .expect("create test session event");
        session
    }

    fn persisted(
        root: PathBuf,
        id: Uuid,
        directory: PathBuf,
        owner: Arc<str>,
        workspace_file_versions: Arc<Mutex<HashMap<PathBuf, u64>>>,
    ) -> Result<Arc<Self>> {
        let (disk, loaded) = SessionDisk::open(&directory)?;
        write_atomic_file(&directory.join("owner"), owner.as_bytes(), 0o600)?;
        let session =
            Self::from_loaded(id, root, Some(disk), loaded, owner, workspace_file_versions);
        session.append(EventKind::SessionCreated)?;
        Ok(session)
    }

    fn restored(
        id: Uuid,
        root: PathBuf,
        disk: Arc<SessionDisk>,
        loaded: LoadedSession,
        owner: Arc<str>,
        workspace_file_versions: Arc<Mutex<HashMap<PathBuf, u64>>>,
    ) -> Arc<Self> {
        Self::from_loaded(id, root, Some(disk), loaded, owner, workspace_file_versions)
    }

    fn from_loaded(
        id: Uuid,
        root: PathBuf,
        disk: Option<Arc<SessionDisk>>,
        loaded: LoadedSession,
        owner: Arc<str>,
        workspace_file_versions: Arc<Mutex<HashMap<PathBuf, u64>>>,
    ) -> Arc<Self> {
        let LoadedSession {
            events,
            next_id,
            oldest_event_unix_ms,
            processes: loaded_processes,
            process_requests,
            file_versions: loaded_file_versions,
            file_requests,
            signal_requests,
            artifact_requests,
            artifacts,
            pty_started,
            pty_generation,
            running_processes,
            event_consumers,
            ..
        } = loaded;
        let canonical_root = root.canonicalize().unwrap_or_else(|_| root.clone());
        let idempotency_record_count = process_requests
            .len()
            .saturating_add(file_requests.len())
            .saturating_add(signal_requests.len())
            .saturating_add(artifact_requests.len());
        let processes = loaded_processes
            .into_iter()
            .map(|(id, record)| (id, Arc::new(Mutex::new(record))))
            .collect();
        let loaded_file_versions: HashMap<PathBuf, u64> = loaded_file_versions
            .into_iter()
            .filter_map(|(relative, version)| {
                let path = Path::new(&relative);
                let valid = !path.as_os_str().is_empty()
                    && !path.is_absolute()
                    && !path.components().any(|component| {
                        matches!(
                            component,
                            Component::ParentDir | Component::RootDir | Component::Prefix(_)
                        ) || matches!(component, Component::Normal(value) if value == ".asp")
                    });
                valid.then(|| (root.join(path), version))
            })
            .collect();
        // A workspace can have several durable sessions. Rebuild one shared
        // version map from every session as it is loaded; equal paths keep
        // the greatest observed version so restart order cannot regress it.
        {
            let mut workspace_versions = workspace_file_versions
                .lock()
                .expect("file versions poisoned");
            for (path, version) in &loaded_file_versions {
                workspace_versions
                    .entry(path.clone())
                    .and_modify(|current| *current = (*current).max(*version))
                    .or_insert(*version);
            }
        }
        let (event_tx, _) = broadcast::channel(EVENT_SUBSCRIBER_CAPACITY);
        Arc::new(Self {
            id,
            owner,
            commit_lock: Mutex::new(()),
            journal: Mutex::new(Journal::from_loaded(events, next_id, oldest_event_unix_ms)),
            disk,
            processes: RwLock::new(processes),
            process_requests: Mutex::new(process_requests),
            file_requests: Mutex::new(file_requests),
            signal_requests: Mutex::new(signal_requests),
            artifact_requests: Mutex::new(artifact_requests),
            artifacts: RwLock::new(artifacts),
            event_consumers: Mutex::new(event_consumers),
            idempotency_records: Arc::new(AtomicUsize::new(idempotency_record_count)),
            pty: Mutex::new(None),
            pty_started: AtomicBool::new(pty_started),
            pty_generation: AtomicU64::new(pty_generation),
            running_processes: AtomicUsize::new(running_processes),
            active_subscriptions: Arc::new(AtomicUsize::new(0)),
            file_versions: workspace_file_versions,
            file_mutations: tokio::sync::Mutex::new(()),
            artifact_mutations: tokio::sync::Mutex::new(()),
            artifact_readers: Mutex::new(HashMap::new()),
            upload_locks: Mutex::new(HashMap::new()),
            event_tx,
            root,
            canonical_root,
        })
    }

    fn upload_lock(&self, request_id: Uuid) -> Arc<tokio::sync::Mutex<()>> {
        let mut locks = self.upload_locks.lock().expect("upload lock map poisoned");
        Arc::clone(
            locks
                .entry(request_id)
                .or_insert_with(|| Arc::new(tokio::sync::Mutex::new(()))),
        )
    }

    fn release_upload_lock(&self, request_id: Uuid, lock: &Arc<tokio::sync::Mutex<()>>) {
        let mut locks = self.upload_locks.lock().expect("upload lock map poisoned");
        if locks
            .get(&request_id)
            .is_some_and(|current| Arc::ptr_eq(current, lock) && Arc::strong_count(current) == 2)
        {
            locks.remove(&request_id);
        }
    }

    fn append(&self, kind: EventKind) -> Result<Event> {
        let _commit = self.commit_lock.lock().expect("commit lock poisoned");
        self.append_locked_off_reactor(kind)
    }

    /// Append while the caller already owns `commit_lock` and is updating
    /// materialized state as one transaction.
    fn append_locked(&self, kind: EventKind) -> Result<Event> {
        let mut journal = self.journal.lock().expect("journal poisoned");
        let event = journal.append(kind);
        if let Some(disk) = &self.disk {
            if let Err(error) = disk.append(&event) {
                journal.rollback(&event);
                return Err(error).with_context(|| format!("persist ASP event {}", event.id));
            }
        }
        // Publish file-version materialization before notifying subscribers.
        // A subscriber that reacts to FILE_MUTATION/FILE_CHANGED may issue a
        // read immediately; sharing the clock here prevents it from seeing
        // the event while still observing the previous version number.
        match &event.kind {
            EventKind::FileChanged { path, version }
            | EventKind::FileMutation { path, version, .. } => {
                if let Some(resolved) = workspace_event_path(&self.root, path) {
                    self.file_versions
                        .lock()
                        .expect("file versions poisoned")
                        .entry(resolved)
                        .and_modify(|current| *current = (*current).max(*version))
                        .or_insert(*version);
                }
            }
            _ => {}
        }
        journal.enforce_bounds();
        if matches!(&event.kind, EventKind::PtyStarted) {
            self.pty_started.store(true, Ordering::Release);
        }
        if let EventKind::PtyStateAdvanced { generation } = &event.kind {
            self.pty_generation.store(*generation, Ordering::Release);
        }
        if matches!(&event.kind, EventKind::ProcessExited { .. }) {
            self.release_process_slot();
        }
        // The durable journal is the source of truth. A live subscriber only
        // receives a best-effort copy; a lagged receiver must reconnect and
        // use its durable cursor through RESUME_SESSION_STREAM.
        let _ = self.event_tx.send(event.clone());
        Ok(event)
    }

    /// Persist an event without pinning a Tokio reactor worker during the
    /// synchronous WAL write/fsync path.  The commit lock is deliberately
    /// still held by the caller, so event numbering, materialized state, and
    /// publication retain the same transaction ordering.  `block_in_place`
    /// is safe on the daemon's multi-thread runtime and keeps the borrowed
    /// session/event lifetime intact; current-thread runtimes and synchronous
    /// startup/tests use the direct path because Tokio rejects blocking-in-
    /// place there.
    fn append_locked_off_reactor(&self, kind: EventKind) -> Result<Event> {
        let can_block_in_place = tokio::runtime::Handle::try_current().is_ok_and(|handle| {
            matches!(
                handle.runtime_flavor(),
                tokio::runtime::RuntimeFlavor::MultiThread
            )
        });
        if can_block_in_place {
            tokio::task::block_in_place(|| self.append_locked(kind))
        } else {
            self.append_locked(kind)
        }
    }

    /// Return whether this session already durably contains one external file
    /// notification. The check is intentionally scoped to the retained
    /// journal and is called while the session commit lock is held by the
    /// caller. A partially delivered workspace fan-out can therefore retry
    /// the same path/version without appending a duplicate event to sessions
    /// whose WAL accepted it before a later session failed.
    fn has_file_changed_event_locked(&self, path: &str, version: u64) -> bool {
        self.journal
            .lock()
            .expect("journal poisoned")
            .events
            .iter()
            .any(|event| {
                matches!(
                    &event.kind,
                    EventKind::FileChanged {
                        path: event_path,
                        version: event_version,
                    } if event_path == path && *event_version == version
                )
            })
    }

    fn has_file_changed_event(&self, path: &str, version: u64) -> bool {
        let _commit = self.commit_lock.lock().expect("commit lock poisoned");
        self.has_file_changed_event_locked(path, version)
    }

    fn subscribe_events(&self, after_event_id: u64) -> Result<EventSubscription> {
        let _commit = self.commit_lock.lock().expect("commit lock poisoned");
        let journal = self.journal.lock().expect("journal poisoned");
        if after_event_id > journal.next_id {
            bail!(
                "subscription cursor {after_event_id} is ahead of journal head {}",
                journal.next_id
            );
        }
        let (events, compacted, replay_limited) =
            self.events_since_locked(&journal, after_event_id)?;
        let retained_from_event_id = journal.retained_from_event_id();
        let through_event_id = journal.next_id;
        let snapshot = self.snapshot_at_locked(through_event_id);
        // Subscribe while commit_lock is held. Any append after this point is
        // ordered after the backlog boundary and therefore cannot be missed.
        let receiver = self.event_tx.subscribe();
        Ok((
            events,
            compacted,
            replay_limited,
            retained_from_event_id,
            through_event_id,
            snapshot,
            receiver,
        ))
    }

    fn events_since_locked(
        &self,
        journal: &Journal,
        after_event_id: u64,
    ) -> Result<(Vec<Event>, bool, bool)> {
        let (events, compacted) = journal.since(after_event_id);
        if !compacted {
            return Ok((events, false, false));
        }
        let Some(disk) = &self.disk else {
            return Ok((events, true, false));
        };
        let snapshot_boundary = disk.snapshot_boundary.load(Ordering::Acquire);
        if after_event_id < snapshot_boundary {
            return Ok((Vec::new(), true, false));
        }
        let Some(durable) = disk.read_events_since(after_event_id)? else {
            // Replaying a very large durable tail costs more than rebuilding
            // from the current materialized snapshot. This is the same
            // recoverable compaction signal used when the in-memory journal
            // has evicted the cursor's history.
            return Ok((Vec::new(), true, true));
        };
        if durable.is_empty() && after_event_id < journal.next_id {
            // The cursor is within the post-snapshot WAL range but no event
            // could be recovered; retain the explicit compacted signal rather
            // than pretending that a gap is a clean empty replay.
            return Ok((Vec::new(), true, false));
        }
        Ok((durable, false, false))
    }

    fn ack_event_consumer(&self, consumer_id: &str, through_event_id: u64) -> Result<u64> {
        validate_event_consumer_id(consumer_id)?;
        let _commit = self.commit_lock.lock().expect("commit lock poisoned");
        let head = self.journal.lock().expect("journal poisoned").next_id;
        if through_event_id > head {
            bail!("ack cursor {through_event_id} is ahead of journal head {head}");
        }
        let now = unix_ms();
        let mut consumers = self
            .event_consumers
            .lock()
            .expect("event consumer map poisoned");
        let previous = consumers.clone();
        let acknowledged = consumers
            .get(consumer_id)
            .map_or(through_event_id, |existing| {
                existing.acknowledged_event_id.max(through_event_id)
            });
        if !consumers.contains_key(consumer_id)
            && consumers.len() >= MAX_EVENT_CONSUMERS_PER_SESSION
        {
            bail!("event consumer capacity reached ({MAX_EVENT_CONSUMERS_PER_SESSION})");
        }
        consumers.insert(
            consumer_id.to_owned(),
            EventConsumer {
                acknowledged_event_id: acknowledged,
                last_seen_unix_ms: now,
            },
        );
        if let Some(disk) = &self.disk
            && let Err(error) = disk.persist_event_consumers(&consumers)
        {
            *consumers = previous;
            return Err(error).context("persist event consumer acknowledgement");
        }
        Ok(acknowledged)
    }

    /// Expire abandoned consumers while holding the per-session commit lock.
    /// Returning whether the sidecar changed lets maintenance report a clean
    /// no-op when only a heartbeat lease was removed.
    fn prune_expired_event_consumers_locked(&self, now: u64) -> Result<bool> {
        let mut consumers = self
            .event_consumers
            .lock()
            .expect("event consumer map poisoned");
        let previous = consumers.clone();
        consumers.retain(|_, consumer| {
            consumer
                .last_seen_unix_ms
                .saturating_add(EVENT_CONSUMER_LEASE.as_millis().min(u64::MAX as u128) as u64)
                > now
        });
        if *consumers == previous {
            return Ok(false);
        }
        if let Some(disk) = &self.disk
            && let Err(error) = disk.persist_event_consumers(&consumers)
        {
            *consumers = previous;
            return Err(error).context("persist expired event consumer leases");
        }
        Ok(true)
    }

    fn event_consumer_count(&self) -> usize {
        self.event_consumers
            .lock()
            .expect("event consumer map poisoned")
            .len()
    }

    fn persistent_processes(&self) -> Vec<(Uuid, Arc<Mutex<ProcessRecord>>)> {
        self.processes
            .read()
            .expect("process map poisoned")
            .iter()
            .filter_map(|(id, record)| {
                let running = record.lock().expect("process record poisoned").running;
                running.then_some((*id, Arc::clone(record)))
            })
            .collect()
    }

    fn reserve_process_slot(&self) -> Result<()> {
        self.running_processes
            .fetch_update(Ordering::AcqRel, Ordering::Acquire, |running| {
                (running < MAX_RUNNING_PROCESSES).then_some(running + 1)
            })
            .map(|_| ())
            .map_err(|_| anyhow!("session already has {MAX_RUNNING_PROCESSES} running processes"))
    }

    /// Reserve one durable request-ID record before executing a new
    /// side-effect. Existing IDs must be checked by the caller first; this
    /// method only admits a new entry and is safe under concurrent streams.
    fn reserve_idempotency_record(&self) -> Result<IdempotencyReservation> {
        self.idempotency_records
            .fetch_update(Ordering::AcqRel, Ordering::Acquire, |count| {
                (count < MAX_IDEMPOTENCY_RECORDS_PER_SESSION).then_some(count + 1)
            })
            .map(|_| IdempotencyReservation {
                records: Arc::clone(&self.idempotency_records),
                committed: false,
            })
            .map_err(|_| {
                anyhow!(
                    "idempotency_capacity: session has reached the {MAX_IDEMPOTENCY_RECORDS_PER_SESSION} request-record limit"
                )
            })
    }

    fn idempotency_record_count(&self) -> usize {
        self.idempotency_records.load(Ordering::Acquire)
    }

    /// Release a durable request-record slot when retention removes its
    /// corresponding artifact. The event tombstone is persisted before this
    /// counter changes, so a crash cannot make capacity appear free while the
    /// old record is still replayable.
    fn release_idempotency_record(&self) {
        let _ =
            self.idempotency_records
                .fetch_update(Ordering::AcqRel, Ordering::Acquire, |count| {
                    (count > 0).then_some(count - 1)
                });
    }

    fn artifact_directory(&self) -> Result<PathBuf> {
        let directory = self
            .disk
            .as_ref()
            .ok_or_else(|| anyhow!("session is not persisted"))?
            .directory
            .join("artifacts");
        ensure_private_directory(&directory)?;
        Ok(directory)
    }

    fn artifact_path(&self, artifact_id: &str) -> Result<PathBuf> {
        let artifact_id = canonical_artifact_id(artifact_id)?;
        let directory = self.artifact_directory()?;
        let path = directory.join(&artifact_id);
        reject_symlink(&path)?;
        Ok(path)
    }

    fn artifact_record(&self, artifact_id: &str) -> Result<Option<ArtifactRecord>> {
        let artifact_id = canonical_artifact_id(artifact_id)?;
        Ok(self
            .artifacts
            .read()
            .expect("artifact map poisoned")
            .get(&artifact_id)
            .cloned())
    }

    /// Acquire a lease before opening an artifact. The reader map is checked
    /// together with the materialized metadata so retention can atomically
    /// make an object unavailable before unlinking it.
    fn artifact_read_lease(&self, artifact_id: &str) -> Result<ArtifactReadLease<'_>> {
        let artifact_id = canonical_artifact_id(artifact_id)?;
        let mut readers = self
            .artifact_readers
            .lock()
            .expect("artifact reader map poisoned");
        if !self
            .artifacts
            .read()
            .expect("artifact map poisoned")
            .contains_key(&artifact_id)
        {
            bail!("unknown artifact {artifact_id}");
        }
        let count = readers.entry(artifact_id.clone()).or_default();
        *count = count
            .checked_add(1)
            .ok_or_else(|| anyhow!("artifact reader count overflow"))?;
        Ok(ArtifactReadLease {
            session: self,
            artifact_id,
        })
    }

    fn artifact_bytes(&self) -> u64 {
        self.artifacts
            .read()
            .expect("artifact map poisoned")
            .values()
            .map(|record| record.total_size)
            .fold(0_u64, u64::saturating_add)
    }

    /// Account for a request record reconstructed from a durable transaction
    /// intent during startup. Recovery must finish an accepted mutation even
    /// when the pre-crash reservation was not itself persisted; this may put
    /// occupancy one slot above the normal limit, after which new side effects
    /// remain blocked until an operator migrates/rotates the session.
    fn record_recovered_idempotency_record(&self) {
        self.idempotency_records.fetch_add(1, Ordering::AcqRel);
    }

    fn release_process_slot(&self) {
        let _ =
            self.running_processes
                .fetch_update(Ordering::AcqRel, Ordering::Acquire, |running| {
                    (running > 0).then_some(running - 1)
                });
    }

    fn subscription_guard(&self) -> Result<SubscriptionGuard> {
        self.active_subscriptions
            .fetch_update(Ordering::AcqRel, Ordering::Acquire, |active| {
                (active < MAX_ACTIVE_SUBSCRIPTIONS_PER_SESSION).then_some(active + 1)
            })
            .map(|_| SubscriptionGuard(Arc::clone(&self.active_subscriptions)))
            .map_err(|_| {
                anyhow!(
                    "session already has {MAX_ACTIVE_SUBSCRIPTIONS_PER_SESSION} active subscriptions"
                )
            })
    }

    fn has_pty(&self) -> bool {
        self.pty_started.load(Ordering::Acquire)
    }

    fn pty_generation(&self) -> u64 {
        self.pty_generation.load(Ordering::Acquire)
    }

    fn snapshot(&self) -> SessionSnapshot {
        let _commit = self.commit_lock.lock().expect("commit lock poisoned");
        let latest_event_id = self.journal.lock().expect("journal poisoned").next_id;
        self.snapshot_at_locked(latest_event_id)
    }

    fn snapshot_at_locked(&self, latest_event_id: u64) -> SessionSnapshot {
        let processes = self
            .processes
            .read()
            .expect("process map poisoned")
            .iter()
            .map(|(id, record)| {
                let record = record.lock().expect("process record poisoned");
                ProcessSnapshot {
                    process_id: *id,
                    command: record.command.clone(),
                    running: record.running,
                    exit_code: record.exit_code,
                    stdout_bytes: record.stdout_bytes,
                    stderr_bytes: record.stderr_bytes,
                }
            })
            .collect();
        let pty = self
            .pty
            .lock()
            .expect("PTY slot poisoned")
            .as_ref()
            .map(|pty| {
                let value = pty.snapshot();
                protocol_pty_snapshot(value)
            });
        SessionSnapshot {
            session_id: self.id,
            latest_event_id,
            processes,
            pty,
        }
    }

    /// Return one process's current materialized state without constructing
    /// the complete session snapshot. Detached agents use this cheap read to
    /// decide whether a durable log range is still growing or whether the
    /// process has exited, avoiding a full RESUME payload on every poll.
    fn process_snapshot(&self, process_id: Uuid) -> Result<Option<ProcessSnapshot>> {
        let _commit = self.commit_lock.lock().expect("commit lock poisoned");
        let record = self
            .processes
            .read()
            .expect("process map poisoned")
            .get(&process_id)
            .cloned();
        Ok(record.map(|record| {
            let record = record.lock().expect("process record poisoned");
            ProcessSnapshot {
                process_id,
                command: record.command.clone(),
                running: record.running,
                exit_code: record.exit_code,
                stdout_bytes: record.stdout_bytes,
                stderr_bytes: record.stderr_bytes,
            }
        }))
    }

    #[cfg(test)]
    fn snapshot_data_locked(&self, through_event_id: u64) -> Result<SessionSnapshotData> {
        let oldest_event_unix_ms = self
            .journal
            .lock()
            .expect("journal poisoned")
            .oldest_event_unix_ms;
        self.snapshot_data_with_oldest(through_event_id, oldest_event_unix_ms)
    }

    #[cfg(test)]
    fn snapshot_data_with_oldest(
        &self,
        through_event_id: u64,
        oldest_event_unix_ms: Option<u64>,
    ) -> Result<SessionSnapshotData> {
        self.snapshot_data_filtered(through_event_id, oldest_event_unix_ms, None)
    }

    fn snapshot_data_filtered(
        &self,
        through_event_id: u64,
        oldest_event_unix_ms: Option<u64>,
        pruned_processes: Option<&HashSet<Uuid>>,
    ) -> Result<SessionSnapshotData> {
        let processes = self
            .processes
            .read()
            .expect("process map poisoned")
            .iter()
            .filter(|(id, _)| pruned_processes.is_none_or(|pruned| !pruned.contains(id)))
            .map(|(id, record)| (*id, record.lock().expect("process record poisoned").clone()))
            .collect();
        let process_requests = self
            .process_requests
            .lock()
            .expect("request map poisoned")
            .iter()
            .map(|(request_id, request)| {
                let mut request = request.clone();
                if pruned_processes.is_some_and(|pruned| pruned.contains(&request.process_id)) {
                    if request.command_hash.is_none() {
                        request.command_hash = Some(sha256(request.command.as_bytes()));
                    }
                    request.command.clear();
                } else if request.command_hash.is_none() {
                    request.command_hash = Some(sha256(request.command.as_bytes()));
                }
                (*request_id, request)
            })
            .collect();
        let file_versions = self
            .file_versions
            .lock()
            .expect("file versions poisoned")
            .iter()
            .filter_map(|(path, version)| {
                path.strip_prefix(&self.root)
                    .ok()
                    .and_then(|relative| relative.to_str())
                    .map(|relative| (relative.trim_start_matches('/').to_owned(), *version))
            })
            .collect();
        let file_requests = self
            .file_requests
            .lock()
            .expect("file request map poisoned")
            .clone();
        let signal_requests = self
            .signal_requests
            .lock()
            .expect("signal request map poisoned")
            .clone();
        let artifact_requests = self
            .artifact_requests
            .lock()
            .expect("artifact request map poisoned")
            .clone();
        let artifacts = self
            .artifacts
            .read()
            .expect("artifact map poisoned")
            .clone();
        Ok(SessionSnapshotData {
            session_id: self.id,
            through_event_id,
            oldest_event_unix_ms,
            processes,
            process_requests,
            file_versions,
            file_requests,
            signal_requests,
            artifact_requests,
            artifacts,
            pty_started: self.pty_started.load(Ordering::Acquire),
            pty_generation: self.pty_generation(),
        })
    }

    fn compact_if_needed(&self, retention: Option<Duration>) -> Result<bool> {
        let Some(disk) = &self.disk else {
            return Ok(false);
        };
        let _commit = self.commit_lock.lock().expect("commit lock poisoned");
        let consumers_pruned = self.prune_expired_event_consumers_locked(unix_ms())?;
        let mut journal = self.journal.lock().expect("journal poisoned");
        let size_due = disk.len()? >= EVENT_LOG_COMPACT_THRESHOLD;
        let age_due = retention.is_some_and(|retention| {
            let retention_ms = retention.as_millis().min(u64::MAX as u128) as u64;
            journal
                .oldest_event_unix_ms
                .is_some_and(|oldest| unix_ms().saturating_sub(oldest) >= retention_ms)
        });
        if !size_due && !age_due {
            return Ok(consumers_pruned);
        }
        // A compacted snapshot advances the replay boundary to the current
        // journal head.  Never cross an unexpired named consumer's durable
        // acknowledgement: that would turn a reconnect into a silent loss
        // of events.  Once every consumer catches up (or expires), the next
        // maintenance pass can compact normally.
        let head = journal.next_id;
        let blocked = self
            .event_consumers
            .lock()
            .expect("event consumer map poisoned")
            .values()
            .any(|consumer| consumer.acknowledged_event_id < head);
        if blocked {
            debug!(
                session = %self.id,
                head,
                "event-log compaction deferred by an unacknowledged consumer"
            );
            return Ok(consumers_pruned);
        }
        // A compacted snapshot is the new replay boundary. Do not persist an
        // old event timestamp in it or maintenance would compact the same
        // idle session forever.
        let prune_before = retention.map(|retention| {
            let retention_ms = retention.as_millis().min(u64::MAX as u128) as u64;
            unix_ms().saturating_sub(retention_ms)
        });
        let pruned_processes = prune_before.map(|cutoff| {
            self.processes
                .read()
                .expect("process map poisoned")
                .iter()
                .filter_map(|(process_id, record)| {
                    let record = record.lock().expect("process record poisoned");
                    (!record.running
                        && record
                            .exit_unix_ms
                            .is_some_and(|finished| finished <= cutoff))
                    .then_some(*process_id)
                })
                .collect::<HashSet<_>>()
        });
        let mut snapshot = self.snapshot_data_filtered(
            journal.next_id,
            journal.oldest_event_unix_ms,
            pruned_processes.as_ref(),
        )?;
        snapshot.oldest_event_unix_ms = None;
        disk.compact(&snapshot)?;
        journal.events.clear();
        journal.approx_bytes = 0;
        journal.oldest_event_unix_ms = None;
        if let Some(pruned_processes) = pruned_processes {
            if !pruned_processes.is_empty() {
                let mut processes = self.processes.write().expect("process map poisoned");
                for process_id in &pruned_processes {
                    processes.remove(process_id);
                }
            }
            let mut process_requests = self.process_requests.lock().expect("request map poisoned");
            for request in process_requests.values_mut() {
                if pruned_processes.contains(&request.process_id) {
                    if request.command_hash.is_none() {
                        request.command_hash = Some(sha256(request.command.as_bytes()));
                    }
                    request.command.clear();
                }
            }
        }
        Ok(true)
    }

    /// Reconcile a process that may have been spawned while the daemon was
    /// crossing the event-journal boundary. A live uncommitted child is only
    /// terminated when its command line still names ASP's private wrapper;
    /// otherwise startup fails rather than risking an unrelated process.
    fn recover_pending_process_starts(&self) -> Result<()> {
        let Some(disk) = &self.disk else {
            return Ok(());
        };
        let directory = disk.directory.join("transactions");
        let metadata = match std::fs::symlink_metadata(&directory) {
            Ok(metadata) => metadata,
            Err(error) if error.kind() == std::io::ErrorKind::NotFound => return Ok(()),
            Err(error) => return Err(error.into()),
        };
        if metadata.file_type().is_symlink() || !metadata.is_dir() {
            bail!(
                "ASP transaction directory is not a regular directory: {}",
                directory.display()
            );
        };
        let entries = std::fs::read_dir(&directory)?;
        let mut entries = entries.collect::<std::result::Result<Vec<_>, _>>()?;
        entries.sort_by_key(|entry| entry.file_name());
        for entry in entries {
            let metadata = std::fs::symlink_metadata(entry.path())?;
            let name = entry.file_name().to_string_lossy().into_owned();
            let Some(stem) = name
                .strip_prefix("process-")
                .and_then(|value| value.strip_suffix(".json"))
            else {
                continue;
            };
            if !metadata.is_file() || stem.parse::<Uuid>().ok().is_none() {
                bail!("invalid pending process intent {}", entry.path().display());
            }
            let pending: PendingProcessStart = serde_json::from_slice(
                &read_file_limited(&entry.path(), MAX_PENDING_METADATA_BYTES).with_context(
                    || format!("read pending process start {}", entry.path().display()),
                )?,
            )
            .with_context(|| format!("decode pending process start {}", entry.path().display()))?;
            if pending.process_id.to_string() != stem
                || pending.command.is_empty()
                || pending.command.len() > COMMAND_MAX_BYTES
            {
                bail!("invalid pending process start {}", entry.path().display());
            }
            let committed = self
                .process_requests
                .lock()
                .expect("request map poisoned")
                .get(&pending.request_id)
                .is_some_and(|request| {
                    request.process_id == pending.process_id && request.command == pending.command
                });
            if committed {
                clear_pending_process_start(&entry.path())?;
                continue;
            }
            let paths = ProcessPaths::new(self, pending.process_id)?;
            if let Some(pid) = pending.pid {
                if process_is_alive(Some(pid)) {
                    if !process_identity_matches(pid, &paths.wrapper, pending.pid_start_time) {
                        bail!(
                            "pending process {} has a live PID that is not ASP's wrapper/identity",
                            pending.process_id
                        );
                    }
                    terminate_process(Some(pid), pending.pid_start_time);
                    for _ in 0..100 {
                        if !process_is_alive(Some(pid)) {
                            break;
                        }
                        std::thread::sleep(Duration::from_millis(10));
                    }
                    if process_is_alive(Some(pid)) {
                        force_terminate_process(Some(pid), pending.pid_start_time);
                    }
                    if process_is_alive(Some(pid)) {
                        bail!(
                            "could not terminate uncommitted process {}",
                            pending.process_id
                        );
                    }
                }
            } else {
                bail!(
                    "pending process {} has no durable PID; inspect and resolve {} before restart",
                    pending.process_id,
                    entry.path().display()
                );
            }
            clear_pending_process_start(&entry.path())?;
            remove_process_artifacts(&paths)?;
        }
        Ok(())
    }

    /// Reconcile file writes that crossed the filesystem/journal boundary
    /// while the daemon was being stopped. Intent files are written before
    /// renames; a matching target is committed to the event log, while an
    /// incomplete transaction is rolled back. Ambiguous state fails startup
    /// instead of silently choosing a version.
    fn recover_pending_file_mutations(&self) -> Result<()> {
        let Some(disk) = &self.disk else {
            return Ok(());
        };
        let directory = disk.directory.join("transactions");
        let metadata = match std::fs::symlink_metadata(&directory) {
            Ok(metadata) => metadata,
            Err(error) if error.kind() == std::io::ErrorKind::NotFound => return Ok(()),
            Err(error) => return Err(error.into()),
        };
        if metadata.file_type().is_symlink() || !metadata.is_dir() {
            bail!(
                "ASP transaction directory is not a regular directory: {}",
                directory.display()
            );
        };
        let entries = std::fs::read_dir(&directory)?;
        let mut entries = entries.collect::<std::result::Result<Vec<_>, _>>()?;
        entries.sort_by_key(|entry| entry.file_name());
        for entry in entries {
            let metadata = std::fs::symlink_metadata(entry.path())?;
            if metadata.file_type().is_symlink() {
                bail!(
                    "refusing symlink in ASP transaction directory {}",
                    entry.path().display()
                );
            }
            if !metadata.is_file()
                || entry.path().extension().is_none_or(|ext| ext != "json")
                || entry
                    .path()
                    .file_name()
                    .is_some_and(|name| name.to_string_lossy().starts_with("process-"))
            {
                continue;
            }
            let pending: PendingFileMutation = serde_json::from_slice(
                &read_file_limited(&entry.path(), MAX_PENDING_METADATA_BYTES).with_context(
                    || format!("read pending file mutation {}", entry.path().display()),
                )?,
            )
            .with_context(|| format!("decode pending file mutation {}", entry.path().display()))?;
            let entry_path = entry.path();
            let Some(stem) = entry_path.file_stem() else {
                bail!("invalid pending file mutation {}", entry_path.display());
            };
            if pending.request_id.to_string() != stem.to_string_lossy()
                || !valid_sha256(&pending.sha256)
                || pending.path.is_empty()
                || pending.temporary_path.is_empty()
                || pending.request_hash.is_empty()
                || pending
                    .previous_sha256
                    .as_deref()
                    .is_some_and(|value| !valid_sha256(value))
            {
                bail!("invalid pending file mutation {}", entry.path().display());
            }
            let target = self.resolve_write_path(&pending.path)?;
            if let Some(metadata) = std::fs::symlink_metadata(&target).ok()
                && (metadata.file_type().is_symlink() || !metadata.is_file())
            {
                bail!(
                    "pending file mutation {} targets a non-regular file",
                    pending.request_id
                );
            }
            if let Some(previous) = self
                .file_requests
                .lock()
                .expect("file request map poisoned")
                .get(&pending.request_id)
                .cloned()
            {
                if previous.request_hash != pending.request_hash
                    || previous.path != pending.path
                    || previous.sha256 != pending.sha256
                {
                    bail!("pending file mutation conflicts with its committed event");
                }
                let target_digest = digest_file_sync(&target).ok().map(|(_, digest)| digest);
                if target_digest.as_deref() != Some(pending.sha256.as_str()) {
                    bail!(
                        "committed file mutation {} is missing or has an unexpected target hash",
                        pending.request_id
                    );
                }
                cleanup_pending_file_mutation(self, &pending, &entry.path())?;
                continue;
            }
            let temporary = self.resolve_internal_path(&pending.temporary_path)?;
            let backup = pending
                .backup_path
                .as_deref()
                .map(|path| self.resolve_internal_path(path))
                .transpose()?;
            let temporary_exists = std::fs::symlink_metadata(&temporary)
                .ok()
                .is_some_and(|metadata| metadata.is_file());
            let backup_exists = backup
                .as_ref()
                .and_then(|path| std::fs::symlink_metadata(path).ok())
                .is_some_and(|metadata| metadata.is_file());
            let target_matches = target.is_file()
                && digest_file_sync(&target)
                    .map(|(_, digest)| digest == pending.sha256)
                    .unwrap_or(false);
            if target_matches {
                let _commit = self.commit_lock.lock().expect("commit lock poisoned");
                let current_version = self
                    .file_versions
                    .lock()
                    .expect("file versions poisoned")
                    .get(&target)
                    .copied()
                    .unwrap_or(0);
                if current_version >= pending.version {
                    bail!(
                        "pending file mutation {} has a stale version",
                        pending.request_id
                    );
                }
                let event = self.append_locked_off_reactor(EventKind::FileMutation {
                    request_id: pending.request_id,
                    request_hash: pending.request_hash.clone(),
                    path: pending.path.clone(),
                    version: pending.version,
                    sha256: pending.sha256.clone(),
                })?;
                debug_assert_eq!(
                    event.kind,
                    EventKind::FileMutation {
                        request_id: pending.request_id,
                        request_hash: pending.request_hash.clone(),
                        path: pending.path.clone(),
                        version: pending.version,
                        sha256: pending.sha256.clone(),
                    }
                );
                self.file_versions
                    .lock()
                    .expect("file versions poisoned")
                    .insert(target.clone(), pending.version);
                self.file_requests
                    .lock()
                    .expect("file request map poisoned")
                    .insert(
                        pending.request_id,
                        FileRequest {
                            request_hash: pending.request_hash.clone(),
                            path: pending.path.clone(),
                            version: pending.version,
                            sha256: pending.sha256.clone(),
                        },
                    );
                self.record_recovered_idempotency_record();
                drop(_commit);
                if let Some(backup) = backup {
                    let _ = std::fs::remove_file(backup);
                }
                let _ = std::fs::remove_file(temporary);
                clear_pending_file_mutation(&entry.path())?;
                continue;
            }
            if target.exists() {
                // If the target still has its pre-transaction digest and no
                // backup was moved away, the daemon died before installing
                // the temporary file. Remove only our temporary and leave
                // the workspace untouched. Anything else is ambiguous.
                let target_digest = digest_file_sync(&target).ok().map(|(_, digest)| digest);
                if !backup_exists
                    && pending.previous_sha256.is_some()
                    && target_digest == pending.previous_sha256
                {
                    if temporary_exists {
                        std::fs::remove_file(&temporary)?;
                        sync_directory(temporary.parent().unwrap_or(&self.root))?;
                    }
                    clear_pending_file_mutation(&entry.path())?;
                    continue;
                }
                bail!(
                    "pending file mutation {} has an unexpected target state",
                    pending.request_id
                );
            }
            if let Some(backup) = backup {
                if backup_exists {
                    let backup_digest = digest_file_sync(&backup).ok().map(|(_, digest)| digest);
                    if backup_digest != pending.previous_sha256 {
                        bail!(
                            "pending file mutation {} has a corrupt rollback backup",
                            pending.request_id
                        );
                    }
                    std::fs::rename(&backup, &target).with_context(|| {
                        format!("roll back pending file mutation {}", pending.request_id)
                    })?;
                    sync_directory(target.parent().unwrap_or(&self.root))?;
                } else if !temporary_exists {
                    bail!(
                        "pending file mutation {} lost both target and backup",
                        pending.request_id
                    );
                }
            } else if !temporary_exists {
                bail!(
                    "pending file mutation {} has no recoverable file",
                    pending.request_id
                );
            }
            if temporary_exists {
                std::fs::remove_file(&temporary)?;
                sync_directory(temporary.parent().unwrap_or(&self.root))?;
            }
            clear_pending_file_mutation(&entry.path())?;
        }
        Ok(())
    }

    fn resolve_path(&self, relative: &str) -> Result<PathBuf> {
        if relative.is_empty()
            || relative.len() > PATH_MAX_BYTES
            || relative.as_bytes().contains(&0)
        {
            bail!("path must be 1..{PATH_MAX_BYTES} bytes and contain no NUL");
        }
        let path = Path::new(relative);
        if path.is_absolute()
            || path.components().any(|part| {
                matches!(
                    part,
                    Component::ParentDir | Component::RootDir | Component::Prefix(_)
                )
            })
        {
            bail!("path must be a non-empty relative path without '..'");
        }
        if path
            .components()
            .any(|component| matches!(component, Component::Normal(value) if value == ".asp"))
        {
            bail!(".asp is reserved for ASP server state");
        }
        Ok(self.root.join(path))
    }

    fn resolve_existing_path(&self, relative: &str) -> Result<PathBuf> {
        let path = self.resolve_path(relative)?;
        let canonical = path
            .canonicalize()
            .with_context(|| format!("resolve workspace path {relative:?}"))?;
        if !canonical.starts_with(&self.canonical_root) {
            bail!("workspace path escapes the configured root");
        }
        Ok(canonical)
    }

    fn resolve_write_path(&self, relative: &str) -> Result<PathBuf> {
        let path = self.resolve_path(relative)?;
        let mut ancestor = path.as_path();
        while !ancestor.exists() {
            ancestor = ancestor
                .parent()
                .ok_or_else(|| anyhow!("workspace path has no existing parent"))?;
        }
        let canonical_ancestor = ancestor.canonicalize()?;
        if !canonical_ancestor.starts_with(&self.canonical_root) {
            bail!("workspace path parent escapes the configured root");
        }
        Ok(path)
    }

    /// Resolve a daemon-owned path recorded in durable transaction metadata.
    /// Unlike a client workspace path this may live below `.asp`, but it is
    /// still relative to the configured root and must not escape through an
    /// existing parent symlink.
    fn resolve_internal_path(&self, relative: &str) -> Result<PathBuf> {
        if relative.is_empty()
            || relative.len() > PATH_MAX_BYTES
            || relative.as_bytes().contains(&0)
        {
            bail!("internal path must be 1..{PATH_MAX_BYTES} bytes and contain no NUL");
        }
        let path = Path::new(relative);
        if path.is_absolute()
            || path.components().any(|part| {
                matches!(
                    part,
                    Component::ParentDir | Component::RootDir | Component::Prefix(_)
                )
            })
        {
            bail!("internal path must be relative and contain no '..'");
        }
        let resolved = self.root.join(path);
        reject_symlink(&resolved)?;
        let mut ancestor = resolved.as_path();
        while !ancestor.exists() {
            ancestor = ancestor
                .parent()
                .ok_or_else(|| anyhow!("internal path has no existing parent"))?;
        }
        if !ancestor.canonicalize()?.starts_with(&self.canonical_root) {
            bail!("internal path escapes the configured root");
        }
        Ok(resolved)
    }
}

fn load_session_owner(directory: &Path) -> Result<Arc<str>> {
    let path = directory.join("owner");
    harden_existing_file(&path)?;
    let owner = match read_file_limited(&path, 256) {
        Ok(value) => String::from_utf8(value)
            .with_context(|| format!("decode owner metadata {}", path.display()))?,
        Err(error) if is_not_found(&error) => {
            // Sessions created before owner binding were all single-token
            // sessions. Keep them addressable by the legacy principal while
            // requiring an explicit migration before multi-principal access.
            return Ok(Arc::from("legacy"));
        }
        Err(error) => return Err(error),
    };
    let owner = owner.trim();
    if owner.is_empty() || owner.len() > 256 || owner.as_bytes().contains(&0) {
        bail!("invalid owner metadata in {}", path.display());
    }
    Ok(Arc::from(owner.to_owned()))
}

/// Bounded, daemon-local workspace indexes for tree metadata, repeated
/// searches, and small Git results. The durable source of truth remains the
/// filesystem: cache entries are used only when a native watcher is healthy,
/// their invalidation generation still matches, and they are younger than
/// `WORKSPACE_INDEX_MAX_AGE`. Any watcher error, overflow, or stale entry
/// forces fresh work instead of serving cached state. The short age window is
/// an additional recovery path for platforms whose native watcher coalesces
/// events.
#[derive(Debug, Clone, PartialEq, Eq, Hash)]
struct WorkspaceDigestKey {
    include_tree: bool,
    include_git_status: bool,
    include_diff: bool,
    recent_commits: u16,
    searches: Vec<String>,
    read_paths: Vec<String>,
}

impl WorkspaceDigestKey {
    fn new(
        include_tree: bool,
        include_git_status: bool,
        include_diff: bool,
        recent_commits: u16,
        searches: &[String],
        read_paths: &[String],
    ) -> Self {
        Self {
            include_tree,
            include_git_status,
            include_diff,
            recent_commits,
            searches: searches.to_vec(),
            read_paths: read_paths.to_vec(),
        }
    }

    fn estimated_bytes(&self) -> usize {
        std::mem::size_of::<Self>()
            .saturating_add(self.searches.iter().map(String::len).sum::<usize>())
            .saturating_add(self.read_paths.iter().map(String::len).sum::<usize>())
    }
}

struct WorkspaceDigestCacheEntry {
    digest: String,
    tree_version: Option<WorkspaceVersion>,
    observed_invalidation: u64,
    built_at: Instant,
}

struct WorkspaceIndex {
    root: PathBuf,
    /// Canonical Git helper selected at daemon startup. Keeping this outside
    /// the request path avoids repeated PATH traversal and makes a service
    /// manager's environment deterministic for the lifetime of the daemon.
    /// The executable identity is retained as well, so an operator or
    /// package-manager replacement cannot silently change the helper used by
    /// semantic workspace queries while the daemon is running.
    git_program: Option<WorkspaceGitProgram>,
    /// Apply the same operator-owned process boundary and per-command limits
    /// to semantic Git helpers that are used for EXEC/SPAWN and PTY creation.
    /// Keeping this policy in the index prevents WORKSPACE_STATE from
    /// becoming an accidental escape hatch in a fail-closed deployment.
    process_launcher: RwLock<ProcessLauncher>,
    process_limits: RwLock<ProcessLimits>,
    epoch: Uuid,
    caches: RwLock<HashMap<PathBuf, Arc<WorkspaceTreeCache>>>,
    search_cache_memory: Arc<Semaphore>,
    git_cache_memory: Arc<Semaphore>,
    invalidation_generation: AtomicU64,
    watcher_started: AtomicBool,
    watcher_healthy: AtomicBool,
    cache_hits: AtomicU64,
    cache_misses: AtomicU64,
    invalidations: AtomicU64,
    digest_cache_hits: AtomicU64,
    search_cache_hits: AtomicU64,
    search_cache_misses: AtomicU64,
    git_cache_hits: AtomicU64,
    git_cache_misses: AtomicU64,
}

#[derive(Debug, Clone)]
struct WorkspaceGitProgram {
    path: PathBuf,
    identity: ProcessLauncherIdentity,
}

/// A bounded observation of one workspace file. The watcher is not a source
/// of file contents, so the metadata fields identify the common case and the
/// optional digest closes the same-size/same-mtime duplicate corner for small
/// source files. `Missing` is retained so a burst of delete notifications
/// produces one durable event rather than one event per backend callback.
#[derive(Debug, Clone, PartialEq, Eq)]
enum WorkspaceFileObservation {
    File {
        bytes: u64,
        modified: Option<SystemTime>,
        digest: Option<String>,
    },
    Missing,
}

impl WorkspaceFileObservation {
    fn metadata_eq(&self, other: &Self) -> bool {
        match (self, other) {
            (
                Self::File {
                    bytes: left_bytes,
                    modified: left_modified,
                    ..
                },
                Self::File {
                    bytes: right_bytes,
                    modified: right_modified,
                    ..
                },
            ) => left_bytes == right_bytes && left_modified == right_modified,
            (Self::Missing, Self::Missing) => true,
            _ => false,
        }
    }
}

/// Capture a regular workspace file without following a final symlink. A
/// missing path is a meaningful deletion observation; directories, symlinks,
/// and special files are ignored because they do not map cleanly to the
/// file-version contract.
fn observe_workspace_file_metadata_sync(path: &Path) -> Result<Option<WorkspaceFileObservation>> {
    let metadata = match std::fs::symlink_metadata(path) {
        Ok(metadata) => metadata,
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => {
            return Ok(Some(WorkspaceFileObservation::Missing));
        }
        Err(error) => return Err(error.into()),
    };
    if metadata.file_type().is_symlink() || !metadata.is_file() {
        return Ok(None);
    }
    Ok(Some(WorkspaceFileObservation::File {
        bytes: metadata.len(),
        modified: metadata.modified().ok(),
        digest: None,
    }))
}

fn observe_workspace_file_sync(path: &Path) -> Result<Option<WorkspaceFileObservation>> {
    let Some(mut observation) = observe_workspace_file_metadata_sync(path)? else {
        return Ok(None);
    };
    if let WorkspaceFileObservation::File { bytes, digest, .. } = &mut observation
        && *bytes <= WORKSPACE_FILE_EVENT_HASH_MAX_BYTES
    {
        *digest = Some(digest_file_sync(path)?.1);
    }
    Ok(Some(observation))
}

struct WorkspaceTreeCache {
    snapshot: RwLock<Option<WorkspaceIndexSnapshot>>,
    rebuild_lock: tokio::sync::Mutex<()>,
    next_generation: AtomicU64,
    digest: RwLock<HashMap<WorkspaceDigestKey, Arc<WorkspaceDigestCacheEntry>>>,
    search: RwLock<HashMap<Vec<String>, Arc<WorkspaceSearchCacheEntry>>>,
    search_rebuild_lock: tokio::sync::Mutex<()>,
    git: RwLock<HashMap<Vec<String>, Arc<WorkspaceGitCacheEntry>>>,
}

struct WorkspaceIndexSnapshot {
    entries: Arc<Vec<ScannedFile>>,
    version: WorkspaceVersion,
    observed_invalidation: u64,
    built_at: Instant,
}

struct WorkspaceSearchCacheEntry {
    hits: Arc<Vec<WorkspaceSearchHit>>,
    version: WorkspaceVersion,
    observed_invalidation: u64,
    built_at: Instant,
    // Retain the global cache budget while this entry is reachable. The
    // permit is deliberately stored in the entry so eviction and daemon
    // shutdown release the exact amount that was charged.
    _memory_permit: OwnedSemaphorePermit,
}

struct WorkspaceGitCacheEntry {
    value: Option<String>,
    observed_invalidation: u64,
    built_at: Instant,
    _memory_permit: OwnedSemaphorePermit,
}

impl WorkspaceIndex {
    fn new(root: PathBuf) -> Arc<Self> {
        let root = root.canonicalize().unwrap_or(root);
        let git_program = resolve_git_program();
        Arc::new(Self {
            root,
            git_program,
            process_launcher: RwLock::new(ProcessLauncher::default()),
            process_limits: RwLock::new(ProcessLimits::default()),
            epoch: Uuid::new_v4(),
            caches: RwLock::new(HashMap::new()),
            search_cache_memory: Arc::new(Semaphore::new(WORKSPACE_SEARCH_CACHE_MEMORY_UNITS)),
            git_cache_memory: Arc::new(Semaphore::new(WORKSPACE_GIT_CACHE_MEMORY_UNITS)),
            invalidation_generation: AtomicU64::new(0),
            watcher_started: AtomicBool::new(false),
            watcher_healthy: AtomicBool::new(false),
            cache_hits: AtomicU64::new(0),
            cache_misses: AtomicU64::new(0),
            invalidations: AtomicU64::new(0),
            digest_cache_hits: AtomicU64::new(0),
            search_cache_hits: AtomicU64::new(0),
            search_cache_misses: AtomicU64::new(0),
            git_cache_hits: AtomicU64::new(0),
            git_cache_misses: AtomicU64::new(0),
        })
    }

    /// Start the watcher and optionally hand regular-file paths to the
    /// session-store event worker. The sender is deliberately separate from
    /// notify's result queue: a slow WAL fsync must never make the backend
    /// callback block or make cache invalidation unavailable.
    fn start_watcher_with_events(
        self: &Arc<Self>,
        file_change_tx: Option<mpsc::Sender<Vec<PathBuf>>>,
    ) -> Result<()> {
        if self
            .watcher_started
            .compare_exchange(false, true, Ordering::AcqRel, Ordering::Acquire)
            .is_err()
        {
            return Ok(());
        }
        let (event_tx, event_rx) = std::sync::mpsc::sync_channel(WORKSPACE_WATCHER_QUEUE_CAPACITY);
        let callback_index = Arc::clone(self);
        let mut watcher = match notify::recommended_watcher(move |result| {
            match event_tx.try_send(result) {
                Ok(()) => {}
                Err(std::sync::mpsc::TrySendError::Full(_)) => {
                    // Dropping the notification is safe: the cache is only a
                    // performance hint. Once the bounded hand-off is full,
                    // force fresh scans rather than allowing event payloads
                    // to accumulate without limit.
                    if callback_index.watcher_healthy.swap(false, Ordering::AcqRel) {
                        callback_index.invalidate();
                        warn!("workspace watcher queue overflowed; disabling index cache");
                    }
                }
                Err(std::sync::mpsc::TrySendError::Disconnected(_)) => {
                    callback_index
                        .watcher_healthy
                        .store(false, Ordering::Release);
                    callback_index.invalidate();
                }
            }
        }) {
            Ok(watcher) => watcher,
            Err(error) => {
                self.watcher_started.store(false, Ordering::Release);
                return Err(error.into());
            }
        };
        // Mark the cache usable before registration so a callback that races
        // the backend setup can still transition it to unhealthy on overflow.
        self.watcher_healthy.store(true, Ordering::Release);
        if let Err(error) = watcher.watch(&self.root, RecursiveMode::Recursive) {
            self.watcher_healthy.store(false, Ordering::Release);
            self.watcher_started.store(false, Ordering::Release);
            return Err(error.into());
        }
        let index = Arc::clone(self);
        std::thread::Builder::new()
            .name("asp-workspace-watcher".to_owned())
            .spawn(move || {
                // Keep the watcher alive for the lifetime of its event
                // receiver. Dropping it would silently disable invalidation.
                let _watcher = watcher;
                while let Ok(result) = event_rx.recv() {
                    match result {
                        Ok(event) => {
                            if event
                                .paths
                                .iter()
                                .any(|path| index.event_affects_workspace(path))
                            {
                                index.invalidate();
                                if let Some(file_change_tx) = file_change_tx.as_ref() {
                                    let path_limit_reached =
                                        event.paths.len() > WORKSPACE_FILE_EVENT_OBSERVATION_LIMIT;
                                    let paths = event
                                        .paths
                                        .iter()
                                        .filter_map(|path| index.event_file_path(path))
                                        .take(WORKSPACE_FILE_EVENT_OBSERVATION_LIMIT)
                                        .collect::<Vec<_>>();
                                    if path_limit_reached {
                                        WORKSPACE_FILE_EVENT_DROPS_TOTAL
                                            .fetch_add(1, Ordering::Relaxed);
                                        if index.watcher_healthy.swap(false, Ordering::AcqRel) {
                                            index.invalidate();
                                            warn!(
                                                limit = WORKSPACE_FILE_EVENT_OBSERVATION_LIMIT,
                                                "workspace watcher callback exceeded file-event path limit; disabling index cache and requiring semantic resync"
                                            );
                                        }
                                    }
                                    if !paths.is_empty()
                                        && let Err(error) = file_change_tx.try_send(paths)
                                    {
                                        WORKSPACE_FILE_EVENT_DROPS_TOTAL
                                            .fetch_add(1, Ordering::Relaxed);
                                        if index.watcher_healthy.swap(false, Ordering::AcqRel) {
                                            index.invalidate();
                                            warn!(
                                                "workspace file-event queue overflowed; disabling index cache and requiring semantic resync"
                                            );
                                        } else if matches!(error, mpsc::error::TrySendError::Full(_)) {
                                            warn!(
                                                "workspace file-event queue remains full; durable FILE_CHANGED notifications may be delayed"
                                            );
                                        }
                                    }
                                }
                            }
                        }
                        Err(error) => {
                            // notify reports queue overflow and backend
                            // failures here. Disable the cache permanently
                            // for this daemon; a fresh scan is safer than
                            // guessing which paths were missed.
                            index.watcher_healthy.store(false, Ordering::Release);
                            index.invalidate();
                            warn!(%error, "workspace watcher became unreliable; disabling index cache");
                        }
                    }
                }
                index.watcher_healthy.store(false, Ordering::Release);
            })
            .map_err(|error| {
                self.watcher_healthy.store(false, Ordering::Release);
                self.watcher_started.store(false, Ordering::Release);
                anyhow!("spawn ASP workspace watcher: {error}")
            })?;
        Ok(())
    }

    /// Return a normalized path eligible for a durable FILE_CHANGED event.
    /// ASP's private state and transaction scratch files are intentionally
    /// excluded; those changes are implementation details and must not wake
    /// every agent subscriber.
    fn event_file_path(&self, path: &Path) -> Option<PathBuf> {
        let absolute = if path.is_absolute() {
            path.to_path_buf()
        } else {
            self.root.join(path)
        };
        let relative = absolute.strip_prefix(&self.root).ok()?;
        if relative.as_os_str().is_empty()
            || relative.components().any(|component| {
                matches!(
                    component,
                    Component::ParentDir | Component::RootDir | Component::Prefix(_)
                ) || matches!(component, Component::Normal(value) if value == ".asp")
            })
        {
            return None;
        }
        let file_name = relative.file_name()?.to_string_lossy();
        if file_name.starts_with("asp-tmp-") || file_name.starts_with("asp-backup-") {
            return None;
        }
        Some(self.root.join(relative))
    }

    fn event_affects_workspace(&self, path: &Path) -> bool {
        let Ok(relative) = path.strip_prefix(&self.root) else {
            return true;
        };
        !relative
            .components()
            .any(|component| matches!(component, Component::Normal(value) if value == ".asp"))
    }

    fn invalidate(&self) {
        self.invalidations.fetch_add(1, Ordering::Relaxed);
        self.invalidation_generation.fetch_add(1, Ordering::AcqRel);
    }

    fn stats(&self) -> (u64, u64, u64, bool, u64, u64, u64, u64) {
        (
            self.cache_hits.load(Ordering::Relaxed),
            self.cache_misses.load(Ordering::Relaxed),
            self.invalidations.load(Ordering::Relaxed),
            self.watcher_healthy.load(Ordering::Acquire),
            self.search_cache_hits.load(Ordering::Relaxed),
            self.search_cache_misses.load(Ordering::Relaxed),
            self.git_cache_hits.load(Ordering::Relaxed),
            self.git_cache_misses.load(Ordering::Relaxed),
        )
    }

    fn cache_memory_usage(&self) -> (u64, u64) {
        let search_used = WORKSPACE_SEARCH_CACHE_MEMORY_UNITS
            .saturating_sub(self.search_cache_memory.available_permits())
            .saturating_mul(FRAME_MEMORY_UNIT_BYTES) as u64;
        let git_used = WORKSPACE_GIT_CACHE_MEMORY_UNITS
            .saturating_sub(self.git_cache_memory.available_permits())
            .saturating_mul(FRAME_MEMORY_UNIT_BYTES) as u64;
        (search_used, git_used)
    }

    fn digest_cache_hits(&self) -> u64 {
        self.digest_cache_hits.load(Ordering::Relaxed)
    }

    fn git_helper_configured(&self) -> bool {
        self.git_program.is_some()
    }

    fn set_process_launcher(&self, launcher: ProcessLauncher) {
        *self
            .process_launcher
            .write()
            .expect("workspace process launcher poisoned") = launcher;
    }

    fn set_process_limits(&self, limits: ProcessLimits) {
        *self
            .process_limits
            .write()
            .expect("workspace process limits poisoned") = limits;
    }

    fn process_launcher(&self) -> ProcessLauncher {
        self.process_launcher
            .read()
            .expect("workspace process launcher poisoned")
            .clone()
    }

    fn process_limits(&self) -> ProcessLimits {
        *self
            .process_limits
            .read()
            .expect("workspace process limits poisoned")
    }

    /// Git is optional for non-repository workspaces. When a helper was
    /// selected, however, a package/path replacement must be visible to
    /// readiness before a semantic query tries to execute it. This mirrors
    /// the process-launcher identity check and gives supervisors a clear
    /// restart boundary after a Git upgrade.
    fn git_helper_healthy(&self) -> bool {
        let Some(program) = self.git_program.as_ref() else {
            return true;
        };
        process_launcher_identity(&program.path).is_ok_and(|identity| identity == program.identity)
    }

    fn cache_for(&self, root: &Path) -> Option<Arc<WorkspaceTreeCache>> {
        if let Some(cache) = self
            .caches
            .read()
            .expect("workspace index cache map poisoned")
            .get(root)
            .cloned()
        {
            return Some(cache);
        }
        let mut caches = self
            .caches
            .write()
            .expect("workspace index cache map poisoned");
        if let Some(cache) = caches.get(root).cloned() {
            return Some(cache);
        }
        if caches.len() >= MAX_WORKSPACE_INDEXES {
            return None;
        }
        let cache = Arc::new(WorkspaceTreeCache {
            snapshot: RwLock::new(None),
            rebuild_lock: tokio::sync::Mutex::new(()),
            next_generation: AtomicU64::new(0),
            digest: RwLock::new(HashMap::new()),
            search: RwLock::new(HashMap::new()),
            search_rebuild_lock: tokio::sync::Mutex::new(()),
            git: RwLock::new(HashMap::new()),
        });
        caches.insert(root.to_path_buf(), Arc::clone(&cache));
        Some(cache)
    }

    /// Return a matching complete-result digest without touching the
    /// filesystem. This fast path is valid only while the native watcher is
    /// healthy, the same invalidation generation is current, and the short
    /// freshness window has not elapsed. A miss always falls back to the
    /// normal bounded scan/read path, so the cache is never authoritative.
    fn lookup_digest(
        &self,
        root: &Path,
        key: &WorkspaceDigestKey,
        known_digest: &str,
    ) -> Option<Option<WorkspaceVersion>> {
        if !self.watcher_healthy.load(Ordering::Acquire) {
            return None;
        }
        let cache = self.cache_for(root)?;
        let current_invalidation = self.invalidation_generation.load(Ordering::Acquire);
        let hit = cache
            .digest
            .read()
            .expect("workspace digest cache poisoned")
            .get(key)
            .filter(|entry| {
                entry.digest == known_digest
                    && entry.observed_invalidation == current_invalidation
                    && entry.built_at.elapsed() <= WORKSPACE_INDEX_MAX_AGE
            })
            .map(|entry| entry.tree_version.clone());
        if hit.is_some() {
            self.digest_cache_hits.fetch_add(1, Ordering::Relaxed);
        }
        hit
    }

    /// Publish a compact digest validator after a stable semantic query. The
    /// payload is deliberately not retained here: the client owns the full
    /// result, while the daemon keeps only enough metadata to skip duplicate
    /// work. Entries are bounded by count and per-key size.
    fn insert_digest(
        &self,
        root: &Path,
        key: WorkspaceDigestKey,
        digest: String,
        tree_version: Option<WorkspaceVersion>,
        observed_invalidation: u64,
    ) {
        if !self.watcher_healthy.load(Ordering::Acquire)
            || key.estimated_bytes() > WORKSPACE_DIGEST_CACHE_ENTRY_MAX_BYTES
            || observed_invalidation != self.invalidation_generation.load(Ordering::Acquire)
        {
            return;
        }
        let Some(cache) = self.cache_for(root) else {
            return;
        };
        let mut digests = cache
            .digest
            .write()
            .expect("workspace digest cache poisoned");
        digests.remove(&key);
        while digests.len() >= WORKSPACE_DIGEST_CACHE_MAX_ENTRIES {
            let oldest = digests
                .iter()
                .min_by_key(|(_, entry)| entry.built_at)
                .map(|(candidate, _)| candidate.clone());
            let Some(oldest) = oldest else { break };
            digests.remove(&oldest);
        }
        digests.insert(
            key,
            Arc::new(WorkspaceDigestCacheEntry {
                digest,
                tree_version,
                observed_invalidation,
                built_at: Instant::now(),
            }),
        );
    }

    async fn entries(
        &self,
        root: &Path,
    ) -> Result<(Arc<Vec<ScannedFile>>, Option<WorkspaceVersion>, bool)> {
        // A daemon without a functioning native watcher never serves cached
        // metadata. This branch is also used by unit tests that intentionally
        // exercise the uncached fallback.
        if !self.watcher_healthy.load(Ordering::Acquire) {
            self.cache_misses.fetch_add(1, Ordering::Relaxed);
            return Ok((fresh_workspace_scan(root).await?, None, false));
        }
        let Some(cache) = self.cache_for(root) else {
            self.cache_misses.fetch_add(1, Ordering::Relaxed);
            return Ok((fresh_workspace_scan(root).await?, None, false));
        };
        let current_invalidation = self.invalidation_generation.load(Ordering::Acquire);
        if let Some(snapshot) = cache
            .snapshot
            .read()
            .expect("workspace index snapshot poisoned")
            .as_ref()
            .filter(|snapshot| {
                snapshot.observed_invalidation == current_invalidation
                    && snapshot.built_at.elapsed() <= WORKSPACE_INDEX_MAX_AGE
            })
        {
            self.cache_hits.fetch_add(1, Ordering::Relaxed);
            return Ok((
                Arc::clone(&snapshot.entries),
                Some(snapshot.version.clone()),
                true,
            ));
        }

        self.cache_misses.fetch_add(1, Ordering::Relaxed);
        let _rebuild = cache.rebuild_lock.lock().await;
        let current_invalidation = self.invalidation_generation.load(Ordering::Acquire);
        if let Some(snapshot) = cache
            .snapshot
            .read()
            .expect("workspace index snapshot poisoned")
            .as_ref()
            .filter(|snapshot| {
                snapshot.observed_invalidation == current_invalidation
                    && snapshot.built_at.elapsed() <= WORKSPACE_INDEX_MAX_AGE
            })
        {
            self.cache_hits.fetch_add(1, Ordering::Relaxed);
            return Ok((
                Arc::clone(&snapshot.entries),
                Some(snapshot.version.clone()),
                true,
            ));
        }

        // Retry once if a filesystem event races the scan. If the workspace
        // is continuously changing, return the bounded scan result but do not
        // publish a cache entry or a validator token.
        let mut scanned = None;
        let mut stable_generation = None;
        for _ in 0..2 {
            let start_generation = self.invalidation_generation.load(Ordering::Acquire);
            let scan_root = root.to_path_buf();
            let entries = tokio::task::spawn_blocking(move || scan_workspace(&scan_root))
                .await
                .context("workspace index scan task failed")??;
            let end_generation = self.invalidation_generation.load(Ordering::Acquire);
            scanned = Some(Arc::new(entries));
            if start_generation == end_generation {
                stable_generation = Some(end_generation);
                break;
            }
        }
        let entries = scanned.expect("workspace index scan always produces a result");
        let Some(observed_invalidation) = stable_generation else {
            return Ok((entries, None, false));
        };
        if !self.watcher_healthy.load(Ordering::Acquire)
            || observed_invalidation != self.invalidation_generation.load(Ordering::Acquire)
        {
            return Ok((entries, None, false));
        }
        let generation = cache.next_generation.fetch_add(1, Ordering::AcqRel) + 1;
        let version = WorkspaceVersion {
            epoch: self.epoch,
            generation,
        };
        *cache
            .snapshot
            .write()
            .expect("workspace index snapshot poisoned") = Some(WorkspaceIndexSnapshot {
            entries: Arc::clone(&entries),
            version: version.clone(),
            observed_invalidation,
            built_at: Instant::now(),
        });
        Ok((entries, Some(version), false))
    }

    /// Return search hits from the same bounded index generation as the tree
    /// scan. Search is intentionally cached separately: the tree metadata is
    /// useful for every inspection, while file-content scans are only useful
    /// when an agent repeats the same query. A watcher invalidation, a stale
    /// age window, or a race during the search always falls back to the fresh
    /// result and skips publication.
    async fn search(
        &self,
        root: &Path,
        entries: Arc<Vec<ScannedFile>>,
        queries: Vec<String>,
        version: Option<&WorkspaceVersion>,
    ) -> Result<(Vec<WorkspaceSearchHit>, bool)> {
        if queries.is_empty() {
            return Ok((Vec::new(), false));
        }
        let Some(version) = version else {
            self.search_cache_misses.fetch_add(1, Ordering::Relaxed);
            let hits = tokio::task::spawn_blocking(move || search_workspace(&entries, &queries))
                .await
                .context("workspace search task failed")??;
            return Ok((hits, false));
        };
        if !self.watcher_healthy.load(Ordering::Acquire) {
            self.search_cache_misses.fetch_add(1, Ordering::Relaxed);
            let hits = tokio::task::spawn_blocking(move || search_workspace(&entries, &queries))
                .await
                .context("workspace search task failed")??;
            return Ok((hits, false));
        }
        let Some(cache) = self.cache_for(root) else {
            self.search_cache_misses.fetch_add(1, Ordering::Relaxed);
            let hits = tokio::task::spawn_blocking(move || search_workspace(&entries, &queries))
                .await
                .context("workspace search task failed")??;
            return Ok((hits, false));
        };
        let key = queries.clone();
        let current_invalidation = self.invalidation_generation.load(Ordering::Acquire);
        let cached = cache
            .search
            .read()
            .expect("workspace search cache poisoned")
            .get(&key)
            .filter(|entry| {
                entry.observed_invalidation == current_invalidation
                    && entry.version == *version
                    && entry.built_at.elapsed() <= WORKSPACE_INDEX_MAX_AGE
            })
            .map(|entry| Arc::clone(&entry.hits));
        if let Some(hits) = cached {
            self.search_cache_hits.fetch_add(1, Ordering::Relaxed);
            return Ok((hits.as_ref().clone(), true));
        }

        self.search_cache_misses.fetch_add(1, Ordering::Relaxed);
        let _rebuild = cache.search_rebuild_lock.lock().await;
        let current_invalidation = self.invalidation_generation.load(Ordering::Acquire);
        let cached = cache
            .search
            .read()
            .expect("workspace search cache poisoned")
            .get(&key)
            .filter(|entry| {
                entry.observed_invalidation == current_invalidation
                    && entry.version == *version
                    && entry.built_at.elapsed() <= WORKSPACE_INDEX_MAX_AGE
            })
            .map(|entry| Arc::clone(&entry.hits));
        if let Some(hits) = cached {
            self.search_cache_hits.fetch_add(1, Ordering::Relaxed);
            return Ok((hits.as_ref().clone(), true));
        }

        let start_generation = self.invalidation_generation.load(Ordering::Acquire);
        let search_entries = Arc::clone(&entries);
        let search_queries = queries.clone();
        let hits =
            tokio::task::spawn_blocking(move || search_workspace(&search_entries, &search_queries))
                .await
                .context("workspace search task failed")??;
        let end_generation = self.invalidation_generation.load(Ordering::Acquire);
        if start_generation != end_generation
            || !self.watcher_healthy.load(Ordering::Acquire)
            || end_generation != current_invalidation
        {
            return Ok((hits, false));
        }

        let estimated_bytes = workspace_search_cache_bytes(&key, &hits);
        if estimated_bytes > WORKSPACE_SEARCH_CACHE_ENTRY_MAX_BYTES {
            return Ok((hits, false));
        }
        let units = frame_memory_units(estimated_bytes)?;
        if usize::try_from(units)
            .ok()
            .is_none_or(|units| units > WORKSPACE_SEARCH_CACHE_MEMORY_UNITS)
        {
            return Ok((hits, false));
        }

        let mut search_cache = cache
            .search
            .write()
            .expect("workspace search cache poisoned");
        // Replace stale data first so its permit can be reclaimed. Evict the
        // oldest entries before acquiring the new permit, keeping the map
        // bounded even when many distinct agent queries are issued.
        search_cache.remove(&key);
        while search_cache.len() >= WORKSPACE_SEARCH_CACHE_MAX_ENTRIES {
            let oldest = search_cache
                .iter()
                .min_by_key(|(_, entry)| entry.built_at)
                .map(|(key, _)| key.clone());
            let Some(oldest) = oldest else { break };
            search_cache.remove(&oldest);
        }
        let Ok(memory_permit) = Arc::clone(&self.search_cache_memory).try_acquire_many_owned(units)
        else {
            return Ok((hits, false));
        };
        search_cache.insert(
            key,
            Arc::new(WorkspaceSearchCacheEntry {
                hits: Arc::new(hits.clone()),
                version: version.clone(),
                observed_invalidation: end_generation,
                built_at: Instant::now(),
                _memory_permit: memory_permit,
            }),
        );
        Ok((hits, false))
    }

    /// Cache bounded Git metadata by the fixed argument vector used by
    /// `WORKSPACE_STATE`. Git output can be much larger than a tree/search
    /// response (especially an uncommitted diff), so entries above the small
    /// cache threshold are returned normally but never retained. The
    /// filesystem watcher invalidates status/diff/log together; if it is not
    /// healthy, every call goes directly to Git.
    async fn git(&self, root: &Path, args: Vec<String>) -> Result<Option<String>> {
        let process_launcher = self.process_launcher();
        let process_limits = self.process_limits();
        // Validate both identities before consulting the cache. A cached Git
        // result must not hide a drifted worker boundary or helper binary from
        // a caller that is not actively polling /ready.
        run_blocking_on_runtime(|| validate_process_launcher_unchanged(&process_launcher))
            .context("validate ASP process launcher for Git helper")?;
        if let Some(program) = self.git_program.as_ref() {
            let current_identity =
                run_blocking_on_runtime(|| process_launcher_identity(&program.path))
                    .context("validate ASP Git helper identity")?;
            if current_identity != program.identity {
                bail!(
                    "Git helper {} changed after startup; restore the reviewed executable or restart aspd",
                    program.path.display()
                );
            }
        }
        if !self.watcher_healthy.load(Ordering::Acquire) {
            self.git_cache_misses.fetch_add(1, Ordering::Relaxed);
            let arg_refs = args.iter().map(String::as_str).collect::<Vec<_>>();
            return run_git_with_policy(
                self.git_program.as_ref(),
                root,
                &arg_refs,
                &process_launcher,
                process_limits,
            )
            .await;
        }
        let Some(cache) = self.cache_for(root) else {
            self.git_cache_misses.fetch_add(1, Ordering::Relaxed);
            let arg_refs = args.iter().map(String::as_str).collect::<Vec<_>>();
            return run_git_with_policy(
                self.git_program.as_ref(),
                root,
                &arg_refs,
                &process_launcher,
                process_limits,
            )
            .await;
        };
        let current_invalidation = self.invalidation_generation.load(Ordering::Acquire);
        let cached = cache
            .git
            .read()
            .expect("workspace Git cache poisoned")
            .get(&args)
            .filter(|entry| {
                entry.observed_invalidation == current_invalidation
                    && entry.built_at.elapsed() <= WORKSPACE_INDEX_MAX_AGE
            })
            .map(|entry| entry.value.clone());
        if let Some(value) = cached {
            self.git_cache_hits.fetch_add(1, Ordering::Relaxed);
            return Ok(value);
        }

        self.git_cache_misses.fetch_add(1, Ordering::Relaxed);
        let arg_refs = args.iter().map(String::as_str).collect::<Vec<_>>();
        let value = run_git_with_policy(
            self.git_program.as_ref(),
            root,
            &arg_refs,
            &process_launcher,
            process_limits,
        )
        .await?;
        let end_generation = self.invalidation_generation.load(Ordering::Acquire);
        if end_generation != current_invalidation || !self.watcher_healthy.load(Ordering::Acquire) {
            return Ok(value);
        }
        let estimated_bytes = workspace_git_cache_bytes(&args, value.as_deref());
        if estimated_bytes > WORKSPACE_GIT_CACHE_ENTRY_MAX_BYTES {
            return Ok(value);
        }
        let units = frame_memory_units(estimated_bytes)?;
        if usize::try_from(units)
            .ok()
            .is_none_or(|units| units > WORKSPACE_GIT_CACHE_MEMORY_UNITS)
        {
            return Ok(value);
        }

        let mut git_cache = cache.git.write().expect("workspace Git cache poisoned");
        git_cache.remove(&args);
        while git_cache.len() >= WORKSPACE_GIT_CACHE_MAX_ENTRIES {
            let oldest = git_cache
                .iter()
                .min_by_key(|(_, entry)| entry.built_at)
                .map(|(key, _)| key.clone());
            let Some(oldest) = oldest else { break };
            git_cache.remove(&oldest);
        }
        let Ok(memory_permit) = Arc::clone(&self.git_cache_memory).try_acquire_many_owned(units)
        else {
            return Ok(value);
        };
        git_cache.insert(
            args,
            Arc::new(WorkspaceGitCacheEntry {
                value: value.clone(),
                observed_invalidation: end_generation,
                built_at: Instant::now(),
                _memory_permit: memory_permit,
            }),
        );
        Ok(value)
    }
}

fn workspace_search_cache_bytes(queries: &[String], hits: &[WorkspaceSearchHit]) -> usize {
    let query_bytes = queries.iter().map(|query| query.len()).sum::<usize>();
    let hit_bytes = hits
        .iter()
        .map(|hit| {
            hit.query
                .len()
                .saturating_add(hit.path.len())
                .saturating_add(hit.text.len())
                .saturating_add(std::mem::size_of::<u64>())
        })
        .sum::<usize>();
    query_bytes.saturating_add(hit_bytes).max(1)
}

fn workspace_git_cache_bytes(args: &[String], value: Option<&str>) -> usize {
    args.iter()
        .map(|arg| arg.len())
        .sum::<usize>()
        .saturating_add(value.map_or(0, str::len))
        .max(1)
}

async fn fresh_workspace_scan(root: &Path) -> Result<Arc<Vec<ScannedFile>>> {
    let root = root.to_path_buf();
    Ok(Arc::new(
        tokio::task::spawn_blocking(move || scan_workspace(&root))
            .await
            .context("workspace scan task failed")??,
    ))
}

/// Add one native-watcher callback to a coalescing batch without allowing a
/// burst of unique paths to grow memory beyond the observation budget. A
/// duplicate path is still retained as a no-op, so repeated backend callbacks
/// do not count as dropped work.
fn extend_workspace_file_event_paths(paths: &mut HashSet<PathBuf>, incoming: Vec<PathBuf>) -> bool {
    let mut truncated = false;
    for path in incoming {
        if paths.contains(&path) {
            continue;
        }
        if paths.len() >= WORKSPACE_FILE_EVENT_OBSERVATION_LIMIT {
            truncated = true;
            break;
        }
        paths.insert(path);
    }
    truncated
}

