            // persisted ASP wrapper and, on Linux, the kernel start-time
            // identity to match before sending a group signal. Refusing an
            // ambiguous signal is safer than risking an unrelated process.
            let identity_valid = match ProcessPaths::new(&session, process_id) {
                Ok(paths) => {
                    process_identity_matches_async(Some(pid), &paths.wrapper, start_time).await
                }
                Err(_) => false,
            };
            let idempotency_reservation = match store.reserve_idempotency_record(&session) {
                Ok(reservation) => reservation,
                Err(error) => {
                    send_error(&mut send, "idempotency_capacity", error.to_string()).await?;
                    send.finish()?;
                    return Ok(());
                }
            };
