    #[tokio::test(flavor = "multi_thread", worker_threads = 1)]
    async fn launch_blocking_path_keeps_single_worker_responsive() {
        // With one Tokio worker, an unwrapped synchronous launch operation
        // would prevent the timer task from running until the operation
        // returns.  `run_blocking_on_runtime` must hand that worker back to
        // Tokio while the durable launch transaction performs filesystem or
        // fork/exec work.
        let timer_ran = Arc::new(AtomicBool::new(false));
        let timer_ran_clone = Arc::clone(&timer_ran);
        let timer = tokio::spawn(async move {
            tokio::time::sleep(Duration::from_millis(20)).await;
            timer_ran_clone.store(true, Ordering::Release);
        });
        let result = run_blocking_on_runtime(|| {
            std::thread::sleep(Duration::from_millis(100));
            42_u32
        });
        assert_eq!(result, 42);
        assert!(
            timer.is_finished(),
            "Tokio's replacement worker did not run while process launch was blocked"
        );
        timer.await.unwrap();
        assert!(timer_ran.load(Ordering::Acquire));
    }

    #[test]
    fn request_latency_histogram_is_bounded_and_cumulative() {
        let metrics = RequestLatencyMetrics::new();
        let exec = RequestLatencyMetrics::operation_index("exec");
        metrics.record(exec, Duration::from_micros(50));
        metrics.record(exec, Duration::from_micros(600));

        let rendered = metrics.render_prometheus();
        assert_eq!(
            rendered.lines().count(),
            2 + REQUEST_LATENCY_OPERATION_NAMES.len() * (REQUEST_LATENCY_BUCKET_COUNT + 2)
        );
        assert!(
            rendered.contains("asp_request_duration_us_bucket{operation=\"exec\",le=\"100\"} 1")
        );
        assert!(
            rendered.contains("asp_request_duration_us_bucket{operation=\"exec\",le=\"1000\"} 2")
        );
        assert!(
            rendered.contains("asp_request_duration_us_bucket{operation=\"exec\",le=\"+Inf\"} 2")
        );
        assert!(rendered.contains("asp_request_duration_us_count{operation=\"exec\"} 2"));
        assert!(rendered.contains("asp_request_duration_us_sum{operation=\"exec\"} 650"));
    }

    #[test]
    fn process_launch_histogram_tracks_success_and_failure() {
        let metrics = ProcessLaunchMetrics::new();
        metrics.record(Duration::from_micros(50), true);
        metrics.record(Duration::from_micros(600), false);

        let rendered = metrics.render_prometheus();
        assert!(rendered.contains("asp_process_launch_duration_us_bucket{le=\"100\"} 1"));
        assert!(rendered.contains("asp_process_launch_duration_us_bucket{le=\"1000\"} 2"));
        assert!(rendered.contains("asp_process_launch_duration_us_bucket{le=\"+Inf\"} 2"));
        assert!(rendered.contains("asp_process_launch_duration_us_count 2"));
        assert!(rendered.contains("asp_process_launch_duration_us_sum 650"));
        assert!(rendered.contains("asp_process_launch_failures_total 1"));
        assert_eq!(metrics.totals(), (2, 1, 650));
    }

