        let first = artifact_request_hash(&upper, 7, Some("a")).unwrap();
        assert_eq!(first, artifact_request_hash(&lower, 7, Some("a")).unwrap());
        assert_ne!(first, artifact_request_hash(&lower, 8, Some("a")).unwrap());
