    #[test]
    fn file_patch_ranges_request_hash_is_order_and_body_sensitive() {
        let ranges = vec![FilePatchRange {
            offset: 4,
            remove_len: 2,
            replacement: b"new".to_vec(),
        }];
        let same = file_patch_ranges_request_hash("src/lib.rs", &"a".repeat(64), &ranges).unwrap();
        assert_eq!(
            same,
            file_patch_ranges_request_hash("src/lib.rs", &"a".repeat(64), &ranges).unwrap()
        );
        let mut changed = ranges.clone();
        changed[0].replacement = b"old".to_vec();
        assert_ne!(
            same,
            file_patch_ranges_request_hash("src/lib.rs", &"a".repeat(64), &changed).unwrap()
        );
        assert_ne!(
            same,
            file_patch_ranges_request_hash("src/lib.rs", &"b".repeat(64), &ranges).unwrap()
        );
    }

