    #[tokio::test(flavor = "current_thread")]
    async fn cancelled_temporary_upload_cleanup_is_off_reactor() {
        let root = std::env::temp_dir().join(format!("asp-temp-guard-{}", Uuid::new_v4()));
        std::fs::create_dir_all(&root).unwrap();
        let path = root.join("upload.asp-tmp");
        std::fs::write(&path, b"staged").unwrap();
        {
            let _guard = TemporaryPathGuard::new(path.clone());
        }
        // The guard schedules its unlink on Tokio's blocking pool when it is
        // dropped from a request task. Keep the current-thread reactor
        // runnable while waiting for that best-effort cleanup to complete.
        tokio::time::timeout(Duration::from_secs(1), async {
            while path.exists() {
                tokio::task::yield_now().await;
            }
        })
        .await
        .expect("temporary upload cleanup should complete");
        std::fs::remove_dir_all(root).unwrap();
    }

