    #[test]
    fn frame_memory_budget_rounds_up_without_exceeding_wire_limit() {
        assert_eq!(frame_memory_units(0).unwrap(), 1);
        assert_eq!(frame_memory_units(FRAME_MEMORY_UNIT_BYTES).unwrap(), 1);
        assert_eq!(frame_memory_units(FRAME_MEMORY_UNIT_BYTES + 1).unwrap(), 2);
        assert_eq!(
            frame_memory_units(MAX_FRAME_BYTES).unwrap() as usize,
            MAX_FRAME_BYTES.div_ceil(FRAME_MEMORY_UNIT_BYTES)
        );
    }

    #[test]
    fn first_compressed_frame_charges_advertised_decoded_memory() {
        let mut compressed = Vec::from(*b"AF");
        compressed.push(1);
        compressed.extend_from_slice(&(MAX_FRAME_BYTES as u32).to_be_bytes());
        let wire_length = FRAME_HEADER_BYTES + 32;
        let expected =
            frame_memory_units(wire_length).unwrap() + frame_memory_units(MAX_FRAME_BYTES).unwrap();
        assert_eq!(
            first_frame_memory_units(FRAME_MODE_CURRENT, wire_length, &compressed).unwrap(),
            expected
        );

        let mut plain = Vec::from(*b"AF");
        plain.push(0);
        plain.extend_from_slice(&32_u32.to_be_bytes());
        assert_eq!(
            first_frame_memory_units(FRAME_MODE_CURRENT, wire_length, &plain).unwrap(),
            frame_memory_units(wire_length).unwrap()
        );
        assert_eq!(
            first_frame_memory_units(FRAME_MODE_LEGACY, 32, b"legacy").unwrap(),
            frame_memory_units(32).unwrap()
        );
    }

