    #[test]
    fn principal_request_byte_budget_is_scoped_and_enforced() {
        let root = std::env::temp_dir().join(format!("asp-byte-budget-{}", Uuid::new_v4()));
        std::fs::create_dir_all(&root).unwrap();
        let store = SessionStore::open_with_budget(root.clone(), None, 8).unwrap();
        let principal = AuthPrincipal::legacy("test-credential");

        assert!(store.admit_request_bytes(&principal, "file_put", 8).is_ok());
        assert!(
            store
                .admit_request_bytes(&principal, "file_put", 1)
                .is_err()
        );
        // Buckets are per operation, so an independent operation is admitted.
        assert!(store.admit_request_bytes(&principal, "exec", 1).is_ok());

        let health = store.health_snapshot();
        assert_eq!(health.request_bytes_total, 9);
        assert_eq!(health.principal_budget_rejections, 1);
        assert_eq!(health.principal_request_bytes_limit, 8);
        assert!(SessionStore::open_with_budget(root.clone(), None, 0).is_err());
        assert!(SessionStore::open_with_budget(root.clone(), None, (1_u64 << 40) + 1).is_err());
        std::fs::remove_dir_all(root).unwrap();
    }

