    #[tokio::test]
    async fn port_forward_payload_is_metered_before_write() {
        use tokio::io::{AsyncReadExt as _, AsyncWriteExt as _};

        let root = std::env::temp_dir().join(format!("asp-port-budget-{}", Uuid::new_v4()));
        std::fs::create_dir_all(&root).unwrap();
        let token: Arc<str> = Arc::from("port-forward-test-token-abcdefghijklmnopqrstuvwxyz");
        let store =
            SessionStore::open_with_budgets(root.clone(), Some(token.clone()), 64, 4).unwrap();
        let principal = AuthPrincipal::legacy(token);

        let (mut source, mut reader) = tokio::io::duplex(64);
        source.write_all(b"abcd").await.unwrap();
        source.shutdown().await.unwrap();
        let (mut writer, mut sink) = tokio::io::duplex(64);
        assert_eq!(
            copy_port_bytes(&mut reader, &mut writer, &store, &principal, false)
                .await
                .unwrap(),
            4
        );
        writer.shutdown().await.unwrap();
        let mut received = Vec::new();
        sink.read_to_end(&mut received).await.unwrap();
        assert_eq!(received, b"abcd");

        let (mut source, mut reader) = tokio::io::duplex(64);
        source.write_all(b"e").await.unwrap();
        source.shutdown().await.unwrap();
        let (mut writer, _sink) = tokio::io::duplex(64);
        assert!(
            copy_port_bytes(&mut reader, &mut writer, &store, &principal, false)
                .await
                .is_err()
        );
        std::fs::remove_dir_all(root).unwrap();
    }

    #[tokio::test]
    async fn idle_port_forward_closes_after_credential_revocation() {
        let root = std::env::temp_dir().join(format!("asp-port-revoke-{}", Uuid::new_v4()));
        std::fs::create_dir_all(&root).unwrap();
        let old_token = "port-forward-old-token-abcdefghijklmnopqrstuvwxyz";
        let new_token = "port-forward-new-token-abcdefghijklmnopqrstuvwxyz";
        let auth_path = root.join("auth-token");
        std::fs::write(&auth_path, format!("{old_token}\n")).unwrap();
        let store = SessionStore::open_with_budgets(
            root.clone(),
            Some(Arc::from(old_token)),
            1024 * 1024,
            1024 * 1024,
        )
        .unwrap();
        store.set_auth_token_file(auth_path.clone());
        let principal = store.authenticate(old_token).unwrap();
        let (_source, mut reader) = tokio::io::duplex(64);
        let (mut writer, _sink) = tokio::io::duplex(64);
        let task_store = store.clone();
        let task_principal = principal.clone();
        let task = tokio::spawn(async move {
            copy_port_bytes(
                &mut reader,
                &mut writer,
                &task_store,
                &task_principal,
                false,
            )
            .await
        });
        tokio::time::sleep(Duration::from_millis(100)).await;
        std::fs::write(&auth_path, format!("{new_token}\n")).unwrap();
        let result = tokio::time::timeout(Duration::from_secs(3), task)
            .await
            .expect("revoked idle port forward did not close in time")
            .expect("port-forward task panicked");
        assert!(result.is_err());
        drop(store);
        std::fs::remove_dir_all(root).unwrap();
    }

    #[test]
    fn process_summary_accumulator_keeps_bounded_tails_and_offsets() {
        let process_id = Uuid::new_v4();
        let mut summary = ProcessSummaryAccumulator::new(4);
        summary.push(OutputStream::Stdout, 0, b"hello");
        summary.push(OutputStream::Stdout, 5, b" world");
        summary.push(OutputStream::Stderr, 0, b"err");
        let Response::ProcessSummary {
            process_id: actual_id,
            event_id,
            stdout_bytes,
            stderr_bytes,
            stdout_tail,
            stderr_tail,
            stdout_truncated,
            stderr_truncated,
        } = summary.into_response(process_id, 19)
        else {
            panic!("summary accumulator returned the wrong response");
        };
        assert_eq!(actual_id, process_id);
        assert_eq!(event_id, 19);
        assert_eq!(stdout_bytes, 11);
        assert_eq!(stderr_bytes, 3);
        assert_eq!(stdout_tail, b"orld");
        assert_eq!(stderr_tail, b"err");
        assert!(stdout_truncated);
        assert!(!stderr_truncated);
    }

