    #[test]
    fn port_target_policy_is_bounded_and_exact() {
        let root = std::env::temp_dir().join(format!("asp-port-policy-{}", Uuid::new_v4()));
        std::fs::create_dir_all(&root).unwrap();
        let store = SessionStore::open_with_budgets(root.clone(), None, 1024, 1024).unwrap();

        // No policy preserves the development behavior, while an explicit
        // empty policy is a deny-all configuration rather than an accidental
        // wildcard.
        assert_eq!(store.port_target_policy_entries(), 0);
        assert!(store.port_target_allowed("127.0.0.1:3000".parse().unwrap()));
        store.set_port_targets(Some(HashSet::new()));
        assert!(!store.port_target_allowed("127.0.0.1:3000".parse().unwrap()));
        assert_eq!(store.port_target_rejections(), 1);

        let targets = parse_port_target_policy(
            &[
                "localhost:3000".to_owned(),
                "[::1]:4000".to_owned(),
                "127.0.0.1:3000".to_owned(),
            ],
            false,
        )
        .unwrap()
        .unwrap();
        assert_eq!(targets.len(), 2, "localhost and IPv4 loopback normalize");
        store.set_port_targets(Some(targets));
        assert!(store.port_target_allowed("127.0.0.1:3000".parse().unwrap()));
        assert!(store.port_target_allowed("[::1]:4000".parse().unwrap()));
        assert!(!store.port_target_allowed("127.0.0.1:3001".parse().unwrap()));

        assert!(parse_port_target_policy(&["192.0.2.1:3000".to_owned()], false).is_err());
        assert!(parse_port_target_policy(&["localhost:0".to_owned()], false).is_err());
        let too_many = (0..=MAX_PORT_TARGETS)
            .map(|port| format!("127.0.0.1:{}", port.saturating_add(1)))
            .collect::<Vec<_>>();
        assert!(parse_port_target_policy(&too_many, false).is_err());
        assert!(
            parse_port_target_policy(&[], true)
                .unwrap()
                .unwrap()
                .is_empty()
        );
        assert!(parse_port_target_policy(&["localhost:3000".to_owned()], true).is_err());

        std::fs::remove_dir_all(root).unwrap();
    }

    #[test]
    fn journal_compacts_and_detects_gap() {
        let mut journal = Journal::default();
        for _ in 0..=JOURNAL_MAX_EVENTS {
            journal.append(EventKind::PtyStateAdvanced { generation: 1 });
        }
        journal.enforce_bounds();
        let (_, compacted) = journal.since(0);
        assert!(compacted);
        assert_eq!(
            journal.oldest_event_unix_ms,
            journal.events.front().map(|event| event.unix_ms)
        );
        let (events, compacted) = journal.since(journal.next_id - 1);
        assert!(!compacted);
        assert_eq!(events.len(), 1);
    }

    #[test]
    fn journal_rollback_does_not_drop_retained_history() {
        let mut journal = Journal::default();
        for _ in 0..=JOURNAL_MAX_EVENTS {
            journal.append(EventKind::PtyStateAdvanced { generation: 1 });
        }
        journal.enforce_bounds();
        let retained_before = journal.events.front().map(|event| event.id);
        let pending = journal.append(EventKind::PtyStateAdvanced { generation: 2 });
        journal.rollback(&pending);
        assert_eq!(
            journal.events.front().map(|event| event.id),
            retained_before
        );
    }

