    #[test]
    fn validate_configuration_is_non_mutating_after_initialization() {
        let root = std::env::temp_dir().join(format!("asp-validate-config-{}", Uuid::new_v4()));
        std::fs::create_dir_all(&root).unwrap();
        ensure_private_directory(&root.join(".asp")).unwrap();
        let cert = root.join(".asp/server-cert.der");
        let key = root.join(".asp/server-key.der");
        let token = root.join(".asp/auth-token");
        let lock = root.join(".asp/aspd.lock");
        let audit = root.join(".asp/audit.log");
        let _ = load_or_create_tls(&cert, &key, None).unwrap();
        #[cfg(unix)]
        {
            use std::os::unix::fs::PermissionsExt;
            std::fs::set_permissions(&key, std::fs::Permissions::from_mode(0o644)).unwrap();
            let _ = load_or_create_tls(&cert, &key, None).unwrap();
            assert_eq!(
                std::fs::metadata(&key).unwrap().permissions().mode() & 0o777,
                0o600
            );
        }
        let _ = load_or_create_auth_token(&token).unwrap();
        validate_configuration(
            &root,
            &cert,
            &key,
            &token,
            &lock,
            &audit,
            None,
            None,
            None,
            false,
            Some("127.0.0.1:0".parse().unwrap()),
            DEFAULT_PRINCIPAL_REQUEST_BYTES_PER_MINUTE,
            DEFAULT_PRINCIPAL_RESPONSE_BYTES_PER_MINUTE,
        )
        .unwrap();
        assert!(!lock.exists());
        assert!(!audit.exists());
        std::fs::remove_dir_all(root).unwrap();
    }

