    #[test]
    fn first_run_tls_creation_rejects_orphaned_material() {
        let root = std::env::temp_dir().join(format!("asp-tls-orphan-{}", Uuid::new_v4()));
        std::fs::create_dir_all(&root).unwrap();
        let cert = root.join("server-cert.der");
        let key = root.join("server-key.der");
        let _ = load_or_create_tls(&cert, &key, None).unwrap();

        std::fs::remove_file(&cert).unwrap();
        let error = match load_or_create_tls(&cert, &key, None) {
            Ok(_) => panic!("orphaned TLS key should fail closed"),
            Err(error) => error,
        };
        assert!(error.to_string().contains("private key"));
        assert!(!cert.exists());

        std::fs::remove_file(&key).unwrap();
        let _ = load_or_create_tls(&cert, &key, None).unwrap();
        std::fs::remove_file(&key).unwrap();
        let error = match load_or_create_tls(&cert, &key, None) {
            Ok(_) => panic!("orphaned TLS certificate should fail closed"),
            Err(error) => error,
        };
        assert!(error.to_string().contains("private key"));
        assert!(!key.exists());

        std::fs::remove_dir_all(root).unwrap();
    }

    #[test]
    fn admin_session_inventory_and_deletion_are_conservative() {
        let root = std::env::temp_dir().join(format!("asp-session-admin-{}", Uuid::new_v4()));
        std::fs::create_dir_all(&root).unwrap();
        let store = SessionStore::open(root.clone(), None).unwrap();
        let session = store.create().unwrap();
        let session_id = session.id;
        let directory = root.join(".asp/sessions").join(session_id.to_string());

        let summaries = store.admin_session_summaries();
        assert_eq!(summaries.len(), 1);
        assert_eq!(summaries[0].session_id, session_id);
        assert_eq!(summaries[0].owner, "legacy");
        assert_eq!(summaries[0].latest_event_id, 1);

        session.running_processes.store(1, Ordering::Release);
        assert!(store.delete_session(session_id).is_err());
        session.running_processes.store(0, Ordering::Release);
        session.pty_started.store(true, Ordering::Release);
        assert!(store.delete_session(session_id).is_err());
        session.pty_started.store(false, Ordering::Release);
        session.active_subscriptions.store(1, Ordering::Release);
        assert!(store.delete_session(session_id).is_err());
        session.active_subscriptions.store(0, Ordering::Release);

        store.delete_session(session_id).unwrap();
        assert!(!directory.exists());
        assert!(store.get(session_id).is_err());
        assert!(store.admin_session_summaries().is_empty());
        std::fs::remove_dir_all(root).unwrap();
    }

    #[test]
    fn readiness_requires_a_healthy_audit_sink() {
        let root = std::env::temp_dir().join(format!("asp-readiness-{}", Uuid::new_v4()));
        std::fs::create_dir_all(&root).unwrap();
        let store = SessionStore::open(root.clone(), None).unwrap();
        let initial = store.health_snapshot();
        assert!(!initial.ready);
        assert_eq!(initial.ready_reasons, vec!["audit_disabled"]);
        let audit = root.join("audit.log");
        store.set_audit_log(audit).unwrap();
        let healthy = store.health_snapshot();
        assert!(healthy.ready);
        assert!(healthy.ready_reasons.is_empty());
        assert!(!healthy.draining);
        store.set_draining();
        let draining = store.health_snapshot();
        assert!(draining.draining);
        assert!(!draining.ready);
        assert_eq!(draining.ready_reasons, vec!["draining"]);
        store.shutdown_audit().unwrap();
        std::fs::remove_dir_all(root).unwrap();
    }

    #[test]
    fn readiness_reports_stale_or_failed_storage_maintenance() {
        let root =
            std::env::temp_dir().join(format!("asp-readiness-maintenance-{}", Uuid::new_v4()));
        std::fs::create_dir_all(&root).unwrap();
        let store = SessionStore::open(root.clone(), None).unwrap();
        store.set_audit_log(root.join("audit.log")).unwrap();

        // Before the first scheduled pass, startup should not flap readiness
        // just because the 30-second maintenance interval has not elapsed.
        let initial = store.health_snapshot();
        assert!(initial.storage_maintenance_healthy);
        assert_eq!(initial.storage_maintenance_runs_total, 0);

        let stale = unix_ms().saturating_sub(
            STORAGE_MAINTENANCE_STALE_AFTER
                .as_millis()
                .saturating_add(1) as u64,
        );
        store
            .storage_maintenance_runs_total
            .store(1, Ordering::Release);

        // A blocking pass that never returns must also take readiness out of
        // service.  This is distinct from a completed pass that reported an
        // operation failure: the in-progress timestamp is the only signal a
        // supervisor has while the worker is wedged.
        store
            .storage_maintenance_started_unix_ms
            .store(stale, Ordering::Release);
        let wedged = store.health_snapshot();
        assert!(!wedged.storage_maintenance_healthy);
        assert!(
            wedged
                .ready_reasons
                .contains(&"storage_maintenance_unhealthy")
        );
        store
            .storage_maintenance_started_unix_ms
            .store(0, Ordering::Release);

        store
            .storage_maintenance_last_run_unix_ms
            .store(stale, Ordering::Release);
        let unhealthy = store.health_snapshot();
        assert!(!unhealthy.storage_maintenance_healthy);
        assert!(
            unhealthy
                .ready_reasons
                .contains(&"storage_maintenance_unhealthy")
        );

        // A recent pass that reports an operation failure remains visible and
        // keeps readiness false until a complete pass succeeds.
        store
            .storage_maintenance_last_run_unix_ms
            .store(unix_ms(), Ordering::Release);
        store
            .storage_maintenance_last_failures
            .store(2, Ordering::Release);
        let failed = store.health_snapshot();
        assert!(!failed.storage_maintenance_healthy);
        assert_eq!(failed.storage_maintenance_last_failures, 2);
        assert_eq!(failed.storage_maintenance_failures_total, 0);

        store
            .storage_maintenance_last_failures
            .store(0, Ordering::Release);
        store
            .storage_maintenance_last_success_unix_ms
            .store(unix_ms(), Ordering::Release);
        let recovered = store.health_snapshot();
        assert!(recovered.storage_maintenance_healthy);
        assert!(
            !recovered
                .ready_reasons
                .contains(&"storage_maintenance_unhealthy")
        );
        store.shutdown_audit().unwrap();
        std::fs::remove_dir_all(root).unwrap();
    }

