    #[test]
    fn health_snapshot_exposes_quic_transport_counters() {
        let root = std::env::temp_dir().join(format!("asp-quic-health-{}", Uuid::new_v4()));
        std::fs::create_dir_all(&root).unwrap();
        let store = SessionStore::open(root.clone(), None).unwrap();
        store.quic_udp_tx_bytes_total.store(1234, Ordering::Release);
        store.quic_lost_packets_total.store(3, Ordering::Release);
        store.quic_path_rtt_us.store(42, Ordering::Release);
        store.quic_path_mtu.store(1200, Ordering::Release);
        store.record_resume(7, 2, true, true);
        store.record_replay_limit();
        let health = store.health_snapshot();
        assert_eq!(health.quic_udp_tx_bytes_total, 1234);
        assert_eq!(health.quic_lost_packets_total, 3);
        assert_eq!(health.quic_path_rtt_us, 42);
        assert_eq!(health.quic_path_mtu, 1200);
        assert_eq!(health.resume_requests_total, 1);
        assert_eq!(health.resume_events_replayed_total, 2);
        assert_eq!(health.resume_compacted_total, 1);
        assert_eq!(health.resume_replay_limited_total, 2);
        assert_eq!(health.resume_lag_events_max, 7);
        assert_eq!(health.response_memory_bytes, 0);
        assert_eq!(health.process_no_new_privs, cfg!(target_os = "linux"));
        assert_eq!(
            health.response_memory_limit,
            MAX_IN_FLIGHT_RESPONSE_BYTES as u64
        );
        let permit = Arc::clone(&store.response_memory)
            .try_acquire_many_owned(2)
            .unwrap();
        assert_eq!(
            store.health_snapshot().response_memory_bytes,
            (2 * FRAME_MEMORY_UNIT_BYTES) as u64
        );
        drop(permit);
        std::fs::remove_dir_all(root).unwrap();
    }

