        let store = SessionStore::open(root.clone(), Some(Arc::from("a".repeat(32)))).unwrap();
        let source = "127.0.0.1".parse::<IpAddr>().unwrap();
        for _ in 0..AUTH_FAILURE_LIMIT {
            assert!(store.auth_attempt_allowed(source));
            store.record_auth_failure(source);
        }
        assert!(!store.auth_attempt_allowed(source));
