    #[cfg(unix)]
    #[test]
    fn production_workspace_root_rejects_final_symlink_before_resolution() {
        let parent = std::env::temp_dir().join(format!("asp-production-root-{}", Uuid::new_v4()));
        let target = parent.join("target");
        let link = parent.join("workspace");
        std::fs::create_dir_all(&target).unwrap();
        std::os::unix::fs::symlink(&target, &link).unwrap();

        assert!(resolve_workspace_root(&link, true).is_err());
        assert_eq!(
            resolve_workspace_root(&link, false).unwrap(),
            target.canonicalize().unwrap()
        );

        std::fs::remove_file(link).unwrap();

        let real_parent = parent.join("real");
        let linked_parent = parent.join("linked");
        let nested_target = real_parent.join("workspace");
        std::fs::create_dir_all(&nested_target).unwrap();
        std::os::unix::fs::symlink(&real_parent, &linked_parent).unwrap();
        let through_link = linked_parent.join("workspace");
        assert!(resolve_workspace_root(&through_link, true).is_err());
        assert_eq!(
            resolve_workspace_root(&through_link, false).unwrap(),
            nested_target.canonicalize().unwrap()
        );

        std::fs::remove_file(linked_parent).unwrap();
        std::fs::remove_dir_all(parent).unwrap();
    }

    #[test]
    fn storage_headroom_policy_fails_closed_and_is_bounded() {
        assert!(validate_min_free_bytes(0).is_ok());
        assert!(validate_min_free_bytes(MAX_MIN_FREE_BYTES).is_ok());
        assert!(validate_min_free_bytes(MAX_MIN_FREE_BYTES + 1).is_err());
        assert!(validate_production_storage_policy(false, 0).is_ok());
        assert!(validate_production_storage_policy(true, 0).is_err());
        assert!(validate_production_storage_policy(true, 1).is_ok());

        let root = std::env::temp_dir().join(format!("asp-storage-headroom-{}", Uuid::new_v4()));
        std::fs::create_dir_all(&root).unwrap();
        assert!(validate_storage_headroom(&root, 1).is_ok());
        assert!(validate_storage_headroom(&root, u64::MAX).is_err());
        let store = SessionStore::open(root.clone(), Some(Arc::from("a".repeat(32)))).unwrap();
        store.set_min_free_bytes(1);
        assert!(store.storage_headroom_ok());
        store.ensure_storage_headroom().unwrap();
        store.set_min_free_bytes(u64::MAX);
        assert!(!store.storage_headroom_ok());
        assert!(store.ensure_storage_headroom().is_err());
        assert_eq!(store.storage_headroom_rejections(), 1);
        assert_eq!(store.health_snapshot().storage_free_bytes_limit, u64::MAX);
        assert!(!store.health_snapshot().storage_headroom_ok);
        std::fs::remove_dir_all(root).unwrap();
    }

