    #[cfg(target_os = "linux")]
    #[test]
    fn linux_process_children_default_to_no_new_privs() {
        let mut command = std::process::Command::new("/bin/sh");
        command.args(["-c", "grep '^NoNewPrivs:' /proc/self/status"]);
        // SAFETY: the child hook only invokes the async-signal-safe `prctl`
        // syscall through `apply_process_limits`; it reads no Rust state.
        unsafe {
            command.pre_exec(|| apply_process_limits(ProcessLimits::default()));
        }
        let output = command.output().expect("spawn no_new_privs probe");
        assert!(output.status.success());
        assert_eq!(
            String::from_utf8_lossy(&output.stdout).trim(),
            "NoNewPrivs:\t1"
        );
    }

    #[test]
    fn process_launcher_configuration_is_fail_closed() {
        assert!(process_launcher_from_args(None, &[], false).is_ok());
        assert!(process_launcher_from_args(None, &[], true).is_err());
        assert!(process_launcher_from_args(None, &["--flag".to_owned()], false).is_err());
        assert!(process_launcher_from_args(Some(Path::new("sh")), &[], false).is_err());

        let executable = std::env::current_exe().unwrap();
        let launcher =
            process_launcher_from_args(Some(&executable), &["--operator-flag".to_owned()], true)
                .unwrap();
        assert_eq!(launcher.program.as_deref(), Some(executable.as_path()));
        assert_eq!(launcher.args, vec!["--operator-flag"]);
        assert!(launcher.required);

        let too_many = vec![String::from("x"); MAX_PROCESS_LAUNCHER_ARGS + 1];
        assert!(process_launcher_from_args(Some(&executable), &too_many, false).is_err());
        assert!(
            process_launcher_from_args(Some(&executable), &["bad\0arg".to_owned()], false).is_err()
        );
        assert!(
            process_launcher_from_args(
                Some(&executable),
                &["x".repeat(MAX_PROCESS_LAUNCHER_ARG_BYTES + 1)],
                false
            )
            .is_err()
        );
    }

    #[cfg(unix)]
    #[test]
    fn process_launcher_rejects_symlinks_and_non_executables() {
        use std::os::unix::fs::{PermissionsExt, symlink};

        let root = std::env::temp_dir().join(format!("asp-process-launcher-{}", Uuid::new_v4()));
        std::fs::create_dir_all(&root).unwrap();
        let executable = std::env::current_exe().unwrap();
        let linked = root.join("linked-launcher");
        symlink(&executable, &linked).unwrap();
        assert!(process_launcher_from_args(Some(&linked), &[], false).is_err());

        let real_directory = root.join("real");
        std::fs::create_dir_all(&real_directory).unwrap();
        let real_launcher = real_directory.join("launcher");
        std::fs::write(&real_launcher, b"#!/bin/sh\nexec \"$@\"\n").unwrap();
        std::fs::set_permissions(&real_launcher, std::fs::Permissions::from_mode(0o700)).unwrap();
        let directory_alias = root.join("alias");
        symlink(&real_directory, &directory_alias).unwrap();
        let aliased_launcher = directory_alias.join("launcher");
        let launcher = process_launcher_from_args(Some(&aliased_launcher), &[], false).unwrap();
        let canonical_real_launcher = real_launcher.canonicalize().unwrap();
        assert_eq!(
            launcher.program.as_deref(),
            Some(canonical_real_launcher.as_path())
        );

        let plain = root.join("plain-launcher");
        std::fs::write(&plain, b"#!/bin/sh\nexec \"$@\"\n").unwrap();
        std::fs::set_permissions(&plain, std::fs::Permissions::from_mode(0o600)).unwrap();
        assert!(process_launcher_from_args(Some(&plain), &[], false).is_err());

        std::fs::set_permissions(&plain, std::fs::Permissions::from_mode(0o702)).unwrap();
        assert!(process_launcher_from_args(Some(&plain), &[], false).is_err());
        std::fs::remove_dir_all(root).unwrap();
    }

    #[cfg(unix)]
    #[test]
    fn process_launcher_rejects_same_path_replacement_after_startup() {
        use std::os::unix::fs::PermissionsExt;

        let root =
            std::env::temp_dir().join(format!("asp-process-launcher-drift-{}", Uuid::new_v4()));
        std::fs::create_dir_all(&root).unwrap();
        let launcher_path = root.join("launcher");
        std::fs::write(&launcher_path, b"#!/bin/sh\nexec \"$@\"\n").unwrap();
        std::fs::set_permissions(&launcher_path, std::fs::Permissions::from_mode(0o700)).unwrap();
        let launcher = process_launcher_from_args(Some(&launcher_path), &[], true).unwrap();

        let replacement = root.join("launcher.new");
        std::fs::write(&replacement, b"#!/bin/sh\nexit 99\n").unwrap();
        std::fs::set_permissions(&replacement, std::fs::Permissions::from_mode(0o700)).unwrap();
        std::fs::rename(&replacement, &launcher_path).unwrap();

        let error = validate_process_launcher_unchanged(&launcher).unwrap_err();
        assert!(error.to_string().contains("changed after startup"));
        std::fs::remove_dir_all(root).unwrap();
    }

    #[test]
    fn exec_timeout_values_are_bounded() {
        assert!(validate_exec_timeout(0).is_ok());
        assert!(validate_exec_timeout(MAX_EXEC_TIMEOUT_SECONDS).is_ok());
        assert!(validate_exec_timeout(MAX_EXEC_TIMEOUT_SECONDS + 1).is_err());
        assert_eq!(
            exec_timeout_duration(
                ProcessLimits {
                    memory_bytes: 0,
                    cpu_seconds: 0,
                    exec_timeout_seconds: 5,
                    no_new_privs: true,
                },
                true,
            ),
            Some(Duration::from_secs(5))
        );
        assert!(exec_timeout_duration(ProcessLimits::default(), true).is_none());
        assert!(
            exec_timeout_duration(
                ProcessLimits {
                    memory_bytes: 0,
                    cpu_seconds: 0,
                    exec_timeout_seconds: 5,
                    no_new_privs: true,
                },
                false,
            )
            .is_none()
        );
    }

    #[test]
    fn shutdown_grace_values_are_bounded() {
        assert_eq!(
            shutdown_grace_duration(DEFAULT_SHUTDOWN_GRACE_SECONDS).unwrap(),
            Duration::from_secs(DEFAULT_SHUTDOWN_GRACE_SECONDS)
        );
        assert_eq!(shutdown_grace_duration(0).unwrap(), Duration::ZERO);
        assert!(shutdown_grace_duration(MAX_SHUTDOWN_GRACE_SECONDS + 1).is_err());
    }

    #[test]
    fn bind_policy_never_exposes_insecure_or_health_endpoints() {
        let loopback = "127.0.0.1:4433".parse().unwrap();
        let private = "192.0.2.10:4433".parse().unwrap();
        let health = "127.0.0.1:9443".parse().unwrap();
        let public_health = "192.0.2.10:9443".parse().unwrap();

        assert!(validate_bind_policy(loopback, false, true, Some(health)).is_ok());
        assert!(validate_bind_policy(private, false, false, None).is_err());
        assert!(validate_bind_policy(private, true, true, None).is_err());
        assert!(validate_bind_policy(loopback, false, false, Some(public_health)).is_err());
        assert!(validate_bind_policy(private, true, false, Some(health)).is_ok());
    }

    #[test]
    fn frame_modes_are_explicitly_bound_to_protocol_versions() {
        assert_eq!(
            frame_mode_for_version(LEGACY_PROTOCOL_VERSION),
            Some(FRAME_MODE_LEGACY)
        );
        assert_eq!(
            frame_mode_for_version(PROTOCOL_VERSION),
            Some(FRAME_MODE_CURRENT)
        );
        assert_eq!(frame_mode_for_version(PROTOCOL_VERSION + 1), None);
        assert_eq!(
            frame_mode_version(FRAME_MODE_LEGACY),
            Some(LEGACY_PROTOCOL_VERSION)
        );
        assert_eq!(
            frame_mode_version(FRAME_MODE_CURRENT),
            Some(PROTOCOL_VERSION)
        );
        assert_eq!(frame_mode_version(FRAME_MODE_UNKNOWN), None);
    }

