    #[test]
    fn resumable_upload_staging_is_private_idempotent_and_prunable() {
        let root = std::env::temp_dir().join(format!("asp-upload-stage-{}", Uuid::new_v4()));
        let store = SessionStore::open(root.clone(), None).unwrap();
        let session = store.create().unwrap();
        let request_id = Uuid::new_v4();
        let paths = UploadPaths::new(&session, request_id).unwrap();
        let pending = PendingFileUpload {
            request_id,
            request_hash: "hash".into(),
            path: "src/main.rs".into(),
            total_size: 4,
            sha256: format!("{:x}", Sha256::digest(b"test")),
            expected_sha256: None,
            allow_blind: false,
        };
        write_pending_file_upload(&paths, &pending).unwrap();
        std::fs::write(&paths.part, b"te").unwrap();
        set_private_permissions(&paths.part).unwrap();
        assert_eq!(
            read_pending_file_upload(&paths).unwrap().unwrap().path,
            pending.path
        );

        // An active request ID is a lease and cannot be collected by the
        // background maintenance pass.
        let lock = session.upload_lock(request_id);
        assert_eq!(store.prune_upload_staging(Duration::ZERO).unwrap(), 0);
        session.release_upload_lock(request_id, &lock);
        drop(lock);
        assert_eq!(store.prune_upload_staging(Duration::ZERO).unwrap(), 1);
        assert!(!paths.directory.exists());
        drop(store);
        std::fs::remove_dir_all(root).unwrap();
    }

