    #[test]
    fn committed_artifacts_are_gc_tombstoned_and_do_not_resurrect() {
        let root = std::env::temp_dir().join(format!("asp-artifact-gc-{}", Uuid::new_v4()));
        let store = SessionStore::open(root.clone(), None).unwrap();
        let session = store.create().unwrap();
        let request_id = Uuid::new_v4();
        let data = b"artifact-retention-test";
        let artifact_id = sha256(data);
        let artifact_directory = session.artifact_directory().unwrap();
        let temporary = artifact_directory.join(format!("asp-tmp-{request_id}"));
        std::fs::write(&temporary, data).unwrap();
        set_private_permissions(&temporary).unwrap();
        let request_hash =
            artifact_request_hash(&artifact_id, data.len() as u64, Some("gc.bin")).unwrap();
        let reservation = session.reserve_idempotency_record().unwrap();
        let runtime = tokio::runtime::Runtime::new().unwrap();
        let response = runtime.block_on(commit_artifact(
            &session,
            request_id,
            request_hash,
            artifact_id.clone(),
            data.len() as u64,
            Some("gc.bin".into()),
            temporary,
            artifact_id.clone(),
            reservation,
        ));
        drop(runtime);
        assert!(matches!(response.unwrap(), Response::ArtifactStored { .. }));
        let object = session.artifact_path(&artifact_id).unwrap();
        assert!(object.is_file());

        let _read_lease = session.artifact_read_lease(&artifact_id).unwrap();
        assert_eq!(store.prune_artifacts(Duration::ZERO).unwrap(), 0);
        drop(_read_lease);
        assert_eq!(store.prune_artifacts(Duration::ZERO).unwrap(), 1);
        assert!(!object.exists());
        assert!(session.artifact_record(&artifact_id).unwrap().is_none());
        assert!(
            session
                .journal
                .lock()
                .unwrap()
                .events
                .iter()
                .any(|event| matches!(
                    event.kind,
                    EventKind::ArtifactDeleted { artifact_id: ref id, .. } if id == &artifact_id
                ))
        );

        drop(store);
        let restored = SessionStore::open(root.clone(), None).unwrap();
        let restored_session = restored
            .sessions
            .read()
            .unwrap()
            .get(&session.id)
            .cloned()
            .unwrap();
        assert!(
            restored_session
                .artifact_record(&artifact_id)
                .unwrap()
                .is_none()
        );

        // A crash after the tombstone but before unlink leaves only an
        // unreferenced digest file; the age-bounded orphan pass cleans it
        // without touching unknown names.
        let orphan_dir = restored_session.artifact_directory().unwrap();
        let orphan_id = sha256(b"orphan");
        let orphan = orphan_dir.join(&orphan_id);
        std::fs::write(&orphan, b"orphan").unwrap();
        set_private_permissions(&orphan).unwrap();
        assert_eq!(restored.prune_artifacts(Duration::ZERO).unwrap(), 1);
        assert!(!orphan.exists());
        std::fs::remove_dir_all(root).unwrap();
    }

    #[tokio::test]
    async fn same_owner_artifacts_are_reused_across_sessions_without_reupload() {
        let root = std::env::temp_dir().join(format!("asp-artifact-dedup-{}", Uuid::new_v4()));
        let store = SessionStore::open(root.clone(), None).unwrap();
        let source = store.create().unwrap();
        let target = store.create().unwrap();
        let data = b"shared-build-artifact";
        let artifact_id = sha256(data);
        let source_directory = source.artifact_directory().unwrap();
        let source_temporary = source_directory.join("source-staged.tmp");
        std::fs::write(&source_temporary, data).unwrap();
        set_private_permissions(&source_temporary).unwrap();
        let source_request_id = Uuid::new_v4();
        let source_reservation = source.reserve_idempotency_record().unwrap();
        let source_hash =
            artifact_request_hash(&artifact_id, data.len() as u64, Some("build.bin")).unwrap();
        let source_response = commit_artifact(
            &source,
            source_request_id,
            source_hash,
            artifact_id.clone(),
            data.len() as u64,
            Some("build.bin".into()),
            source_temporary,
            artifact_id.clone(),
            source_reservation,
        )
        .await
        .unwrap();
        assert!(matches!(source_response, Response::ArtifactStored { .. }));
        store.index_artifact(&source, &artifact_id);

        let target_request_id = Uuid::new_v4();
        let target_hash =
            artifact_request_hash(&artifact_id, data.len() as u64, Some("copy.bin")).unwrap();
        let target_response = try_deduplicate_artifact(
            &store,
            &target,
            target_request_id,
            &target_hash,
            &artifact_id,
            data.len() as u64,
            Some("copy.bin"),
        )
        .await
        .unwrap()
        .expect("same-owner artifact should be reused");
        assert!(matches!(target_response, Response::ArtifactStored { .. }));
        let health = store.health_snapshot();
        assert_eq!(health.artifact_dedup_hits_total, 1);
        assert_eq!(health.artifact_dedup_bytes_total, data.len() as u64);
        let target_path = target.artifact_path(&artifact_id).unwrap();
        assert_eq!(std::fs::read(&target_path).unwrap(), data);
        assert_eq!(
            target
                .artifact_record(&artifact_id)
                .unwrap()
                .unwrap()
                .name
                .as_deref(),
            Some("copy.bin")
        );
        #[cfg(unix)]
        {
            use std::os::unix::fs::MetadataExt;
            assert!(std::fs::metadata(&target_path).unwrap().nlink() >= 2);
        }

        // A different owner must not be able to use the digest as a
        // cross-session read oracle. Build a foreign session with the same
        // object and ensure discovery still refuses it.
        let foreign_id = Uuid::new_v4();
        let foreign = Session::persisted(
            root.clone(),
            foreign_id,
            store.sessions_dir.join(foreign_id.to_string()),
            Arc::from("foreign"),
            Arc::clone(&store.workspace_file_versions),
        )
        .unwrap();
        store
            .sessions
            .write()
            .unwrap()
            .insert(foreign_id, Arc::clone(&foreign));
        let foreign_directory = foreign.artifact_directory().unwrap();
        let foreign_temporary = foreign_directory.join("foreign-staged.tmp");
        std::fs::write(&foreign_temporary, data).unwrap();
        set_private_permissions(&foreign_temporary).unwrap();
        let foreign_reservation = foreign.reserve_idempotency_record().unwrap();
        let foreign_hash = artifact_request_hash(&artifact_id, data.len() as u64, None).unwrap();
        commit_artifact(
            &foreign,
            Uuid::new_v4(),
            foreign_hash,
            artifact_id.clone(),
            data.len() as u64,
            None,
            foreign_temporary,
            artifact_id,
            foreign_reservation,
        )
        .await
        .unwrap();
        // The same-owner source remains the only eligible candidate while it
        // is registered in the store. This also makes the owner filter
        // observable rather than merely checking that *some* object exists.
        let found = store
            .find_same_owner_artifact(&target, &sha256(data), data.len() as u64)
            .await
            .unwrap()
            .expect("same-owner source should remain discoverable");
        assert_eq!(found.id, source.id);

        // Remove the same-owner entry from the in-memory inventory. With only
        // the foreign session left, discovery must fail closed even though the
        // digest and bytes are identical.
        store.sessions.write().unwrap().remove(&source.id);
        assert!(
            store
                .find_same_owner_artifact(&target, &sha256(data), data.len() as u64)
                .await
                .unwrap()
                .is_none()
        );

        let target_id = target.id;
        let source_id = source.id;
        drop(store);
        let restored = SessionStore::open(root.clone(), None).unwrap();
        let restored_target = restored.get(target_id).unwrap();
        let restored_found = restored
            .find_same_owner_artifact(&restored_target, &sha256(data), data.len() as u64)
            .await
            .unwrap()
            .expect("startup should rebuild the artifact index");
        assert_eq!(restored_found.id, source_id);
        restored.delete_session(source_id).unwrap();
        assert!(
            restored
                .find_same_owner_artifact(&restored_target, &sha256(data), data.len() as u64)
                .await
                .unwrap()
                .is_none()
        );
        drop(restored);
        std::fs::remove_dir_all(root).unwrap();
    }

