    #[tokio::test]
    async fn monitor_failure_publishes_terminal_exit_event() {
        let session = Session::new(std::env::current_dir().unwrap());
        session.running_processes.store(1, Ordering::Release);
        let process_id = Uuid::new_v4();
        let record = Arc::new(Mutex::new(ProcessRecord {
            command: "test".into(),
            running: true,
            exit_code: None,
            exit_unix_ms: None,
            pid: None,
            pid_start_time: None,
            stdout_bytes: 0,
            stderr_bytes: 0,
        }));
        let (tx, mut rx) = mpsc::channel(4);
        let mut responses = Some(tx);
        terminate_and_record_process_failure(&session, process_id, &record, None, &mut responses)
            .await;

        assert!(!record.lock().unwrap().running);
        assert_eq!(session.running_processes.load(Ordering::Acquire), 0);
        assert!(matches!(
            session.journal.lock().unwrap().events.back().map(|event| &event.kind),
            Some(EventKind::ProcessExited {
                process_id: id,
                code: None,
            }) if *id == process_id
        ));
        assert!(matches!(
            rx.recv().await.map(|queued| queued.response),
            Some(Response::ProcessExited {
                process_id: id,
                code: None,
                ..
            }) if id == process_id
        ));
    }

    #[cfg(unix)]
    #[tokio::test]
    async fn monitor_failure_never_signals_unverified_recovered_pid() {
        let session = Session::new(std::env::current_dir().unwrap());
        session.running_processes.store(1, Ordering::Release);
        let mut child = Command::new("/bin/sh")
            .args(["-c", "sleep 5"])
            .spawn()
            .expect("spawn unrelated process");
        let pid = child.id();
        let process_id = Uuid::new_v4();
        let record = Arc::new(Mutex::new(ProcessRecord {
            command: "recovered".into(),
            running: true,
            exit_code: None,
            exit_unix_ms: None,
            pid,
            // Model a process reconstructed from a legacy WAL that predates
            // persisted Linux start-time identity.
            pid_start_time: None,
            stdout_bytes: 0,
            stderr_bytes: 0,
        }));
        let (tx, _rx) = mpsc::channel(1);
        let mut responses = Some(tx);
        terminate_and_record_process_failure(&session, process_id, &record, None, &mut responses)
            .await;

        // This synthetic session has no durable process wrapper to prove the
        // PID belongs to ASP. The helper must publish the terminal event but
        // leave the unrelated child untouched.
        assert!(process_is_alive(pid));
        assert!(!record.lock().unwrap().running);
        child.kill().await.expect("clean up unrelated process");
        let _ = child.wait().await;
    }

    #[test]
    fn state_backup_verifies_and_restores_without_copying_the_daemon_lock() {
        let root = std::env::temp_dir().join(format!("asp-backup-{}", Uuid::new_v4()));
        let backup = std::env::temp_dir().join(format!("asp-backup-copy-{}", Uuid::new_v4()));
        std::fs::create_dir_all(root.join(".asp/sessions/demo")).expect("create ASP state");
        std::fs::write(root.join(".asp/auth-token"), "token").expect("write token");
        std::fs::write(
            root.join(".asp/sessions/demo/events.log"),
            b"ASPLOG\0\x02\0durable",
        )
        .expect("write event log");
        std::fs::write(root.join(".asp/aspd.lock"), b"stale lock").expect("write lock");

        let manifest = backup_state(&root, &backup).expect("create backup");
        assert_eq!(manifest.version, BACKUP_MANIFEST_VERSION);
        assert_eq!(verify_backup(&backup).unwrap().entries.len(), 2);
        assert!(!backup.join("state/aspd.lock").exists());
        #[cfg(unix)]
        {
            use std::os::unix::fs::PermissionsExt;
            assert_eq!(
                std::fs::metadata(&backup).unwrap().permissions().mode() & 0o777,
                0o700
            );
        }

        std::fs::write(root.join(".asp/auth-token"), "changed").expect("mutate state");
        let previous = restore_state(&root, &backup, true).expect("restore backup");
        assert!(previous.as_ref().is_some_and(|path| path.exists()));
        assert_eq!(
            std::fs::read(root.join(".asp/auth-token")).unwrap(),
            b"token"
        );

        std::fs::remove_dir_all(root).unwrap();
        std::fs::remove_dir_all(backup).unwrap();
    }

