    #[test]
    fn principal_identity_remains_bound_when_credentials_rotate() {
        let active = Arc::new(Mutex::new(HashMap::new()));
        let original = AuthPrincipal::legacy("original-token");
        let replacement = AuthPrincipal {
            id: Arc::from("other-principal"),
            credential: Arc::from("replacement-token"),
            certificate_sha256: None,
            scopes: default_auth_scopes(),
        };
        let lease = PrincipalConnectionGuard {
            active: Arc::clone(&active),
            principal: original.id.to_string(),
        };

        // A cleared current credential is expected during token rotation, but
        // the connection lease still prevents a different principal from
        // taking over the attachment.
        assert!(!principal_identity_conflicts(Some(&lease), None, &original));
        assert!(principal_identity_conflicts(
            Some(&lease),
            None,
            &replacement
        ));
        assert!(principal_identity_conflicts(
            Some(&lease),
            Some(&original),
            &replacement
        ));
        assert!(!principal_identity_conflicts(
            None,
            Some(&original),
            &original
        ));
    }

    #[test]
    fn connection_principal_install_is_idempotent_but_rejects_switches() {
        let root = std::env::temp_dir().join(format!(
            "asp-connection-principal-binding-{}",
            Uuid::new_v4()
        ));
        let store = SessionStore::open(root.clone(), None).unwrap();
        let principal = Arc::new(Mutex::new(None));
        let lease = Arc::new(Mutex::new(None));
        let original = AuthPrincipal::legacy("original-token");
        let rotated = AuthPrincipal::legacy("rotated-token");
        let other = AuthPrincipal {
            id: Arc::from("other-principal"),
            credential: Arc::from("other-token"),
            certificate_sha256: None,
            scopes: default_auth_scopes(),
        };

        install_connection_principal(&store, &principal, &lease, original.clone()).unwrap();
        // The request path clears the current credential after detecting
        // rotation; the same principal may then re-authenticate with its new
        // credential while retaining the original lease.
        *principal.lock().unwrap() = None;
        install_connection_principal(&store, &principal, &lease, rotated.clone()).unwrap();
        assert_eq!(principal.lock().unwrap().as_ref(), Some(&rotated));
        assert!(matches!(
            install_connection_principal(&store, &principal, &lease, other),
            Err(PrincipalInstallError::Conflict)
        ));
        assert_eq!(
            store
                .active_principal_connections
                .lock()
                .unwrap()
                .get("legacy"),
            Some(&1)
        );
        drop(lease);
        drop(principal);
        drop(store);
        std::fs::remove_dir_all(root).unwrap();
    }

