    #[test]
    fn idempotency_record_budget_is_bounded_and_released_on_failure() {
        let session = Session::new(std::env::temp_dir());
        assert_eq!(session.idempotency_record_count(), 0);

        let reservation = session.reserve_idempotency_record().unwrap();
        assert_eq!(session.idempotency_record_count(), 1);
        drop(reservation);
        assert_eq!(session.idempotency_record_count(), 0);

        let reservation = session.reserve_idempotency_record().unwrap();
        reservation.commit();
        assert_eq!(session.idempotency_record_count(), 1);

        session
            .idempotency_records
            .store(MAX_IDEMPOTENCY_RECORDS_PER_SESSION, Ordering::Release);
        let error = session
            .reserve_idempotency_record()
            .expect_err("full idempotency table should reject a new side effect");
        assert!(error.to_string().contains("idempotency_capacity"));
        assert_eq!(
            session.idempotency_record_count(),
            MAX_IDEMPOTENCY_RECORDS_PER_SESSION
        );
    }

    #[tokio::test]
    async fn idempotency_capacity_rejects_side_effects_before_execution() {
        let root =
            std::env::temp_dir().join(format!("asp-idempotency-capacity-{}", Uuid::new_v4()));
        std::fs::create_dir_all(&root).unwrap();
        let session = Session::new(root.clone());
        session
            .idempotency_records
            .store(MAX_IDEMPOTENCY_RECORDS_PER_SESSION, Ordering::Release);

        let process_error = start_process(
            None,
            Arc::clone(&session),
            Uuid::new_v4(),
            "printf should-not-run".to_owned(),
            None,
        )
        .await
        .expect_err("full idempotency table must reject EXEC before spawning");
        assert!(process_error.to_string().contains("idempotency_capacity"));
        assert!(session.processes.read().unwrap().is_empty());

        let file_error = store_file(
            &session,
            Uuid::new_v4(),
            file_put_request_hash("capacity.txt", b"should-not-install").unwrap(),
            "capacity.txt".to_owned(),
            b"should-not-install".to_vec(),
        )
        .await
        .expect_err("full idempotency table must reject FILE_PUT before commit");
        assert!(file_error.to_string().contains("idempotency_capacity"));
        assert!(!root.join("capacity.txt").exists());
        tokio::time::timeout(Duration::from_secs(1), async {
            while root.read_dir().unwrap().any(|entry| {
                entry
                    .unwrap()
                    .file_name()
                    .to_string_lossy()
                    .contains("asp-tmp-")
            }) {
                tokio::task::yield_now().await;
            }
        })
        .await
        .expect("temporary upload cleanup should finish after rejection");
        assert!(!root.read_dir().unwrap().any(|entry| {
            entry
                .unwrap()
                .file_name()
                .to_string_lossy()
                .contains("asp-tmp-")
        }));
        std::fs::remove_dir_all(root).unwrap();
    }

