    fn open_session_enforces_per_principal_quota() {
        let root = std::env::temp_dir().join(format!("asp-principal-quota-{}", Uuid::new_v4()));
        let store = SessionStore::open(root.clone(), None).unwrap();
        let principal = AuthPrincipal::legacy("quota-test-token");
        for _ in 0..MAX_SESSIONS_PER_PRINCIPAL {
            store.open_session(Uuid::new_v4(), &principal).unwrap();
        }
        let error = store
            .open_session(Uuid::new_v4(), &principal)
            .err()
            .expect("per-principal quota should reject the next session");
        assert!(error.to_string().contains("principal legacy"));
        drop(store);
        std::fs::remove_dir_all(root).unwrap();
    }

    #[test]
    fn running_process_quota_is_scoped_across_sessions() {
        let root = std::env::temp_dir().join(format!("asp-process-quota-{}", Uuid::new_v4()));
        let store = SessionStore::open(root.clone(), None).unwrap();
        let first = store.create().unwrap();
        let second = store.create().unwrap();
        first
            .running_processes
            .store(MAX_RUNNING_PROCESSES_PER_PRINCIPAL, Ordering::Release);
        let error = store
            .reserve_process_slot(&second)
            .expect_err("principal-wide process quota should reject a new child");
        assert!(error.to_string().contains("running-process limit"));
        assert_eq!(
            store.principal_process_rejections.load(Ordering::Acquire),
            1
        );
        drop(first);
        drop(second);
        drop(store);
        std::fs::remove_dir_all(root).unwrap();
    }

