    #[tokio::test]
    async fn ten_megabyte_output_is_streamed_and_retained_for_resume() {
        let session = Session::new(std::env::current_dir().unwrap());
        let (tx, mut rx) = mpsc::channel(PROCESS_OUTPUT_CHANNEL_CAPACITY);
        let (_, started_event, _) = start_process(
            None,
            Arc::clone(&session),
            Uuid::new_v4(),
            "yes x | head -c 10485760".to_string(),
            Some(tx),
        )
        .await
        .unwrap();
        let mut streamed = 0_usize;
        while let Some(queued) = rx.recv().await {
            let response = queued.response;
            match response {
                Response::ProcessOutput { data, .. } => streamed += data.len(),
                Response::ProcessExited { code, .. } => {
                    assert_eq!(code, Some(0));
                    break;
                }
                _ => {}
            }
        }
        assert_eq!(streamed, 10 * 1024 * 1024);

        let (events, compacted) = session
            .journal
            .lock()
            .expect("journal poisoned")
            .since(started_event);
        assert!(!compacted);
        let retained: usize = events
            .iter()
            .filter_map(|event| match &event.kind {
                EventKind::ProcessOutput { data, .. } => Some(data.len()),
                _ => None,
            })
            .sum();
        assert_eq!(retained, 10 * 1024 * 1024);
    }

    #[tokio::test]
    async fn exec_wall_clock_timeout_terminates_persisted_process() {
        let root = std::env::temp_dir().join(format!("asp-exec-timeout-{}", Uuid::new_v4()));
        let store = SessionStore::open(root.clone(), None).unwrap();
        store.set_process_limits(ProcessLimits {
            memory_bytes: 0,
            cpu_seconds: 0,
            exec_timeout_seconds: 1,
            no_new_privs: true,
        });
        let session = store.create().unwrap();
        let (tx, mut rx) = mpsc::channel(PROCESS_OUTPUT_CHANNEL_CAPACITY);
        let (process_id, _, duplicate) = start_process(
            Some(&store),
            Arc::clone(&session),
            Uuid::new_v4(),
            "sleep 30".into(),
            Some(tx),
        )
        .await
        .unwrap();
        assert!(!duplicate);

        let mut exit_code = None;
        let deadline = Instant::now() + Duration::from_secs(8);
        while Instant::now() < deadline {
            let queued = match tokio::time::timeout(Duration::from_millis(250), rx.recv()).await {
                Ok(Some(queued)) => queued,
                Ok(None) | Err(_) => continue,
            };
            if let Response::ProcessExited { code, .. } = queued.response {
                exit_code = Some(code);
                break;
            }
        }
        assert_eq!(exit_code, Some(Some(PROCESS_TIMEOUT_EXIT_CODE)));
        let record = session
            .processes
            .read()
            .unwrap()
            .get(&process_id)
            .cloned()
            .unwrap();
        assert!(!record.lock().unwrap().running);
        drop(store);
        std::fs::remove_dir_all(root).unwrap();
    }

    #[tokio::test]
    async fn duplicate_process_request_runs_only_once() {
        let root = std::env::temp_dir().join(format!("asp-idempotency-{}", Uuid::new_v4()));
        std::fs::create_dir_all(&root).unwrap();
        let session = Session::new(root.clone());
        let request_id = Uuid::new_v4();
        let first = start_process(
            None,
            Arc::clone(&session),
            request_id,
            "printf x >> idempotency.txt".to_string(),
            None,
        )
        .await
        .unwrap();
        let second = start_process(
            None,
            Arc::clone(&session),
            request_id,
            "printf x >> idempotency.txt".to_string(),
            None,
        )
        .await
        .unwrap();
        assert_eq!(first.0, second.0);
        assert!(second.2);
        for _ in 0..100 {
            if !session
                .processes
                .read()
                .unwrap()
                .get(&first.0)
                .unwrap()
                .lock()
                .unwrap()
                .running
            {
                break;
            }
            tokio::time::sleep(std::time::Duration::from_millis(10)).await;
        }
        assert_eq!(std::fs::read(root.join("idempotency.txt")).unwrap(), b"x");
        std::fs::remove_dir_all(root).unwrap();
    }

