        let without_git = workspace_state(
            &session,
            ".".into(),
            false,
            false,
            false,
            0,
            Vec::new(),
            Vec::new(),
            None,
            None,
            Arc::clone(&index),
            Arc::clone(&memory),
            Arc::clone(&response_memory),
        )
        .await
        .unwrap()
        .response;
