    #[tokio::test]
    async fn workspace_git_query_uses_the_configured_process_launcher() {
        use std::os::unix::fs::PermissionsExt;

        let root = std::env::temp_dir().join(format!("asp-git-helper-launcher-{}", Uuid::new_v4()));
        std::fs::create_dir_all(&root).unwrap();
        let helper = root.join("git-helper");
        std::fs::write(&helper, b"#!/bin/sh\nprintf 'helper-used\\n'\n").unwrap();
        std::fs::set_permissions(&helper, std::fs::Permissions::from_mode(0o755)).unwrap();
        let launcher_path = root.join("launcher");
        // The test launcher deliberately identifies the Git executable and
        // returns its own marker. This proves the policy-aware path invoked
        // the launcher rather than the helper directly; real deployments
        // replace it with their reviewed sandbox/supervisor wrapper.
        std::fs::write(
            &launcher_path,
            b"#!/bin/sh\ncase \"$1\" in *git-helper) printf 'launcher-used\\n'; exit 0;; esac\nexec \"$@\"\n",
        )
        .unwrap();
        std::fs::set_permissions(&launcher_path, std::fs::Permissions::from_mode(0o755)).unwrap();
        let launcher = process_launcher_from_args(Some(&launcher_path), &[], true).unwrap();
        let program = resolve_workspace_git_executable(&helper).expect("helper must resolve");
        let mut index = WorkspaceIndex::new(root.clone());
        Arc::get_mut(&mut index)
            .expect("new index must be uniquely owned")
            .git_program = Some(program);
        index.set_process_launcher(launcher);
        index.watcher_healthy.store(true, Ordering::Release);

        let result = index
            .git(&root, vec!["status".into(), "--short".into()])
            .await
            .unwrap();
        assert_eq!(result.as_deref(), Some("launcher-used\n"));
        // A cached semantic result must not mask a replacement of the helper
        // executable; validation happens before the cache fast path as well
        // as immediately before an actual spawn.
        std::fs::write(
            &helper,
            b"#!/bin/sh\nprintf 'replacement-helper-output-that-is-longer\\n'\n",
        )
        .unwrap();
        let error = index
            .git(&root, vec!["status".into(), "--short".into()])
            .await
            .unwrap_err();
        assert!(error.to_string().contains("Git helper"));
        std::fs::remove_dir_all(root).unwrap();
    }

    #[cfg(unix)]
    #[tokio::test]
    async fn git_helper_output_limit_terminates_descendant_process_group() {
        use std::os::unix::fs::PermissionsExt;

        let root =
            std::env::temp_dir().join(format!("asp-git-helper-descendant-{}", Uuid::new_v4()));
        std::fs::create_dir_all(&root).unwrap();
        let helper = root.join("git");
        // Keep a descendant blocked in the same process group while the
        // helper writes one byte beyond FILE_MAX_BYTES. The bounded reader
        // must stop the whole group; killing only the direct shell would
        // leave the sleep process alive and leak work outside the request.
        std::fs::write(
            &helper,
            b"#!/bin/sh\n( /bin/sleep 30 ) &\nchild=$!\nprintf '%s\\n' \"$child\" > child.pid\n/bin/dd if=/dev/zero bs=1048576 count=17 2>/dev/null\nwait \"$child\"\n",
        )
        .unwrap();
        std::fs::set_permissions(&helper, std::fs::Permissions::from_mode(0o755)).unwrap();
        let program = resolve_workspace_git_executable(&helper).expect("helper must resolve");

        let result = tokio::time::timeout(
            Duration::from_secs(10),
            run_git(Some(&program), &root, &["status", "--short"]),
        )
        .await
        .expect("oversized helper must terminate promptly")
        .unwrap_err();
        assert!(result.to_string().contains("git output exceeds"));

        let child_pid = std::fs::read_to_string(root.join("child.pid"))
            .expect("helper must publish descendant PID")
            .trim()
            .parse::<u32>()
            .expect("descendant PID must be numeric");
        for _ in 0..200 {
            if !process_is_alive(Some(child_pid)) {
                break;
            }
            tokio::time::sleep(Duration::from_millis(10)).await;
        }
        assert!(
            !process_is_alive(Some(child_pid)),
            "output-limit cleanup left descendant process {child_pid} alive"
        );
        std::fs::remove_dir_all(root).unwrap();
    }

    #[tokio::test]
    async fn workspace_state_can_omit_an_unchanged_tree() {
        let root =
            std::env::temp_dir().join(format!("asp-workspace-tree-token-{}", Uuid::new_v4()));
        std::fs::create_dir_all(&root).unwrap();
        std::fs::write(root.join("one.txt"), b"one").unwrap();
        let session = Session::new(root.clone());
        let index = WorkspaceIndex::new(root.clone());
        index.watcher_healthy.store(true, Ordering::Release);
        let memory = Arc::new(Semaphore::new(WORKSPACE_FILE_MEMORY_UNITS));
        let response_memory = Arc::new(Semaphore::new(FRAME_MEMORY_UNITS));

        let first = workspace_state(
            &session,
            ".".into(),
            true,
            false,
            false,
            0,
            Vec::new(),
            Vec::new(),
            None,
            None,
            Arc::clone(&index),
            Arc::clone(&memory),
            Arc::clone(&response_memory),
        )
        .await
        .unwrap()
        .response;
        let first_wire_bytes = encode_message(&first).unwrap().len();
        let Response::WorkspaceState {
            tree_version: Some(version),
            state_digest,
            tree,
            tree_unchanged: false,
            ..
        } = first
        else {
            panic!("first workspace response did not include a tree token");
        };
        assert_eq!(tree.len(), 1);
        let old_digest = state_digest.clone();

        let second = workspace_state(
            &session,
            ".".into(),
            true,
            false,
            false,
            0,
            Vec::new(),
            Vec::new(),
            Some(version),
            Some(state_digest),
            Arc::clone(&index),
            Arc::clone(&memory),
            Arc::clone(&response_memory),
        )
        .await
        .unwrap()
        .response;
        let second_wire_bytes = encode_message(&second).unwrap().len();
        let Response::WorkspaceState {
            tree,
            tree_unchanged: true,
            state_unchanged: true,
            state_digest: second_digest,
            git_status: None,
            diff: None,
            recent_commits,
            search_hits,
            files,
            ..
        } = second
        else {
            panic!("second workspace response did not omit the unchanged tree");
        };
        assert!(tree.is_empty());
        assert!(recent_commits.is_empty());
        assert!(search_hits.is_empty());
        assert!(files.is_empty());
        assert!(second_wire_bytes < first_wire_bytes);
        assert_eq!(second_digest, old_digest);

        std::fs::write(root.join("one.txt"), b"changed").unwrap();
        index.invalidate();
        let third = workspace_state(
            &session,
            ".".into(),
            true,
            false,
            false,
            0,
            Vec::new(),
            Vec::new(),
            None,
            Some(old_digest),
            index,
            memory,
            response_memory,
        )
        .await
        .unwrap()
        .response;
        let Response::WorkspaceState {
            state_unchanged: false,
            tree,
            ..
        } = third
        else {
            panic!("changed workspace incorrectly matched the old digest");
        };
        assert_eq!(tree.len(), 1);
        std::fs::remove_dir_all(root).unwrap();
    }

