    #[tokio::test]
    async fn external_workspace_changes_are_journaled_once_and_versioned() {
        let root = std::env::temp_dir().join(format!("asp-workspace-events-{}", Uuid::new_v4()));
        std::fs::create_dir_all(root.join("src")).unwrap();
        let path = root.join("src/main.rs");
        std::fs::write(&path, b"first\n").unwrap();
        let store = SessionStore::open(root.clone(), None).unwrap();
        let session = store.create().unwrap();
        // WorkspaceIndex canonicalizes its root for watcher paths; use that
        // identity here just as notify does on a real daemon.
        let path = store.workspace_index.root.join("src/main.rs");
        assert_eq!(
            store.workspace_index.event_file_path(&path),
            Some(path.clone())
        );
        let mut changed = HashSet::new();
        changed.insert(path.clone());
        store.record_workspace_file_events(changed).await.unwrap();
        let file_events = || {
            session
                .journal
                .lock()
                .expect("journal poisoned")
                .events
                .iter()
                .filter_map(|event| match &event.kind {
                    EventKind::FileChanged { path, version } => Some((path.clone(), *version)),
                    _ => None,
                })
                .collect::<Vec<_>>()
        };
        assert_eq!(file_events(), vec![("src/main.rs".to_owned(), 1)]);

        let mut duplicate = HashSet::new();
        duplicate.insert(path.clone());
        store.record_workspace_file_events(duplicate).await.unwrap();
        assert_eq!(file_events().len(), 1);

        std::fs::write(&path, b"second\n").unwrap();
        let mut changed_again = HashSet::new();
        changed_again.insert(path.clone());
        store
            .record_workspace_file_events(changed_again)
            .await
            .unwrap();
        assert_eq!(
            file_events(),
            vec![("src/main.rs".to_owned(), 1), ("src/main.rs".to_owned(), 2)]
        );

        std::fs::remove_file(&path).unwrap();
        let mut deleted = HashSet::new();
        deleted.insert(path.clone());
        store.record_workspace_file_events(deleted).await.unwrap();
        assert_eq!(file_events().len(), 3);
        store
            .record_workspace_file_events(HashSet::from([path]))
            .await
            .unwrap();
        assert_eq!(file_events().len(), 3);
        drop(store);
        std::fs::remove_dir_all(root).unwrap();
    }

    #[tokio::test]
    async fn partial_external_workspace_fanout_reuses_version_without_duplicates() {
        let root =
            std::env::temp_dir().join(format!("asp-workspace-partial-events-{}", Uuid::new_v4()));
        std::fs::create_dir_all(root.join("src")).unwrap();
        let path = root.join("src/main.rs");
        std::fs::write(&path, b"partial\n").unwrap();
        let store = SessionStore::open(root.clone(), None).unwrap();
        let first = store.create().unwrap();
        let second = store.create().unwrap();
        let watcher_path = store.workspace_index.root.join("src/main.rs");

        // Simulate the first WAL accepting a notification before a later WAL
        // fails. The shared workspace clock is already at version 1, but the
        // observation cache is intentionally empty just as it would be on a
        // failed worker attempt.
        first
            .append(EventKind::FileChanged {
                path: "src/main.rs".to_owned(),
                version: 1,
            })
            .unwrap();
        store
            .record_workspace_file_events(HashSet::from([watcher_path]))
            .await
            .unwrap();

        let file_events = |session: &Arc<Session>| {
            session
                .journal
                .lock()
                .expect("journal poisoned")
                .events
                .iter()
                .filter_map(|event| match &event.kind {
                    EventKind::FileChanged { path, version } => Some((path.clone(), *version)),
                    _ => None,
                })
                .collect::<Vec<_>>()
        };
        assert_eq!(file_events(&first), vec![("src/main.rs".to_owned(), 1)]);
        assert_eq!(file_events(&second), vec![("src/main.rs".to_owned(), 1)]);

        // A second worker notification for the same unchanged bytes is
        // suppressed by the observation cache and cannot create version 2.
        store
            .record_workspace_file_events(HashSet::from([store
                .workspace_index
                .root
                .join("src/main.rs")]))
            .await
            .unwrap();
        assert_eq!(file_events(&first).len(), 1);
        assert_eq!(file_events(&second).len(), 1);
        drop(store);
        std::fs::remove_dir_all(root).unwrap();
    }

