    #[test]
    fn compaction_prunes_exited_process_records_but_keeps_idempotency_tombstones() {
        let root = std::env::temp_dir().join(format!("asp-process-prune-{}", Uuid::new_v4()));
        let store = SessionStore::open(root.clone(), None).unwrap();
        let session = store.create().unwrap();
        let process_id = Uuid::new_v4();
        let request_id = Uuid::new_v4();
        let command = "echo retained only as a hash".to_owned();
        session.processes.write().unwrap().insert(
            process_id,
            Arc::new(Mutex::new(ProcessRecord {
                command: command.clone(),
                running: false,
                exit_code: Some(0),
                exit_unix_ms: Some(0),
                pid: None,
                pid_start_time: None,
                stdout_bytes: 0,
                stderr_bytes: 0,
            })),
        );
        session.process_requests.lock().unwrap().insert(
            request_id,
            ProcessRequest {
                command: command.clone(),
                command_hash: Some(sha256(command.as_bytes())),
                process_id,
                started_event_id: 1,
            },
        );
        {
            let mut journal = session.journal.lock().unwrap();
            journal.oldest_event_unix_ms = Some(0);
            if let Some(event) = journal.events.front_mut() {
                event.unix_ms = 0;
            }
        }
        assert!(
            session
                .compact_if_needed(Some(Duration::from_secs(1)))
                .unwrap()
        );
        assert!(!session.processes.read().unwrap().contains_key(&process_id));
        let tombstone = session
            .process_requests
            .lock()
            .unwrap()
            .get(&request_id)
            .cloned()
            .unwrap();
        assert!(tombstone.command.is_empty());
        assert!(process_request_matches(&tombstone, &command));
        let session_id = session.id;
        drop(session);
        drop(store);
        let restored_store = SessionStore::open(root.clone(), None).unwrap();
        let restored = restored_store.get(session_id).unwrap();
        let tombstone = restored
            .process_requests
            .lock()
            .unwrap()
            .get(&request_id)
            .cloned()
            .unwrap();
        assert!(tombstone.command.is_empty());
        assert!(process_request_matches(&tombstone, &command));
        assert!(!restored.processes.read().unwrap().contains_key(&process_id));
        drop(restored_store);
        std::fs::remove_dir_all(root).unwrap();
    }

