    #[test]
    fn segmented_event_log_rotates_and_reloads_all_state() {
        let root = std::env::temp_dir().join(format!("asp-log-segments-{}", Uuid::new_v4()));
        std::fs::create_dir_all(&root).unwrap();
        let (disk, _) = SessionDisk::open(&root).unwrap();
        let process_id = Uuid::new_v4();
        let payload = vec![b'x'; 1024 * 1024];
        for id in 1..=65_u64 {
            disk.append(&Event {
                id,
                unix_ms: id,
                kind: EventKind::ProcessOutput {
                    process_id,
                    stream: OutputStream::Stdout,
                    offset: (id - 1) * payload.len() as u64,
                    data: payload.clone(),
                },
            })
            .unwrap();
        }
        disk.sync().unwrap();
        let segments = list_event_segments(&root).unwrap();
        assert!(
            !segments.is_empty(),
            "event log should rotate before 64 MiB"
        );
        drop(disk);
        let (_reopened, loaded) = SessionDisk::open(&root).unwrap();
        assert_eq!(loaded.next_id, 65);
        assert!(!loaded.events.is_empty());
        std::fs::remove_dir_all(root).unwrap();
    }

    #[test]
    fn truncated_rotated_event_segment_is_quarantined_instead_of_truncated() {
        let root = std::env::temp_dir().join(format!("asp-log-segment-tail-{}", Uuid::new_v4()));
        std::fs::create_dir_all(&root).unwrap();
        let segment = root.join("events-00000000000000000001-test.log");
        let mut log = OpenOptions::new()
            .create_new(true)
            .write(true)
            .open(&segment)
            .unwrap();
        log.write_all(EVENT_LOG_MAGIC).unwrap();
        log.write_all(&EVENT_LOG_VERSION.to_be_bytes()).unwrap();
        // The frame advertises four bytes but only two made it to the
        // immutable rotated segment. Treating this like a recoverable active
        // log tail would silently discard an event that was already rotated.
        log.write_all(&4_u32.to_be_bytes()).unwrap();
        log.write_all(&crc32(b"full").to_be_bytes()).unwrap();
        log.write_all(b"to").unwrap();
        log.sync_data().unwrap();
        drop(log);

        let active = root.join("events.log");
        let mut active_log = OpenOptions::new()
            .create_new(true)
            .write(true)
            .open(&active)
            .unwrap();
        active_log.write_all(EVENT_LOG_MAGIC).unwrap();
        active_log
            .write_all(&EVENT_LOG_VERSION.to_be_bytes())
            .unwrap();
        active_log.sync_data().unwrap();
        drop(active_log);

        let error = match SessionDisk::open(&root) {
            Ok(_) => panic!("a torn rotated segment must fail closed"),
            Err(error) => error,
        };
        assert!(error.to_string().contains("truncated event log payload"));
        assert!(!segment.exists());
        assert!(
            std::fs::read_dir(&root)
                .unwrap()
                .filter_map(Result::ok)
                .any(|entry| entry.file_name().to_string_lossy().contains("corrupt-")),
            "torn rotated segment should remain available for recovery"
        );
        std::fs::remove_dir_all(root).unwrap();
    }

