    #[test]
    fn event_log_replay_keeps_memory_bounded_while_rebuilding_state() {
        let root = std::env::temp_dir().join(format!("asp-log-replay-{}", Uuid::new_v4()));
        let session_dir = root.join(".asp/sessions").join(Uuid::new_v4().to_string());
        std::fs::create_dir_all(&session_dir).unwrap();
        let log_path = session_dir.join("events.log");
        let mut log = OpenOptions::new()
            .create_new(true)
            .write(true)
            .open(&log_path)
            .unwrap();
        log.write_all(EVENT_LOG_MAGIC).unwrap();
        log.write_all(&EVENT_LOG_VERSION.to_be_bytes()).unwrap();
        let process_id = Uuid::new_v4();
        let started = Event {
            id: 1,
            unix_ms: 1,
            kind: EventKind::ProcessStarted {
                process_id,
                command: "sleep 60".into(),
                pid: None,
                request_id: Some(Uuid::new_v4()),
            },
        };
        for event in
            std::iter::once(started).chain((2..=JOURNAL_MAX_EVENTS as u64 + 500).map(|id| Event {
                id,
                unix_ms: id,
                kind: EventKind::PtyStateAdvanced { generation: id },
            }))
        {
            let payload = asp_protocol::encode_message(&event).unwrap();
            log.write_all(&(payload.len() as u32).to_be_bytes())
                .unwrap();
            log.write_all(&crc32(&payload).to_be_bytes()).unwrap();
            log.write_all(&payload).unwrap();
        }
        log.sync_data().unwrap();
        drop(log);

        let (_disk, loaded) = SessionDisk::open(&session_dir).unwrap();
        assert_eq!(loaded.next_id, JOURNAL_MAX_EVENTS as u64 + 500);
        assert_eq!(loaded.events.len(), JOURNAL_MAX_EVENTS);
        assert!(
            loaded
                .processes
                .get(&process_id)
                .is_some_and(|record| record.running)
        );
        assert_eq!(loaded.pty_generation, JOURNAL_MAX_EVENTS as u64 + 500);
        std::fs::remove_dir_all(root).unwrap();
    }

    #[test]
    fn durable_replay_recovers_events_evicted_from_memory_window() {
        let root = std::env::temp_dir().join(format!("asp-durable-replay-{}", Uuid::new_v4()));
        let session_id = Uuid::new_v4();
        let session_dir = root.join(".asp/sessions").join(session_id.to_string());
        std::fs::create_dir_all(&session_dir).unwrap();
        let log_path = session_dir.join("events.log");
        let mut log = OpenOptions::new()
            .create_new(true)
            .write(true)
            .open(&log_path)
            .unwrap();
        log.write_all(EVENT_LOG_MAGIC).unwrap();
        log.write_all(&EVENT_LOG_VERSION.to_be_bytes()).unwrap();
        let total = JOURNAL_MAX_EVENTS as u64 + 500;
        for id in 1..=total {
            let event = Event {
                id,
                unix_ms: id,
                kind: EventKind::PtyStateAdvanced { generation: id },
            };
            let payload = asp_protocol::encode_message(&event).unwrap();
            log.write_all(&(payload.len() as u32).to_be_bytes())
                .unwrap();
            log.write_all(&crc32(&payload).to_be_bytes()).unwrap();
            log.write_all(&payload).unwrap();
        }
        log.sync_data().unwrap();
        drop(log);

        let (disk, loaded) = SessionDisk::open(&session_dir).unwrap();
        let session = Session::restored(
            session_id,
            root.clone(),
            Arc::clone(&disk),
            loaded,
            Arc::from("test"),
            Arc::new(Mutex::new(HashMap::new())),
        );
        let _commit = session.commit_lock.lock().unwrap();
        let journal = session.journal.lock().unwrap();
        let (events, compacted, replay_limited) = session.events_since_locked(&journal, 1).unwrap();
        assert!(!compacted);
        assert!(!replay_limited);
        assert_eq!(events.len(), (total - 1) as usize);
        assert_eq!(events.first().unwrap().id, 2);
        assert_eq!(events.last().unwrap().id, total);
        drop(journal);
        drop(_commit);
        drop(session);
        std::fs::remove_dir_all(root).unwrap();
    }

    #[test]
    fn durable_replay_falls_back_to_snapshot_at_memory_bound() {
        let root =
            std::env::temp_dir().join(format!("asp-durable-replay-bound-{}", Uuid::new_v4()));
        let session_dir = root.join(".asp/sessions").join(Uuid::new_v4().to_string());
        std::fs::create_dir_all(&session_dir).unwrap();
        let log_path = session_dir.join("events.log");
        let mut bytes = Vec::new();
        bytes.extend_from_slice(EVENT_LOG_MAGIC);
        bytes.extend_from_slice(&EVENT_LOG_VERSION.to_be_bytes());
        for id in 1..=MAX_DURABLE_REPLAY_EVENTS as u64 + 1 {
            let event = Event {
                id,
                unix_ms: id,
                kind: EventKind::PtyStateAdvanced { generation: id },
            };
            let payload = asp_protocol::encode_message(&event).unwrap();
            bytes.extend_from_slice(&(payload.len() as u32).to_be_bytes());
            bytes.extend_from_slice(&crc32(&payload).to_be_bytes());
            bytes.extend_from_slice(&payload);
        }
        std::fs::write(&log_path, &bytes).unwrap();
        let before = std::fs::metadata(&log_path).unwrap().len();
        let (disk, _loaded) = SessionDisk::open(&session_dir).unwrap();
        assert!(disk.read_events_since(0).unwrap().is_none());
        // Hitting the replay budget is an application-level compaction
        // decision, never permission to truncate a valid active WAL.
        assert_eq!(std::fs::metadata(&log_path).unwrap().len(), before);
        std::fs::remove_dir_all(root).unwrap();
    }

